// Öğrenme yollarında anlama ve tedebbür katmanı: ikinci kuşak yollar (yollar-2.js).
// Alanlar yollar-ek.js ile aynıdır.
window.YOL_EK = window.YOL_EK || {};
Object.assign(window.YOL_EK, {
  "kuran-ilimleri": {
    buyukResim: "Bir âyeti okuduğunda onu yalnızca mealinden anlıyorsan, aslında büyük bir binanın yalnızca cephesine bakıyorsun. Bu yol, o binanın taşıyıcı sütunlarını tanıtır. Önce vahyin ne olduğunu ve Kur'an'ın nasıl indiğini, yazıldığını ve toplandığını görürsün. Sonra bir âyetin anlamını belirleyen bağlamları öğrenirsin: iniş sebebi, nesih, açıklık ve kapalılık. Ardından lafzın ve nazmın inceliklerine geçersin: kıraatler, âyetler arası bağ, i'câz ve te'vîl. En sonda bu ilimlerin hepsini kullanarak Kur'an'ı tefsir etmiş büyük müfessirlerle tanışırsın ve her birinin Kur'an'a hangi pencereden baktığını görürsün.",
    hedefler: ["Bir âyeti anlamak için hangi ilimlere başvurulduğunu sayabilmek ve her birinin anlama nasıl katkı yaptığını açıklayabilmek.", "Rivayet, dil, kelâm ve işaret tefsirlerinin farklı yöntemlerini ayırt edebilmek.", "Bir tefsir okurken müfessirin hangi usul tercihlerini yaptığını fark edebilmek.", "Kur'an'ı okurken bağlam, nazım ve âyetler arası bağı gözeten bir dikkat geliştirebilmek."],
    sure: "Yaklaşık 3 hafta; günde 1 adım", onbilgi: "Gerekmez; Arapça bilgisi faydalıdır ama şart değildir.",
    etaplar: [
      ["Vahiy ve iniş", 0, 2, "Vahyin bir tecrübe olarak ağırlığı, Kur'an'ın parça parça inişi ve sahabenin onu titizlikle toplaması arasında nasıl bir bağ görüyorsun? Bu üç adım, metne duyulan güvenin temelini nasıl kuruyor?"],
      ["Âyetin bağlamı ve hükmü", 3, 5, "İniş sebebi, nesih ve muhkem-müteşâbih ayrımı, bir âyetin anlamını farklı yönlerden sınırlar veya genişletir. Bu üç ilmin her biri bir âyeti yanlış anlamaktan seni nasıl korur?"],
      ["Lafız, nazım ve mana", 6, 9, "Kıraatlerin çeşitliliği, âyetler arası bağ ve i'câz, Kur'an'ın lafzına gösterilen hassasiyeti anlatır. Te'vîl ise o lafızdan mana çıkarmanın sınırını çizer. Lafza bağlılık ile yorum özgürlüğü arasındaki dengeyi nasıl kurarsın?"],
      ["Müfessirler ve yöntemler", 10, 15, "Taberî rivayetle, Zemahşerî belâgatle, Râzî kelâmla, işârî müfessirler kalple, Elmalılı da bütün bunları Türkçeyle birleştirerek okudu. Bu yöntemlerden hangisi seni en çok cezbetti ve neden?"]
    ],
    adim: {
      0: { amac: "Vahyin mahiyetini ve Kur'an'ın diğer bilgi türlerinden farkını kavramak.", odak: "Vahiy bir “bilgi aktarımı” mıdır, yoksa bir “karşılaşma” mı?",
        not: "Hâris b. Hişâm, Hz. Peygamber'e vahyin nasıl geldiğini sorduğunda şu cevabı almıştır: “Bazen çan sesine benzer bir sesle gelir; bu bana en ağır gelenidir. Sonra benden ayrılır, ben de söyleneni belleğime almış olurum. Bazen de melek bana bir adam suretinde görünür, benimle konuşur, ben de söylediğini ezberlerim.” Hz. Âişe de çok soğuk günlerde vahiy geldiğini, vahiy bittiğinde Hz. Peygamber'in alnından ter aktığını görmüştür (Buhârî). Müzzemmil 5'teki “Biz sana ağır bir söz bırakacağız” âyeti, vahyin hem bedenen hem manen taşınması güç bir emanet olduğunu bildirir.",
        tedebbur: [["Vahyin Hz. Peygamber'e “ağır” gelmesi, Kur'an'ı okurken senin ona nasıl yaklaşman gerektiği hakkında ne söylüyor?", "Bir sözün ağırlığının, onu taşıyanın dikkatini ve hazırlığını nasıl değiştirdiğini düşün."], ["Kur'an'ın “okunan vahiy”, sünnetin ise “okunmayan vahiy” olarak nitelenmesi, iki kaynağa bakışını nasıl etkiler?", "Lafzın da mananın da Allah'tan olması ile mananın Allah'tan, lafzın Peygamber'den olmasının farkını düşün."]] },
      1: { amac: "Kur'an'ın iniş sürecini ve Mekkî-Medenî ayrımının anlama katkısını görmek.", odak: "Kur'an neden bir kerede değil, yirmi üç yılda indi?",
        not: "Kur'an hem “Ramazan ayında indirildi” (Bakara 185), “Kadir gecesinde indirildi” (Kadir 1) diye anılır hem de yirmi üç yıl boyunca parça parça inmiştir. Müfessirler bu iki bilgiyi İbn Abbâs'tan gelen bir rivayetle uzlaştırır: Kur'an önce Kadir gecesinde Levh-i Mahfûz'dan dünya semasındaki “Beytü'l-izze”ye toptan indirilmiş, sonra olaylara göre Hz. Peygamber'e parça parça indirilmiştir (Nesâî, Hâkim). Böylece Kur'an'ın bir bütün olarak tamamlanmış olması ile hayatın içinde, sorulara ve olaylara cevap vererek inmesi birlikte korunmuş olur.",
        tedebbur: [["Kur'an'ın olaylara ve sorulara cevap olarak inmesi, onu bugün okurken kendi hayatının olaylarıyla nasıl ilişkilendirmeni sağlar?", "Furkān 32'deki “kalbini sağlamlaştırmak için” gerekçesini düşün; parça parça inişin bir terbiye yöntemi olduğunu fark et."], ["Mekkî surelerin önce imanı, Medenî surelerin sonra hükümleri inşa etmesi, bir insanın veya toplumun dinî terbiyesinde nasıl bir sıra önerir?", "Hz. Âişe'nin “İlk inenler cennet ve cehennemi anlatan surelerdi; insanlar İslâm'a ısınınca helal ve haram indi” sözünü düşün."]] },
      2: { amac: "Kur'an metninin nasıl korunup toplandığını öğrenmek.", odak: "Sahabe, Kur'an'ı toplarken hangi titizliği gösterdi?",
        not: "Hz. Ebû Bekir, Kur'an'ı toplama görevini Zeyd b. Sâbit'e verdiğinde Zeyd şöyle demişti: “Allah'a yemin ederim ki, bir dağı yerinden taşımayı bana yükleselerdi, bu bana Kur'an'ı toplamaktan daha ağır gelmezdi.” Zeyd, kendisi hâfız olduğu hâlde, her âyeti hem yazılı bir belgeden hem de ezberlerden doğrulayarak topladı. Tevbe suresinin son iki âyetini yazılı olarak yalnızca Ebû Huzeyme el-Ensârî'nin yanında bulduğunu anlatır (Buhârî). Bu titizlik, ezber ile yazının birbirini denetlediği bir koruma sistemini gösterir.",
        tedebbur: [["Zeyd b. Sâbit'in bu görevi “bir dağı taşımaktan” daha ağır bulması, Kur'an metnine duyulan sorumluluk hakkında ne söylüyor?", "Kendisi hâfız olduğu hâlde her âyeti ayrıca belgeyle doğrulamasının anlamını düşün."], ["Hz. Osman'ın mushafları çoğaltması, ümmetin birliğini korumak ile okuma farklılıklarına izin vermek arasında nasıl bir denge kurdu?", "Farklı bölgelerdeki okuma ihtilaflarının bir fitneye dönüşme tehlikesini ve Osman mushaflarının bazı kıraat farklarını taşıyabilecek şekilde yazılmasını düşün."]] },
      3: { amac: "İniş sebebinin bir âyeti anlamadaki rolünü kavramak.", odak: "İniş sebebini bilmeden bir âyeti yanlış anlamak mümkün mü?",
        not: "Urve b. Zübeyr, teyzesi Hz. Âişe'ye Bakara 158'i sordu: “Safa ve Merve Allah'ın nişanelerindendir; kim hac veya umre yaparsa onları tavaf etmesinde bir günah yoktur.” Urve, âyetin zahirinden Safa ile Merve arasında sa'y etmemenin de bir sakıncası olmadığı sonucunu çıkarmıştı. Hz. Âişe bunun yanlış olduğunu söyledi ve âyetin iniş sebebini anlattı: Ensar, İslâm'dan önce Safa ile Merve'deki putlar yüzünden orada sa'y etmekten çekiniyordu; âyet bu çekinceyi gidermek için inmiştir (Buhârî, Müslim). “Günah yoktur” ifadesi, bir zorunluluğun değil, bir çekincenin cevabıdır.",
        tedebbur: [["Urve gibi büyük bir âlimin bile iniş sebebini bilmeden âyeti yanlış anlaması, bugün meallerden hüküm çıkarmanın riskleri hakkında ne söylüyor?", "Âyetin hangi soruya veya kaygıya cevap verdiğini bilmenin, onun ne söylediğini nasıl değiştirdiğini düşün."], ["“Sebebin özel olması değil, lafzın genel olması esastır” kaidesi ile iniş sebebinin anlamı sınırlaması arasındaki dengeyi nasıl kurarsın?", "Sebebin âyetin anlamını açıklayan bir anahtar olduğunu, ama hükmünü yalnız o olayla sınırlamadığını düşün."]] },
      4: { amac: "Nesih kavramını ve tartışmalarını öğrenmek.", odak: "Bir âyetin hükmünün kaldırılması, Kur'an'ın değişmezliğiyle nasıl bağdaşır?",
        not: "Usulcüler Kur'an'daki neshi üç türe ayırır: hem lafzı hem hükmü kaldırılan, lafzı kalıp hükmü kaldırılan ve hükmü kalıp lafzı kaldırılan. Bu sınıflandırma, “Biz bir âyeti neshedersek veya unutturursak, ondan daha hayırlısını veya benzerini getiririz” (Bakara 106) âyetine dayanır. Neshin ilmî önemine dair Hz. Ali'den şu olay nakledilir: Kûfe mescidinde halka vaaz veren birine nâsih ve mensûhu bilip bilmediğini sordu; adam bilmediğini söyleyince “Hem kendini helak ettin hem de başkalarını” dedi. Nesih bilgisi, bir hükmü yürürlükten kalkmış bir âyete dayandırma hatasından korur.",
        tedebbur: [["İçki yasağının aşamalı gelmesi, insanın ve toplumun alışkanlıklarını değiştirmede nasıl bir hikmet gösteriyor?", "Kendi hayatında bir alışkanlığı aşamalı olarak değiştirdiğin bir tecrübeyi düşün."], ["Ebû Müslim el-İsfahânî'nin Kur'an'da nesih bulunmadığını savunması ile cumhurun görüşü arasında, Kur'an'a saygı bakımından bir fark var mı?", "İki tarafın da Kur'an'ın tutarlılığını korumaya çalıştığını, ama bunu farklı yollarla yaptığını düşün."]] },
      5: { amac: "Muhkem ve müteşâbih ayrımının Kur'an'ı okumadaki işlevini kavramak.", odak: "Anlamı kapalı âyetlere nasıl yaklaşmalıyım?",
        not: "Kur'an kendisini üç farklı şekilde niteler: Bir yerde bütün âyetlerinin “muhkem kılındığını” (Hûd 1), başka bir yerde bütün olarak “müteşâbih”, yani birbirine benzeyen, birbirini doğrulayan bir kitap olduğunu (Zümer 23), Âl-i İmrân 7'de ise bir kısmının muhkem, bir kısmının müteşâbih olduğunu söyler. Âlimler bunu şöyle açıklar: Bütün Kur'an sağlamlık bakımından muhkem, güzellik ve tutarlılık bakımından müteşâbihtir; özel anlamdaki ayrım ise mananın açıklığıyla ilgilidir. Hz. Âişe, Âl-i İmrân 7'yi okuduktan sonra Hz. Peygamber'in şöyle buyurduğunu nakleder: “Müteşâbihin peşine düşenleri gördüğünüzde, bilin ki Allah'ın adını verdikleri onlardır; onlardan sakının” (Buhârî, Müslim).",
        tedebbur: [["Âl-i İmrân 7'ye göre müteşâbihin peşine düşmenin sebebi “kalplerdeki eğrilik”tir. Kapalı bir âyete yaklaşırken kendi niyetini nasıl sınarsın?", "Bir âyeti anlamaya çalışmak ile ondan önceden belirlenmiş bir sonuca destek aramak arasındaki farkı düşün."], ["Âyetin sonundaki “Derin ilim sahipleri ‘Ona inandık, hepsi Rabbimizin katındandır’ derler” ifadesi, bilginin sınırına gelindiğinde nasıl bir tavır öneriyor?", "Anlayamadığın bir şey karşısında teslimiyet ile araştırmayı bırakmak arasındaki farkı düşün."]] },
      6: { amac: "Kıraatlerin kaynağını ve mana zenginliğine katkısını görmek.", odak: "Farklı okuyuşlar bir çelişki midir, yoksa bir zenginlik mi?",
        not: "Kıraatleri yedi imamla sınırlayan ilk kişi, Bağdatlı âlim İbn Mücâhid'dir (ö. 324/936). Daha sonra İbnü'l-Cezerî, bir kıraatin sahih sayılması için üç şart belirlemiştir: Arapçaya uygun olması, Hz. Osman'ın mushaflarından birinin yazısına, ihtimal yoluyla da olsa, uygun düşmesi ve sahih bir senetle nakledilmesi. Kıraat farklılıkları mana zenginliği de taşır: Fâtiha'daki kelime bir kıraatte “Mâliki” (din gününün sahibi), bir kıraatte “Meliki” (din gününün hükümdarı) diye okunur. İki okuyuş birlikte, Allah'ın o günün hem sahibi hem de hükümdarı olduğunu bildirir.",
        tedebbur: [["“Mâlik” ile “Melik” okuyuşlarının birlikte verdiği anlam, Kur'an'ın lafzındaki genişlik hakkında sana ne düşündürüyor?", "Bir sözün iki farklı okunuşunun birbirini tamamlayan iki hakikati anlatabileceğini düşün."], ["Kıraat farklarının tevâtürle nakledilmesi, Kur'an'ın korunmuşluğu ile nasıl bağdaşır?", "Korunmuşluğun tek bir okuyuş değil, Hz. Peygamber'den gelen bütün okuyuşların korunması anlamına geldiğini düşün."]] },
      7: { amac: "Âyetler arasındaki bağı aramanın tefsirdeki yerini öğrenmek.", odak: "Bir âyet neden tam da o yerde duruyor?",
        not: "Münasebet ilminin en çarpıcı örneklerinden biri Bakara 238'dir: Talak, iddet ve mehir hükümlerinin anlatıldığı âyetlerin tam ortasında birden “Namazlara ve orta namaza devam edin; Allah'a gönülden boyun eğerek kalkın” emri gelir. Ardından yine aile hükümlerine dönülür. Müfessirler bu yerleşimi şöyle açıklar: Ayrılık ve anlaşmazlık anlarında insanın kalbi katılaşır ve haksızlığa meyleder; namaz, kalbi Allah'a bağlayarak bu hükümleri adaletle uygulamayı mümkün kılar. Hemen önceki âyette de “Aranızdaki iyiliği unutmayın” (Bakara 237) denmiştir. Zerkeşî, münasebetin bir akıl ilmi olduğunu ve akla arz edildiğinde akıl tarafından kabul edildiğini söyler.",
        tedebbur: [["Bakara 238'in aile hükümleri arasına yerleştirilmesi, kendi hayatındaki çatışma anlarında namazın yeri hakkında sana ne söylüyor?", "Bir anlaşmazlığın ortasında namaz kılmanın, öfkeyi ve kararı nasıl değiştirebileceğini düşün."], ["Münasebet ararken zorlama bir bağ kurmaktan nasıl kaçınırsın?", "İzz b. Abdisselâm'ın uyarısını hatırla: Farklı zamanlarda farklı sebeplerle inen âyetler arasında her zaman sıkı bir bağ aranmaz."]] },
      8: { amac: "Kur'an'ın i'câzını, onunla karşılaşan ilk muhatapların tecrübesi üzerinden görmek.", odak: "Kur'an'ın etkisi, ona inanmayanlar tarafından bile nasıl tarif edildi?",
        not: "Mekke'nin önde gelen müşriklerinden Velîd b. Muğîre, Kur'an'ı dinledikten sonra kavmine şöyle dediği nakledilir: “Onda bir tatlılık, üzerinde bir parlaklık var. Altı verimli, üstü meyvelidir. O yükselir, onun üzerine çıkılmaz” (Hâkim, Beyhakî). Ancak kavminin baskısı üzerine bunun “nakledilen bir sihir” olduğunu söylemeye karar verdi. Müddessir 18-25. âyetler bu kararın anını tasvir eder: “O düşündü ve ölçtü... Sonra baktı, sonra kaşlarını çattı ve surat astı, sonra sırt çevirdi ve büyüklendi; ‘Bu, nakledilen bir sihirden başka bir şey değildir’ dedi.”",
        tedebbur: [["Velîd, Kur'an'ın üstünlüğünü fark ettiği hâlde kibri yüzünden onu reddetti. Hakikati tanımak ile ona teslim olmak arasındaki mesafe hakkında bu ne söylüyor?", "Bir gerçeği kabul etmemize engel olan şeyin bazen bilgisizlik değil, bir kayıp korkusu veya kibir olduğunu düşün."], ["Kur'an'ın i'câzını bugün hangi yönüyle en çok hissediyorsun: dili, haberleri, insan ruhuna etkisi?", "Kendi okumanda seni en çok etkileyen bir âyeti ve onun seni neden etkilediğini düşün."]] },
      9: { amac: "Tefsir ile te'vîlin sınırını ve yorumun meşruiyet şartlarını öğrenmek.", odak: "Bir âyete yorum getirirken nerede durmalıyım?",
        not: "Kur'an'da “te'vîl” kelimesi çoğunlukla bir sözün yorumunu değil, bir şeyin varacağı yeri, gerçekleşmesini anlatır. Hz. Yûsuf, ailesi önünde secdeye kapandığında “Babacığım, bu daha önce gördüğüm rüyanın te'vîlidir” der (Yûsuf 100); yani rüya gerçekleşmiştir. A'râf 53'te de inkârcıların “Kur'an'ın te'vîlini”, yani haber verdiği şeylerin gerçekleşmesini beklediği söylenir. Hz. Peygamber'in İbn Abbâs için “Allah'ım, onu dinde fakih kıl ve ona te'vîli öğret” diye dua ettiği nakledilir (Ahmed). Te'vîl, kelimenin kök anlamıyla, sözü varacağı asıl hedefe döndürmektir.",
        tedebbur: [["“Te'vîl”in bir sözün varacağı yer anlamına gelmesi, Kur'an'ı okurken âyetlerin senin hayatında nereye varacağını düşünmeye nasıl davet ediyor?", "Bir âyeti anlamak ile onun hayatında gerçekleşmesini görmek arasındaki farkı düşün."], ["Mâtürîdî'nin kesin bilgiye dayanmayan yorumlarında “Allah bunu kastetti” demekten kaçınması, yorum yaparken nasıl bir edep öğretiyor?", "Kendi anladığın ile Allah'ın muradını eşitlemenin tehlikesini düşün."]] },
      10: { amac: "Tefsirin kaynaklarını ve müfessirde aranan donanımı öğrenmek.", odak: "Kur'an hakkında konuşmak için ne bilmek gerekir?",
        not: "Hz. Ebû Bekir'e Abese 31'deki “ve fâkiheten ve ebbâ” ifadesindeki “ebb” kelimesinin anlamı sorulduğunda şöyle dediği nakledilir: “Allah'ın kitabı hakkında bilmediğim bir şey söylersem, hangi yer beni taşır, hangi gök beni gölgeler?” Hz. Ömer'in de aynı kelime üzerinde düşündüğü, sonra “Bu, kendini zorlamaktır” diyerek bıraktığı rivayet edilir (Ebû Ubeyd, Fezâilü'l-Kur'ân). Kur'an'ın inişine bizzat şahit olan bu iki sahabinin tutumu, bilmediği konuda susmanın bir ilim edebi olduğunu gösterir.",
        tedebbur: [["Ebû Bekir ve Ömer'in bilmedikleri bir kelime hakkında konuşmaktan kaçınması, bugün Kur'an hakkında kolayca hüküm verme eğilimine nasıl bir ayna tutuyor?", "Bilgisiz konuşmanın Kur'an'a karşı bir saygısızlık olabileceğini düşün."], ["Suyûtî'nin müfessir için saydığı ilimlerin sonuncusu “Allah'ın ilmiyle amel edene verdiği ilim”dir (ilm-i mevhibe). Bu, tefsirin yalnızca bir bilgi işi olmadığı hakkında ne söylüyor?", "İlmin amelle birleştiğinde nasıl bir derinlik kazandığını düşün."]] },
      11: { amac: "Rivayet tefsirinin yöntemini en büyük temsilcisinden öğrenmek.", odak: "Taberî, farklı rivayetler arasında nasıl tercih yapar?",
        not: "Hatîb el-Bağdâdî'nin naklettiğine göre Taberî talebelerine “Kur'an'ın tefsirini yazmaya istekli misiniz?” diye sorup tefsirin otuz bin varak tutacağını söylemiş; talebeler bunun bitirilmeden ömürlerin tükeneceğini söyleyince “İnna lillâh! Himmetler ölmüş” demiş ve eseri yaklaşık üç bin varakta özetlemiştir. Tarihi için de aynısını yaşamıştır. Tefsirinin yöntemi, önce âyetin anlamına dair farklı görüşleri senetleriyle nakletmek, sonra “Bize göre bu sözlerin en doğrusu şudur” diyerek gerekçeli bir tercih yapmaktır. Bu, onu yalnızca bir rivayet derleyicisi değil, bir müctehid müfessir yapar.",
        tedebbur: [["Taberî'nin “Himmetler ölmüş” sözü, ilim yolunda büyük hedeflerden korkmak hakkında sana ne söylüyor?", "Kendi ilim hayatında, zorluğu yüzünden vazgeçtiğin bir hedefi düşün."], ["Taberî'nin rivayetleri naklettikten sonra kendi tercihini gerekçesiyle belirtmesi, rivayete saygı ile akıl yürütme arasında nasıl bir denge kurar?", "Görüşleri yalnızca sıralamak ile onları tartıp tercih etmek arasındaki farkı düşün."]] },
      12: { amac: "Belâgatin tefsire nasıl taşındığını görmek.", odak: "Bir kelimenin yeri ve sırası, anlamı nasıl değiştirir?",
        not: "Zemahşerî, Bakara 2'deki “Lâ raybe fîh” (Onda hiçbir şüphe yoktur) ifadesinde ince bir noktaya dikkat çeker: Eğer “fîhi lâ rayb” denseydi, yani “onda” kelimesi öne alınsaydı, bu “Şüphe yalnızca onda yoktur, başka kitaplarda vardır” anlamına gelirdi. Oysa âyetin amacı başka kitaplarla bir kıyas yapmak değil, şüphenin bu kitaptan tamamen uzak olduğunu bildirmektir. Keşşâf, bu tür incelikleri “Eğer dersen ki... derim ki...” şeklindeki soru-cevap üslubuyla işler; bu üslup, okuyucunun aklına gelebilecek soruyu önceden sorarak onu metnin içine çeker.",
        tedebbur: [["Bir kelimenin yalnızca yerinin değişmesinin anlamı bu kadar değiştirmesi, Kur'an'ı mealden okumanın sınırları hakkında sana ne söylüyor?", "Bir çevirinin aslındaki bu tür incelikleri ne ölçüde taşıyabileceğini düşün."], ["Zemahşerî'nin Mu'tezilî olmasına rağmen tefsirinin bütün mezheplerce okunması, ilim geleneğinin farklı görüşteki bir âlime nasıl yaklaştığını gösteriyor?", "Bir eserin faydasını alıp hatasını ayıklamanın, onu tamamen reddetmekten farkını düşün."]] },
      13: { amac: "Kelâm ve felsefeyle zenginleşen bir tefsir anlayışını tanımak.", odak: "Râzî tefsiri neden bu kadar geniş ve tartışmalıdır?",
        not: "Râzî'nin Mefâtîhu'l-gayb'ı hakkında iki meşhur değerlendirme vardır. Bazı âlimler, kelâm, felsefe, tıp ve astronomi tartışmalarıyla dolu olan bu eser için “Onda tefsir dışında her şey var” demiştir. Süyûtî gibi başka âlimler ise bu sözü düzelterek “Onda tefsirle birlikte her şey var” demiştir. Eserin önemli bir kısmının Râzî'nin vefatından sonra talebeleri tarafından tamamlandığı da bilinmektedir. Râzî'nin tefsiri, bir âyetin akla getirebileceği her soruyu sorup cevaplamaya çalışır; bu yüzden hem aklî derinliği hem de dağınıklığı eleştirilmiştir.",
        tedebbur: [["“Tefsir dışında her şey” ile “tefsirle birlikte her şey” değerlendirmeleri arasındaki fark, tefsirin sınırlarının nerede çizilmesi gerektiği hakkında ne söylüyor?", "Bir âyetin etrafındaki bütün soruları tartışmanın onu zenginleştirip zenginleştirmediğini, yoksa ondan uzaklaştırıp uzaklaştırmadığını düşün."], ["Râzî'nin “küllî kanunu” ile İbn Teymiyye'nin buna itirazı, bugünkü bilim ve din tartışmalarına nasıl bir çerçeve sunuyor?", "Akıl ile nakil çatıştığında iki tarafın da yanılıyor olabileceğini hesaba katmanın önemini düşün."]] },
      14: { amac: "İşârî tefsirin imkânlarını ve sınırlarını öğrenmek.", odak: "Bir âyetin zâhirinin ötesinde bir anlam aramak meşru mudur?",
        not: "İşârî tefsirin ilk büyük derlemesi, Ebû Abdurrahmân es-Sülemî'nin Hakāiku't-tefsîr'idir. Bu eser sert tepkilerle karşılaşmıştır: Vâhidî, Sülemî'nin bu yorumları gerçekten tefsir olarak kabul ettiyse küfre girmiş olacağını söyleyecek kadar ileri gitmiştir. İbnü's-Salâh ise daha dengeli bir değerlendirme yapar: Sûfîlerin bu sözleri âyetin tefsiri olarak değil, âyetin hatırlattığı bir mana ve bir benzerlik olarak söylediklerini kabul etmek gerekir. Bu ayrım, işârî yorumun meşruiyet şartının, onu zâhirin yerine koymamak olduğunu gösterir.",
        tedebbur: [["İbnü's-Salâh'ın yaptığı ayrım, kendi Kur'an okumanda aklına gelen kişisel çağrışımları nasıl değerlendirmen gerektiğini gösteriyor?", "Bir âyetin sana hatırlattığı ile o âyetin anlamı arasındaki farkı düşün."], ["“Ayakkabılarını çıkar” emrinin işârî yorumu gibi, okuduğun bir âyetten kendi iç dünyana yönelik bir işaret çıkarmayı dene.", "Zâhiri inkâr etmeden, âyetin kalbine dokunan bir boyutunu aramayı düşün."]] },
      15: { amac: "Klasik tefsir birikiminin Türkçede nasıl yeniden kurulduğunu görmek.", odak: "Kur'an'ı başka bir dile aktarmak mümkün müdür?",
        not: "Elmalılı, eserine “tercüme” değil “meal” demeyi bilinçli olarak tercih etmiştir. Ona göre Kur'an'ın lafzındaki bütün incelikleri, ses ve nazım özellikleriyle birlikte başka bir dile aktarmak mümkün değildir; yapılabilecek olan, anlaşılan manayı yaklaşık olarak ifade etmektir. Tefsirinin adı da bir programı özetler: “Hak Dini”, Kur'an'ın getirdiği dinin hak oluşunu; “Kur'an Dili” ise bu dinin bir dil ve üslup içinde geldiğini ve o dilin incelikleri bilinmeden tam anlaşılamayacağını anlatır.",
        tedebbur: [["Elmalılı'nın “meal” tercihi, kendi Kur'an okumanda bir mealden ne beklemen gerektiği hakkında ne söylüyor?", "Bir mealin seni Kur'an'a yaklaştıran bir kapı mı, yoksa onun yerine geçen bir metin mi olduğunu düşün."], ["Bu yolda tanıdığın ilimlerden hangileri, Elmalılı'nın tefsirinde birleşmiş olabilir?", "Belâgat, kelâm, fıkıh ve felsefenin bir tefsirde nasıl bir araya gelebileceğini düşün."]] }
    },
    sentez: "Kısa bir sure veya sevdiğin bir âyet seç. Bu yolda öğrendiğin ilimleri sırayla uygula: İniş ortamı veya sebebi nedir? Önceki ve sonraki âyetlerle bağı nedir? Bir kelimesinde dikkat çekici bir dil inceliği var mı? Farklı bir kıraat veya yorumu var mı? Sonunda, bu ilimlerin âyeti anlamana neler kattığını kısa bir paragrafla yaz." },

  "hadis-okumak": {
    buyukResim: "Her gün karşımıza “Hz. Peygamber şöyle buyurdu” diye başlayan sözler çıkar. Bunların bir kısmı sahih, bir kısmı zayıf, bir kısmı ise uydurmadır. Bu yol, sana bu sözleri değerlendirmenin yöntemini öğretir. Önce sünnetin dindeki yerini ve bir haberin yapısını görürsün. Sonra ravilerin nasıl değerlendirildiğini ve bir haberin hangi gizli kusurlarla zayıflayabileceğini öğrenirsin. Ardından büyük muhaddislerin bu kuralları nasıl uyguladığını izlersin. En sonda öğrendiklerini, rivayetleri tartışmalı bir akide meselesinde kullanırsın.",
    hedefler: ["Sünnetin bağlayıcılığını ve farklı türlerini açıklayabilmek.", "Bir hadisin sahih, hasen veya zayıf sayılmasının ölçülerini anlayabilmek.", "Muhaddislerin ravi ve metin tenkidi yöntemlerini tanıyabilmek.", "Hadislere ne körü körüne ne de toptan reddederek, ölçülü bir şekilde yaklaşabilmek."],
    sure: "Yaklaşık 3 hafta", onbilgi: "Gerekmez.",
    etaplar: [
      ["Sünnet ve haberin yapısı", 0, 3, "Sünnetin bağlayıcılığı ile bir haberin sahih olup olmadığı ayrı sorulardır. Birincisi “Peygamber'in sözü bağlayıcı mı?”, ikincisi “Bu söz gerçekten onun mu?” sorusudur. Bu ayrım neden önemli?"],
      ["Raviler ve gizli kusurlar", 4, 8, "Sahabenin adâleti, ravi tenkidi, mürsel, illet ve uydurma: Bu beş adım, bir haberin yolculuğundaki hangi tehlikelere karşı alınmış tedbirlerdir?"],
      ["Muhaddislerin yöntemleri", 9, 13, "Buhârî'nin titizliği, Müslim'in tertibi, Tirmizî'nin fıkıhla birleştirmesi, İbnü's-Salâh'ın sistemleştirmesi ve İbn Hacer'in şerhi: Hadis ilmi bu beş âlimde nasıl bir gelişme gösteriyor?"],
      ["Uygulama", 14, 14, "Öğrendiğin usul kurallarını bir akide meselesine uyguladığında, kuralların sonuca nasıl doğrudan etki ettiğini gördün mü?"]
    ],
    adim: {
      0: { amac: "Sünnetin dindeki yerini ve farklı türlerini anlamak.", odak: "Hz. Peygamber'in her davranışı aynı bağlayıcılıkta mıdır?",
        not: "Tâbiûn neslinden bazı âlimler, “Sünnet Kur'an'a hükmeder, Kur'an sünnete değil” sözünü söylemiştir; çünkü sünnet Kur'an'ın mücmelini açıklar, mutlakını kayıtlar. Ahmed b. Hanbel'e bu söz sorulduğunda ise ölçülü bir cevap vermiştir: “Bunu söylemeye cesaret edemem; ama sünnet Kur'an'ı tefsir eder ve açıklar” (İbn Abdilber, Câmiu beyâni'l-ilm). Ahmed'in bu tavrı, sünnetin yerini yüceltirken Kur'an'ın önceliğini koruyan bir dengeyi gösterir.",
        tedebbur: [["Ahmed b. Hanbel'in “cesaret edemem” demesi, büyük bir ilmî iddia karşısında nasıl bir edep öğretiyor?", "Doğru bir manayı ifade ederken bile kelimeleri seçmenin önemini düşün."], ["Hz. Peygamber'in tebliğ, kazâ ve imamet olarak yaptığı tasarrufları ayırmak, bir hadisi bugün nasıl uygulayacağını nasıl etkiler?", "Bir devlet başkanı olarak verdiği bir kararın, bir peygamber olarak bildirdiği bir hükümle aynı kalıcılıkta olup olmadığını düşün."]] },
      1: { amac: "Hadisin temel kısımlarını ve rivayetin amacını öğrenmek.", odak: "Bir hadisi nakletmek ile onu anlamak aynı şey midir?",
        not: "Hz. Peygamber şöyle buyurmuştur: “Benden bir söz işitip onu ezberleyen ve işittiği gibi başkasına ulaştıran kişinin Allah yüzünü ağartsın. Nice fıkıh taşıyan vardır ki kendisi fakih değildir; nice fıkıh taşıyan da onu kendisinden daha fakih olana ulaştırır” (Ebû Dâvûd, Tirmizî). Bu hadis, rivayet ile dirayetin, yani bir sözü doğru nakletmek ile onu derinlemesine anlamanın iki ayrı meleke olduğunu gösterir. Hadis ilmi bu yüzden iki kola ayrılmıştır: Rivayetin doğruluğunu inceleyen usul ve metnin anlamını inceleyen şerh ve fıkıh.",
        tedebbur: [["“Nice fıkıh taşıyan vardır ki kendisi fakih değildir” cümlesi, bir sözü ezberlemek ile anlamak arasındaki fark hakkında sana ne düşündürüyor?", "Bildiğin ama derinliğini henüz kavramadığın bir hadisi düşün."], ["Sahih hadisin beş şartından hangisi sana en çok dikkat gerektiren şart gibi geliyor?", "Senedin bitişikliği, ravinin güvenilirliği, hafızası, daha güvenilirlere aykırı olmaması ve gizli kusur bulunmaması şartlarını karşılaştır."]] },
      2: { amac: "Mütevâtir ve âhâd haberin bilgi değerini ayırt etmek.", odak: "Tek bir kişinin haberiyle amel etmek meşru mudur?",
        not: "Âhâd haberle amel etmenin en güçlü delillerinden biri Kuba olayıdır: Sahabe Kuba mescidinde sabah namazı kılarken bir kişi gelip kıblenin Kâbe'ye çevrildiğini haber verdi. Cemaat, namazın ortasında yüzlerini Kudüs'ten Kâbe'ye çevirdi (Buhârî, Müslim). Hz. Peygamber'in de Muâz b. Cebel'i tek başına Yemen'e, başka sahabileri tek tek farklı kabilelere öğretmen olarak göndermesi, tek kişinin getirdiği bilginin bağlayıcı kabul edildiğini gösterir. Tevâtür için ise âlimler belirli sayılar (dört, beş, on, kırk) önermiş, muhakkikler ise ölçünün sayı değil, kesin bilginin hâsıl olması olduğunu söylemiştir.",
        tedebbur: [["Kuba'daki cemaatin namazın ortasında tek bir kişinin haberiyle kıblesini değiştirmesi, güvenilir bir habere nasıl bir güven duyulduğunu gösteriyor?", "Güvenilir bir kişinin haberine güvenmek ile her habere inanmak arasındaki farkı düşün."], ["Âhâd haberin amelde delil olup akidede tartışılması, bilgi türleri arasındaki ayrım hakkında ne söylüyor?", "Bir işi yapmak için yeterli olan kanaat ile bir inancı kurmak için gereken kesinlik arasındaki farkı düşün."]] },
      3: { amac: "Hadislerin derecelendirilmesini ve sonuçlarını kavramak.", odak: "Buhârî ve Müslim'deki bir hadis kesin bilgi mi ifade eder?",
        not: "İbnü's-Salâh, Buhârî ve Müslim'in birlikte rivayet ettiği hadislerin kesin bilgi ifade ettiğini savunmuştur; çünkü ümmet bu iki kitabı kabul etmiştir (telakkî bi'l-kabûl) ve ümmetin bir hata üzerinde birleşmesi düşünülemez. Nevevî ise bu görüşe itiraz eder: Bu hadisler, mütevâtir olmadıkça zan ifade eder; ümmetin kabulü, onlarla amel etmenin vacip olduğunu gösterir, kesin bilgi ifade ettiklerini değil. Bu tartışma, “sahih” ile “kesin” kavramlarının aynı olmadığını gösterir.",
        tedebbur: [["“Sahih” ile “kesin” arasındaki fark, bir hadise nasıl bir güven duyman gerektiği hakkında ne söylüyor?", "Bir bilginin güvenilir olması ile hiçbir şüpheye yer bırakmaması arasındaki farkı düşün."], ["Zayıf bir hadisi faziletler konusunda kullanmanın şartları, iyi niyetle yanlış bilgi yayma tehlikesine karşı nasıl bir önlem sunuyor?", "Sosyal medyada dolaşan “hadis” sözlerini bu şartlarla değerlendirmeyi düşün."]] },
      4: { amac: "Senedin ilk halkası olan sahabenin konumunu anlamak.", odak: "Kimler sahabi sayılır?",
        not: "Buhârî sahabiyi şöyle tanımlar: “Müslümanlardan Hz. Peygamber'le arkadaşlık eden veya onu gören kimse sahabidir.” Muhaddislerin bu geniş tanımına karşılık bazı fıkıh usulcüleri, sahabi sayılmak için Hz. Peygamber'le uzun süre birlikte bulunmayı şart koşmuştur. Ebû Zür'a er-Râzî'nin, Hz. Peygamber vefat ettiğinde onu görmüş ve ondan rivayet etmiş kimselerin sayısının yüz on dört bini bulduğunu söylediği nakledilir. Vefat eden son sahabinin ise Ebü't-Tufeyl Âmir b. Vâsile (ö. 110 civarı) olduğu kabul edilir.",
        tedebbur: [["Muhaddisler ile usulcülerin sahabi tanımındaki farkı, hangi amaçla tanım yaptıklarına bağlarsan nasıl açıklarsın?", "Rivayetin güvenilirliği ile sahabe sözünün fıkıhtaki bağlayıcılığı için farklı ölçüler gerekebileceğini düşün."], ["Sahabenin adâleti ilkesi, onların hata yapmayacağı anlamına gelmediğine göre, sahabe arasındaki ihtilaflara nasıl bakmalıyız?", "Rivayette güvenilirlik ile ictihadda isabet arasındaki farkı düşün."]] },
      5: { amac: "Ravilerin değerlendirilme yöntemini ve ahlâkını öğrenmek.", odak: "Bir insanı eleştirmek hangi durumda meşrudur?",
        not: "Ravi tenkidi, gıybet yasağıyla çatışıyor gibi görünür. Muhaddisler bu tenkidi, dini korumak için gerekli bir “nasihat” olarak görmüştür. Yahyâ b. Saîd el-Kattân'a, “Rivayetlerini terk ettiğin bu insanların kıyamet günü senin hasmın olmasından korkmaz mısın?” diye sorulduğunda şöyle cevap verdiği nakledilir: “Onların benim hasmım olması, Resûlullah'ın ‘Hakkımda yalan söylendiğini gördüğün hâlde neden onu savunmadın?’ diyerek hasmım olmasından bana daha sevimlidir” (İbn Ebî Hâtim, el-Cerh ve't-ta'dîl mukaddimesi).",
        tedebbur: [["Kattân'ın cevabı, bir insanı eleştirmenin ne zaman bir görev hâline geldiği hakkında ne söylüyor?", "Eleştirinin kişisel bir duyguya değil, korunması gereken bir değere dayanmasının önemini düşün."], ["Akranlar arasındaki rekabetten doğan cerhlerin dikkate alınmaması kuralı, bugün insanlar hakkındaki değerlendirmelerimize nasıl bir ölçü sunuyor?", "Bir eleştirinin arkasındaki niyeti ve ilişkiyi sorgulamanın önemini düşün."]] },
      6: { amac: "Mürsel hadisin delil değeri tartışmasını öğrenmek.", odak: "Senedde bir halka eksikse, haber değerini kaybeder mi?",
        not: "Ebû Dâvûd, Mekke halkına yazdığı ve Sünen'inin yöntemini açıkladığı risalesinde şöyle der: “Mürsel hadislerle geçmişte Süfyân es-Sevrî, Mâlik ve Evzâî gibi âlimler delil getirirdi. Nihayet Şâfiî geldi ve bu konuda konuştu; Ahmed b. Hanbel ve başkaları da ona uydu.” Bu tespit, mürselin reddedilmesinin ilk dönemden beri var olan bir kural değil, usulün sistemleşmesiyle ortaya çıkan bir gelişme olduğunu gösterir. Hanefî ve Mâlikîlerin mürseli kabul etmesi, bu eski uygulamanın devamıdır.",
        tedebbur: [["Mürselin kabulünün zamanla değişmesi, ilim usullerinin de tarihî bir gelişim geçirdiği hakkında ne söylüyor?", "Bir kuralın sonradan sistemleşmesinin, onun daha önce bilinmediği anlamına gelip gelmediğini düşün."], ["Güvenilir bir ravinin senedi atlamasını “kesin bildiği için atladı” şeklinde yorumlamak ikna edici mi?", "Hanefîlerin gerekçesi ile muhaddislerin “aradaki kişiyi bilmiyoruz” itirazını karşılaştır."]] },
      7: { amac: "Hadis ilminin en ince dalı olan ilel ilmini tanımak.", odak: "Görünüşte kusursuz bir rivayetin gizli bir kusuru nasıl fark edilir?",
        not: "Abdurrahmân b. Mehdî şöyle demiştir: “Bir hadisin illetini bilmek, bana yeni yirmi hadis yazmaktan daha sevimlidir.” Yine ondan şu söz nakledilir: “Hadisin illetini bilmek bir ilhamdır. İlleti bilen âlime ‘Bunu nereden biliyorsun?’ diye sorsan, bir delil getiremeyebilir.” Bu sözler, ilel ilminin yalnızca kuralları uygulamakla değil, binlerce rivayetle uzun bir uğraşın kazandırdığı bir sezgi ve melekeyle yapıldığını gösterir. Tıpkı bir sarrafın sahte parayı elinde tartarak tanıması gibi.",
        tedebbur: [["İlel bilgisinin bir “meleke” olması, uzmanlık ve sezginin ilimdeki yeri hakkında sana ne söylüyor?", "Bir alanda uzun süre çalışan birinin, kurallarla açıklayamadığı bir hatayı nasıl fark edebildiğini düşün."], ["Bir hadisin bütün yollarını toplamadan illetini tespit etmenin mümkün olmaması, hüküm vermeden önce araştırmanın önemi hakkında ne söylüyor?", "Tek bir kaynağa bakarak kesin bir hüküm vermenin risklerini düşün."]] },
      8: { amac: "Uydurma hadisleri tanımanın yollarını öğrenmek.", odak: "Senedine bakmadan bir hadisin uydurma olduğu anlaşılabilir mi?",
        not: "İbnü'l-Kayyim, el-Menârü'l-münîf adlı eserinde senedine bakmadan bir rivayetin uydurma olduğunu gösteren işaretleri sayar: Küçük bir amel için akıl almaz büyüklükte sevap vaat edilmesi; duyulara veya apaçık akla aykırılık; Kur'an'ın veya sahih sünnetin açık ifadesiyle çelişme; tarih bakımından tutarsızlık; ve Hz. Peygamber'in sözüne benzemeyen, sanatlı ama rekik bir üslup. Bu ölçüler, metin tenkidinin muhaddislerin gündeminde olduğunu ve senet tenkidinin tek yöntem olmadığını gösterir.",
        tedebbur: [["İbnü'l-Kayyim'in ölçülerini, karşılaştığın yaygın bir “hadis” sözüne uygula. Hangi işaretleri taşıyor?", "Abartılı sevap vaatleri ve Peygamber'in üslubuna benzemeyen ifadeler üzerinde dur."], ["Bir sözün hadis olarak sabit olmaması, manasının yanlış olduğu anlamına gelmez. Bu ayrımı korumak neden önemli?", "Güzel bir sözü Peygamber'e nispet etmenin, onu güzelleştirmediğini, aksine bir yalan riski taşıdığını düşün."]] },
      9: { amac: "Buhârî'nin titizliğini ve hadis ilmindeki yerini kavramak.", odak: "Buhârî'yi bu kadar güvenilir kılan nedir?",
        not: "Hatîb el-Bağdâdî'nin naklettiğine göre Buhârî Bağdat'a geldiğinde muhaddisler onu sınamak istedi. On kişi seçilip her birine on hadis verildi; hadislerin senetleri ile metinleri birbirine karıştırıldı. Meclis toplandığında her biri kendi hadislerini sordu; Buhârî her birine “Bilmiyorum” dedi. Sonra sırayla dönerek her hadisin doğru senedini doğru metniyle birleştirip yüz hadisin hepsini düzeltti. Hikâye, onun hafızasından çok, hatayı fark etme ve düzeltme yeteneğini gösterir.",
        tedebbur: [["Buhârî'nin önce “Bilmiyorum” demesi, sonra her şeyi düzeltmesi, ilim meclislerinde nasıl bir tavır öğretiyor?", "Hemen cevap vermek yerine bütün tabloyu görüp sonra konuşmanın değerini düşün."], ["Sahîh'in “Kur'an'dan sonra en sahih kitap” kabul edilmesi, onun hiçbir rivayetinin tartışılamayacağı anlamına mı gelir?", "Dârekutnî gibi muhaddislerin bazı rivayetlere yönelttiği eleştirileri ve bunlara verilen cevapları düşün."]] },
      10: { amac: "Müslim'in yöntemini ve rivayet geleneğinin ilkelerini öğrenmek.", odak: "Müslim Sahîh'ine neden uzun bir mukaddime yazdı?",
        not: "Müslim, Sahîh'inin mukaddimesinde isnadın önemini anlatan sözleri toplar. İbn Sîrîn'in şu sözü bunların başındadır: “Önceleri isnad sorulmazdı. Fitne çıkınca ‘Ravilerinizi bize söyleyin’ denmeye başlandı. Ehl-i sünnetten olanların hadisi alındı, bid'at ehlinin hadisi alınmadı.” Abdullah b. Mübârek de şöyle der: “İsnad dindendir. İsnad olmasaydı, dileyen dilediğini söylerdi.” Müslim aynı mukaddimede “Her duyduğunu anlatması, kişiye yalancılık olarak yeter” hadisini de nakleder.",
        tedebbur: [["“Her duyduğunu anlatması, kişiye yalancılık olarak yeter” hadisi, bugünkü bilgi paylaşma alışkanlıklarımıza nasıl bir uyarı yapıyor?", "Doğruluğunu bilmediğin bir haberi paylaşmanın sorumluluğunu düşün."], ["İsnadın fitneden sonra sorulmaya başlanması, güvenin sarsıldığı dönemlerde bilginin kaynağını sorgulamanın önemi hakkında ne söylüyor?", "Bir bilginin kimden geldiğini sormanın, ona saygısızlık değil, ona gösterilen özen olduğunu düşün."]] },
      11: { amac: "Hadis ile fıkhı birleştiren yöntemi tanımak.", odak: "Bir hadisin sahih olması, onunla amel edildiği anlamına gelir mi?",
        not: "Tirmizî, Câmi'inin sonundaki el-İlel bölümünde dikkat çekici bir tespit yapar: Kitabındaki bütün hadislerle âlimlerin amel ettiğini, yalnızca iki hadisin istisna olduğunu söyler. Bunlardan biri İbn Abbâs'ın, Hz. Peygamber'in Medine'de korku ve yağmur olmadan namazları cem ettiğine dair rivayetidir. Bu tespit, bir hadisin sahih olması ile onunla fiilen amel edilmesinin farklı şeyler olduğunu ve fakihlerin bir hadisi uygularken başka delilleri de gözettiğini gösterir.",
        tedebbur: [["Sahih bir hadisle amel edilmemesi, fakihlerin hadise saygısızlığı mı, yoksa onu diğer delillerle birlikte okuma çabası mı?", "Cem meselesini hatırla: Fakihler bu hadisi namaz vakitlerini belirleyen kesin delillerle birlikte değerlendirdiler."], ["Tirmizî'nin her bâbın sonunda fukahanın amelini bildirmesi, hadis okurken nasıl bir alışkanlık edinmen gerektiğini gösteriyor?", "Bir hadisi okuduktan sonra âlimlerin onu nasıl anladığını ve uyguladığını sormayı düşün."]] },
      12: { amac: "Hadis usulünün sistemleşmesini görmek.", odak: "Bir ilim nasıl sistemli bir hâle gelir?",
        not: "İbnü's-Salâh'ın Mukaddime'si, kendisinden sonraki hadis usulü literatürünün merkezi hâline gelmiştir. Nevevî onu et-Takrîb adıyla özetlemiş, Süyûtî bu özeti Tedrîbü'r-râvî ile şerh etmiştir. Zeynüddin el-Irâkī, Mukaddime'yi bin beyitlik bir manzume (Elfiyye) hâline getirmiş, bu manzume de Sehâvî tarafından şerh edilmiştir. İbn Hacer ise Mukaddime üzerine tenkitli notlar (en-Nüket) yazmıştır. Bu zincir, klasik ilim geleneğinin bir temel metin etrafında özet, şerh, nazım ve tenkit yoluyla nasıl geliştiğini gösterir.",
        tedebbur: [["Bir temel metnin özet, şerh, nazım ve tenkitle sürekli yeniden işlenmesi, ilmin nesiller boyunca nasıl canlı tutulduğu hakkında ne söylüyor?", "Bir eseri ezberlemek, açıklamak ve eleştirmek arasındaki farklı katkıları düşün."], ["İbnü's-Salâh'ın kendi döneminde yeni bir hadisi tashih etmenin zor olduğunu söylemesi, ilmî tevazu mu, yoksa ictihad kapısını daraltma mı?", "Sonraki âlimlerin bu görüşe nasıl itiraz ettiğini ve tashih yapmaya devam ettiğini düşün."]] },
      13: { amac: "Hadis şerhinin ve savunusunun zirvesini tanımak.", odak: "Buhârî'ye yöneltilen eleştiriler nasıl cevaplandı?",
        not: "Dârekutnî, et-Tetebbu' adlı eserinde Buhârî ve Müslim'in Sahîh'lerindeki yaklaşık iki yüz rivayete senet bakımından eleştiriler yöneltmiştir. İbn Hacer, Fethu'l-bârî'nin mukaddimesi olan Hedyü's-sârî'de bu eleştirileri tek tek ele alır: Bir kısmının yerinde olmadığını gösterir, bir kısmında Buhârî'nin rivayeti başka yollarla desteklediğini ortaya koyar, bir kısmında ise eleştirinin isabetli olduğunu, ancak bunun hadisin metnine zarar vermediğini kabul eder. Bu tavır, en güvenilir kitabın bile eleştiriye açık olduğunu ve eleştiriye ilmî bir yöntemle cevap verilmesi gerektiğini gösterir.",
        tedebbur: [["İbn Hacer'in Buhârî'ye yönelik eleştirilerin bir kısmını kabul etmesi, bir esere duyulan saygı ile ilmî dürüstlük arasındaki dengeyi nasıl gösteriyor?", "Sevdiğin bir eseri veya kişiyi savunurken haklı eleştirileri kabul etmenin önemini düşün."], ["Hadislerin bütün yollarını toplayıp birlikte değerlendirmek, tek bir rivayete takılıp kalmaktan nasıl korur?", "Fethu'l-bârî'nin bir hadisin bütün varyantlarını bir araya getirme yöntemini düşün."]] },
      14: { amac: "Öğrenilen usul kurallarını tartışmalı bir akide meselesine uygulamak.", odak: "Rivayetlerin çokluğu, zayıflıklarını telafi eder mi?",
        not: "Zayıf rivayetlerin birbirini destekleyerek güçlenmesi (taaddüd-i turuk) her durumda geçerli değildir. İbnü's-Salâh'ın açıkladığı gibi, zayıflık ravinin hafızasının zayıflığından veya senetteki küçük bir kopukluktan kaynaklanıyorsa, farklı yollar birbirini destekleyerek hadisi hasen derecesine çıkarabilir. Ancak zayıflık ravinin yalancılıkla itham edilmesinden veya fâsıklığından kaynaklanıyorsa, bu tür yolların çokluğu hadisi güçlendirmez. Mehdi rivayetleri tartışmasında iki tarafın ayrıldığı noktalardan biri de budur.",
        tedebbur: [["Zayıflığın türüne göre yolların çokluğunun farklı sonuç vermesi, “çok kişi söylüyor” gerekçesinin sınırları hakkında ne söylüyor?", "Aynı yanlış bilginin farklı kişilerce tekrar edilmesinin onu doğru yapmadığını düşün."], ["Bu yolda öğrendiğin kurallardan hangisi, Mehdi meselesinde sana en çok yol gösterdi?", "Mütevâtir ve âhâd ayrımını, cerh kurallarını ve tarihî bağlamı düşün."]] }
    },
    sentez: "Sosyal medyada veya bir sohbette karşılaştığın bir “hadis” seç. Bu yolda öğrendiğin adımları uygula: Hangi kaynakta geçiyor? Senedi hakkında âlimler ne demiş? Metni Kur'an'a, sahih sünnete ve akla uygun mu? İbnü'l-Kayyim'in uydurma işaretlerinden birini taşıyor mu? Sonunda bu sözü başkalarıyla paylaşırken nasıl bir dil kullanman gerektiğini yaz." },
  tasavvuf: {
    buyukResim: "Cibrîl hadisinde din üç katlı bir bina olarak anlatılır: İslâm, iman ve ihsan. Fıkıh birinci katın, kelâm ikinci katın ilmidir; tasavvuf ise kendini üçüncü katın, “Allah'ı görüyormuş gibi kulluk” etmenin ilmi olarak tanımlar. Bu yol, o katın nasıl inşa edildiğini gösterir. Önce ilk zâhidlerin hüzün ve sevgi tecrübesini görürsün. Sonra kalp, nefs, ihlas ve zühd gibi iç dünyanın temel kavramlarını tanırsın. Ardından tasavvufun Muhâsibî, Cüneyd, Kuşeyrî ve Gazâlî eliyle bir ilim olarak nasıl sistemleştiğini izlersin. En sonda velâyet ve vahdet gibi en çok tartışılan kavramlara ve tasavvufun Anadolu'daki sesine ulaşırsın. Bu yolda bilgi biriktirmekten çok, okuduğunu kendi kalbinde aramak önemlidir.",
    hedefler: ["İhsan, nefs, ihlas, zühd, hâl ve makam gibi temel kavramları kendi iç dünyanla ilişkilendirerek açıklayabilmek.", "Tasavvufun şeriatla uyumlu ana çizgisini ve bu çizginin ölçülerini tanıyabilmek.", "Velâyet, kerâmet ve vahdet-i vücûd gibi tartışmalı kavramlara dengeli bir bakış geliştirebilmek.", "Okuduğun bir sözü veya kavramı, kendi ahlâkî hayatında bir uygulamaya dönüştürebilmek."],
    sure: "Yaklaşık 3 hafta; acele etmeden", onbilgi: "Gerekmez.",
    etaplar: [
      ["İhsan ve ilk zâhidler", 0, 2, "Hasan-ı Basrî'nin hüznü ile Râbia'nın sevgisi, ihsanın iki yüzü gibidir: Biri Allah'ın azametinden doğan bir ürperti, diğeri O'nun güzelliğinden doğan bir yakınlık. Senin kulluğunda hangisi daha baskın?"],
      ["İç dünyanın kavramları", 3, 6, "Kalp, nefs, ihlas ve zühd bir zincir oluşturur: Nefsin istekleri kalbi bulandırır, ihlas onu arındırır, zühd ise dünyayı kalpten çıkarır. Bu zincirin en zayıf halkası sende hangisi?"],
      ["Tasavvufun bir ilim olması", 7, 12, "Muhâsibî nefsi tahlil etti, Cüneyd yolu Kitap ve sünnetle sınırladı, Kuşeyrî kavramları tanımladı, Gazâlî ise hepsini fıkıh ve kelâmla birleştirdi. Bu dört adım, tasavvufun dinin içinde meşru bir ilim hâline gelmesini nasıl sağladı?"],
      ["Tartışmalar ve Anadolu", 13, 16, "Velâyet ve vahdet gibi kavramlar tartışmalı olsa da Mevlânâ ve Yunus bu derinliği halkın anlayacağı bir sevgi diline dönüştürdü. Derin bir tecrübeyi sade bir dille anlatmanın değeri nedir?"]
    ],
    adim: {
      0: { amac: "İhsanı dinin üçüncü boyutu olarak kavramak.", odak: "İhsan yalnızca ibadette mi, yoksa her işte mi aranır?",
        not: "Şeddâd b. Evs'in rivayet ettiği bir hadiste Hz. Peygamber şöyle buyurur: “Allah her şeye ihsanı yazmıştır. Öldürdüğünüzde güzel öldürün, kestiğinizde güzel kesin. Biriniz bıçağını bilesin ve kestiği hayvanı rahatlatsın” (Müslim). Bu hadis, ihsanın yalnızca namazdaki bir huşu hâli olmadığını, bir hayvanı keserken bile gözetilmesi gereken bir incelik ve merhamet ahlâkı olduğunu gösterir. İhsan, Allah'ı görür gibi ibadet etmekle başlar; ama her işi O'nun gördüğünü bilerek en güzel şekilde yapmaya kadar uzanır.",
        tedebbur: [["Bir hayvanı keserken bile ihsanın gözetilmesi emredilmişse, senin gündelik işlerinde ihsanı nasıl uygularsın?", "Mesleğindeki bir işi, Allah'ın gördüğünü bilerek “en güzel şekilde” yapmanın ne anlama geldiğini düşün."], ["İhsanın iki derecesi, müşahede ve murakabe, sana hangisi daha ulaşılabilir görünüyor?", "Allah'ı görür gibi olmanın zorluğunu ve O'nun seni gördüğünü bilmenin her an mümkün olduğunu düşün."]] },
      1: { amac: "İlk zâhidlerin manevî tecrübesini Hasan-ı Basrî üzerinden tanımak.", odak: "Hüzün manevî hayatta neden bu kadar önemsenmiştir?",
        not: "Hasan-ı Basrî'den şu söz nakledilir: “Mümin hüzün içinde sabahlar, hüzün içinde akşamlar; başka bir şey ona yakışmaz. Çünkü o iki korku arasındadır: Allah'ın kendisine ne yapacağını bilmediği geçmiş bir günah ile başına neler geleceğini bilmediği yaklaşan bir ecel.” Onun hüznü bir karamsarlık değil, sorumluluk bilincinin bir sonucudur. Görenlerin onu “sanki bir cenazeden yeni dönmüş gibi” tarif ettiği nakledilir. Bu hüzün, sonraki tasavvuf geleneğinde “havf” (korku) makamının temelini oluşturmuştur.",
        tedebbur: [["Hasan-ı Basrî'nin hüznü ile depresif bir karamsarlık arasındaki fark nedir?", "Hüznün bir sorumluluk bilincinden mi, yoksa bir ümitsizlikten mi doğduğunu düşün."], ["“İki korku arasında” yaşamak, gündelik kararlarını nasıl etkileyebilir?", "Geçmişini hesaba katmanın ve geleceği bilmemenin, bugünü daha dikkatli yaşamaya nasıl yönelttiğini düşün."]] },
      2: { amac: "İlâhî sevginin tasavvuftaki merkezî yerini görmek.", odak: "Cennet arzusu ve cehennem korkusu olmadan da kulluk edilebilir mi?",
        not: "Menâkıb kaynaklarında Râbia'nın bir elinde ateş, bir elinde su ile Basra sokaklarında yürüdüğü anlatılır: Cenneti yakıp cehennemi söndürmek istediğini, böylece insanların Allah'a korku veya ümit için değil, yalnızca O'nun için kulluk edeceğini söylemiştir. Bu tarihî doğruluğu tartışmalı menkıbe, sevgi merkezli bir kulluk anlayışını sembolize eder. Bununla birlikte âlimler, Kur'an'ın peygamberleri “umarak ve korkarak” (rağaben ve rahaben) dua edenler olarak övdüğünü (Enbiyâ 90) hatırlatır: Cennet ümidi ve cehennem korkusu da meşru ve övülmüş kulluk sebepleridir; sevgi bunları ortadan kaldırmaz, onları tamamlar.",
        tedebbur: [["Râbia'nın menkıbesi ile Enbiyâ 90'daki “umarak ve korkarak” ifadesini nasıl uzlaştırırsın?", "Sevginin korku ve ümidi ortadan kaldırması ile onları derinleştirmesi arasındaki farkı düşün."], ["Senin ibadetlerini en çok ne harekete geçiriyor: korku, ümit, sevgi veya alışkanlık?", "Kendine dürüstçe bakmayı ve bu sebeplerin birbirini nasıl tamamlayabileceğini düşün."]] },
      3: { amac: "Kalbin Kur'an'daki yerini ve hâllerini tanımak.", odak: "Kalbim nasıl bir değişim içinde?",
        not: "Huzeyfe'nin rivayet ettiği bir hadiste Hz. Peygamber, fitnelerin kalplere bir hasır örgüsünün çubukları gibi teker teker arz edileceğini anlatır: Hangi kalp bir fitneyi içine alırsa, onda siyah bir nokta oluşur; hangisi onu reddederse, onda beyaz bir nokta oluşur. Sonunda kalpler ikiye ayrılır: Biri, gökler ve yer var oldukça hiçbir fitnenin zarar veremeyeceği beyaz, düz bir taş gibi olur; diğeri ise ters dönmüş bir testi gibi kapkara olur, iyiliği tanımaz, kötülüğü reddetmez (Müslim). Kalp, küçük kararların birikimiyle şekillenir.",
        tedebbur: [["Kalbin “teker teker” arz edilen fitnelerle şekillenmesi, küçük kararlarının önemi hakkında sana ne söylüyor?", "Bugün verdiğin küçük bir kararın, kalbinde bir iz bırakabileceğini düşün."], ["“Ters dönmüş testi” benzetmesi, iyiliği tanıyamayan bir kalbin durumunu nasıl anlatıyor?", "Bir testinin ters döndüğünde içine hiçbir şey alamayacağını ve kalbin de bir noktadan sonra uyarıları alamayabileceğini düşün."]] },
      4: { amac: "Nefis terbiyesinin anlamını ve sınırını öğrenmek.", odak: "Nefisle mücadele bir cihad mıdır?",
        not: "Hz. Peygamber şöyle buyurmuştur: “Asıl mücahid, Allah'a itaat konusunda nefsiyle mücadele edendir” (Tirmizî, Fudâle b. Ubeyd; sahih). Buna karşılık yaygın olarak bilinen “Küçük cihaddan büyük cihada döndük” sözü, muhaddislere göre hadis olarak sabit değildir; İbn Hacer ve başkaları bunun senedinin zayıf olduğunu, bir tâbiînin sözü olabileceğini belirtir. Bu ayrım önemlidir: Nefisle mücadelenin değeri sahih bir hadisle sabittir; ancak bu değeri anlatmak için zayıf bir rivayeti Peygamber'e nispet etmeye gerek yoktur.",
        tedebbur: [["Nefisle mücadelenin bir “cihad” olarak nitelenmesi, gündelik hayattaki küçük çabalarına nasıl bir anlam kazandırıyor?", "Bir kötü alışkanlığı bırakmak için verdiğin mücadeleyi bir ibadet olarak görmeyi düşün."], ["Sahih bir manayı zayıf bir rivayetle anlatmanın sakıncası nedir?", "Hadis yolunda öğrendiğin ölçüleri hatırla: Bir sözün güzel olması, onu Peygamber'e nispet etmeyi meşru kılmaz."]] },
      5: { amac: "İhlas ve riyânın ameli nasıl şekillendirdiğini görmek.", odak: "İhlassız büyük bir amel neyi kaybeder?",
        not: "Ebû Hüreyre'nin rivayet ettiği bir hadiste, kıyamet günü ilk hesaba çekilecek üç kişi anlatılır: Bir şehit, bir âlim ve bir cömert. Şehide “Ne yaptın?” denince “Senin yolunda savaştım” der; “Yalan söyledin, ‘cesur’ denmesi için savaştın; o da dendi” cevabını alır. Âlim “İlmi senin için öğrendim” der; “‘Âlim’ denmesi için öğrendin” denir. Cömert de aynı şekilde “‘Cömert’ denmesi için verdin” cevabını alır. Üçü de yüzüstü cehenneme sürüklenir (Müslim). Ebû Hüreyre'nin bu hadisi anlatırken birkaç kez bayıldığı nakledilir (Tirmizî).",
        tedebbur: [["Hadisteki üç kişinin amelleri dünyada övgüye değer olduğu hâlde neden kabul edilmedi?", "Amelin dış görünüşü ile onu harekete geçiren niyet arasındaki farkı düşün."], ["Fudayl'ın “İnsanlar için ameli terk etmek riyâdır” sözü ile bu hadis birlikte okununca, riyâ korkusuyla ne yapmalısın?", "Ameli bırakmak yerine niyeti düzeltmeye çalışmanın yolunu düşün."]] },
      6: { amac: "Zühdün gerçek anlamını kavramak.", odak: "Zühd, dünyayı terk etmek midir?",
        not: "Süfyân es-Sevrî'den şu söz nakledilir: “Dünyada zühd, kaba yemek yemek ve aba giymek değildir; zühd, emeli kısaltmaktır.” Âlimler zühdü Hadîd 23. âyetle de tanımlamıştır: “Elinizden çıkana üzülmeyesiniz ve Allah'ın size verdiğiyle şımarmayasınız diye.” Bu tanıma göre zühd, malın yokluğu değil, malın kalp üzerindeki hâkimiyetinin yokluğudur. Elindeki bir şey gittiğinde yıkılmayan, bir şey geldiğinde şımarmayan insan, zengin de olsa zâhiddir.",
        tedebbur: [["Hadîd 23'e göre zühdün ölçüsü, kaybettiğin bir şey karşısındaki tepkindir. Son kaybettiğin bir şeye nasıl tepki verdin?", "Kaybın acısını hissetmek ile kaybın kalbini ele geçirmesi arasındaki farkı düşün."], ["“Emeli kısaltmak” ne demektir? Uzun vadeli planlar yapmak zühde aykırı mı?", "Gelecek için plan yapmak ile kalbi geleceğe bağlamak arasındaki farkı düşün."]] },
      7: { amac: "Nefsin sistemli tahlilini başlatan âlimi tanımak.", odak: "Kendini hesaba çekmek nasıl bir yöntemle yapılır?",
        not: "Muhâsibî'nin babasının Kaderiyye mezhebine mensup olduğu ve vefatında yetmiş bin dirhem miras bıraktığı nakledilir. Muhâsibî büyük bir ihtiyaç içinde olmasına rağmen bu mirastan tek bir dirhem bile almamış, “İki ayrı din mensubu birbirine mirasçı olmaz” hadisini gerekçe göstermiştir (Kuşeyrî, Hatîb el-Bağdâdî). Ayrıca şüpheli bir lokmaya elini uzattığında parmaklarının titrediği ve onu yiyemediği anlatılır. Bu hikâyeler, onun “muhasebe” anlayışının yalnızca bir iç tahlil değil, gündelik hayatta helal-haram titizliğine (vera') dönüşen bir disiplin olduğunu gösterir.",
        tedebbur: [["Muhâsibî'nin ihtiyaç içinde olmasına rağmen mirası reddetmesi, ilkeye bağlılığın bedeli hakkında sana ne düşündürüyor?", "Kendi hayatında bir ilke için bir kazancı veya kolaylığı reddettiğin bir anı düşün."], ["Günün sonunda kendini hesaba çekmek için hangi soruları sorabilirsin?", "Muhâsibî'nin yaklaşımıyla, sadece yaptıklarını değil, onları yaparken niyetini de sormayı düşün."]] },
      8: { amac: "Tasavvufun şeriatla uyumlu ana çizgisini tanımak.", odak: "Manevî tecrübenin ölçüsü nedir?",
        not: "Kuşeyrî'nin naklettiğine göre Cüneyd şöyle demiştir: “Biz bu tasavvufu dedikodudan ve laf ebeliğinden almadık; açlıktan, dünyayı terk etmekten, alışılmış ve hoşa giden şeyleri bırakmaktan aldık.” Cüneyd'in ayıklık (sahv) çizgisi, coşkun hâllerde söylenen ve şeriatın zâhirine aykırı görünen sözlere karşı mesafeli durur. Ona göre manevî yolun meyvesi, sözde değil, kişinin davranışında ve Kitap ile sünnete bağlılığında görünmelidir.",
        tedebbur: [["Cüneyd'in tasavvufu “dedikodudan değil açlıktan aldık” sözü, manevî bilgiyi okumakla elde etmenin sınırları hakkında ne söylüyor?", "Bir şeyi bilmek ile onu yaşayarak öğrenmek arasındaki farkı düşün."], ["Ayıklık (sahv) ile coşkunluk (sekr) arasında hangisi, manevî tecrübenin topluma zarar vermeden yaşanmasını sağlar?", "Kendini kaybetmiş bir hâlin söylediklerinin, başkalarını nasıl yanıltabileceğini düşün."]] },
      9: { amac: "Tasavvufun bir el kitabıyla nasıl tanımlandığını ve içeriden eleştirildiğini görmek.", odak: "Kuşeyrî Risâle'sini neden yazdı?",
        not: "Kuşeyrî, Risâle'yi 437/1045 yılında yazdığını belirtir ve mukaddimesinde dönemin tasavvufundan şikâyet eder: Bu yolun gerçek ehlinin çoğunun göçüp gittiğini, geriye yalnızca izlerinin kaldığını; haramı helalden ayırmayan, ibadetleri hafife alan ve hâl iddiasında bulunan kimselerin ortaya çıktığını söyler. Risâle'yi, gerçek sûfîlerin akidelerini, hâllerini ve sözlerini aktararak bu yozlaşmaya karşı bir ölçü sunmak için yazmıştır. Bu, tasavvufun en güçlü eleştirisinin çoğu zaman tasavvufun içinden geldiğini gösterir.",
        tedebbur: [["Bir geleneği içeriden eleştirmek ile dışarıdan eleştirmek arasında nasıl bir fark var?", "Kuşeyrî'nin eleştirisinin, tasavvufu reddetmek için değil, onu korumak için yapıldığını düşün."], ["Kuşeyrî'nin saydığı yozlaşma belirtileri bugün de görülüyor mu? Gerçek manevî rehberliği sahte olandan nasıl ayırırsın?", "Haram-helal titizliğini ve ibadetlere bağlılığı bir ölçü olarak kullanmayı düşün."]] },
      10: { amac: "Manevî yolun aşamalarını anlatan kavramları öğrenmek.", odak: "Makam kazanılır, hâl bağışlanır. Bu ayrım ne anlatıyor?",
        not: "Herevî'nin Menâzilü's-sâirîn adlı eseri, manevî yolu yüz menzil hâlinde anlatır. Herevî, kelâmı şiddetle eleştiren Hanbelî bir âlimdir. İbnü'l-Kayyim bu eser üzerine Medâricü's-sâlikîn adlı geniş bir şerh yazmış, ama yer yer müellife itiraz etmekten de çekinmemiştir. Herevî'nin bir görüşüne katılmadığı bir yerde şöyle der: “Şeyhülislâm bize sevgilidir, ama hak bize ondan daha sevgilidir.” Bu, tasavvufun Hanbelî çevrelerde de derin bir karşılığı olduğunu ve sevgi ile ilmî bağımsızlığın bir arada bulunabileceğini gösterir.",
        tedebbur: [["“Şeyhülislâm bize sevgilidir, ama hak daha sevgilidir” sözü, sevdiğin bir âlime veya hocaya nasıl bakman gerektiği hakkında ne söylüyor?", "Birine duyduğun sevginin, onun hatasını görmene engel olmaması gerektiğini düşün."], ["Makamların kazanılması ve hâllerin bağışlanması, manevî yolda çaba ile lütuf arasındaki ilişkiyi nasıl açıklıyor?", "Çaba göstermeden lütuf beklemenin ve lütfu kendi çabana bağlamanın iki ayrı hata olduğunu düşün."]] },
      11: { amac: "Gazâlî'nin ilim ile kalbi birleştirme projesini kavramak.", odak: "İhyâ neyi “diriltmek” istedi?",
        not: "İhyâü ulûmi'd-dîn dört bölümden (rub') oluşur ve her bölüm on kitap içerir: ibadetler, âdetler (gündelik hayat), helak ediciler (mühlikât) ve kurtarıcılar (münciyât). Eser, namaz ve oruç gibi dış amellerden başlayıp yeme-içme, evlilik ve kazanç gibi gündelik konulardan geçerek, kibir, haset ve dünya sevgisi gibi kalp hastalıklarına, oradan da tevbe, sabır, şükür ve sevgi gibi kurtarıcı hâllere uzanır. Bu yapı, ilmin bir terbiye programı olarak düzenlendiğini gösterir. Eser, içerdiği zayıf hadisler sebebiyle eleştirilmiş; Endülüs'te Murâbıtlar döneminde yakılmıştır. Zeynüddin el-Irâkī ise kitaptaki hadislerin kaynaklarını ve derecelerini tek tek göstermiştir.",
        tedebbur: [["İhyâ'nın dış amellerden kalbin hâllerine doğru ilerleyen yapısı, kendi manevî gelişimin için nasıl bir sıra öneriyor?", "Dış ibadetlerin kalbi hazırladığını, kalbin ise ibadetlere ruh verdiğini düşün."], ["İhyâ'nın zayıf hadisler sebebiyle eleştirilmesi ve Irâkī'nin bu hadisleri tahric etmesi, büyük bir eseri okurken nasıl bir tavır öneriyor?", "Bir eserin faydasını alırken onun zayıf yönlerini bilmenin önemini düşün."]] },
      12: { amac: "Gazâlî'nin bir talebeye nasihatini okumak.", odak: "Okuduğum ilimlerden hangisi bana fayda verecek?",
        not: "Risaleyi doğuran talebenin sorusu, Gazâlî'nin kendi hayatındaki büyük krizin bir yankısıdır. Gazâlî, el-Munkız mine'd-dalâl'de, Bağdat'taki Nizâmiye Medresesi'nde şöhretinin zirvesindeyken, öğrettiği ilimlerin ve niyetinin Allah için olup olmadığını sorguladığını anlatır. Bu sorgulama onu konuşamaz hâle getirmiş, sonunda her şeyi bırakıp yıllarca süren bir inzivaya çekilmiştir. Talebenin “Hangi ilim kabrimde bana yoldaş olacak?” sorusu, Gazâlî'nin bizzat yaşadığı bir sorudur; bu yüzden risale, bir hocanın kendi tecrübesinden süzülmüş bir cevabıdır.",
        tedebbur: [["Talebenin “Okuduğum ilimlerden hangisi bana fayda verecek?” sorusunu kendi okumaların için sor. Cevabın ne?", "Bu yolda okuduklarından hangisinin seni daha iyi bir insan yaptığını düşün."], ["Gazâlî'nin bu cevabı, kendi krizini yaşadıktan sonra vermesi, nasihatin değeri hakkında ne söylüyor?", "Yaşanmış bir tecrübeden doğan nasihat ile yalnızca bilgiden doğan nasihat arasındaki farkı düşün."]] },
      13: { amac: "Velâyet ve kerâmetin ölçüsünü öğrenmek.", odak: "Bir velînin gerçek alameti nedir?",
        not: "Kuşeyrî'nin naklettiğine göre Bâyezîd-i Bistâmî, velâyetiyle meşhur olan bir zâhidi ziyarete gitmiştir. O zâhidin mescide girerken kıble tarafına doğru tükürdüğünü görünce onunla görüşmeden geri dönmüş ve şöyle demiştir: “Bu kişi Resûlullah'ın edeplerinden biri konusunda güvenilir değilken, iddia ettiği şey konusunda nasıl güvenilir olabilir?” Bu hikâye, sûfîlerin kendi ölçüsünü gösterir: Velâyetin alameti olağanüstü hâller değil, şeriatın en küçük edebine bile bağlılıktır.",
        tedebbur: [["Bâyezîd'in bir edep hatasına bakarak bir velâyet iddiasını değerlendirmesi, bugün manevî iddialara nasıl bakmamız gerektiğini gösteriyor?", "Olağanüstü hikâyeler yerine kişinin gündelik edebine ve şeriata bağlılığına bakmayı düşün."], ["“En büyük kerâmet istikamettir” sözü, senin hayatında nasıl bir hedef öneriyor?", "Olağanüstü bir tecrübe aramak yerine, her gün dosdoğru yaşamanın kendisinin bir mucize olduğunu düşün."]] },
      14: { amac: "Tasavvufun en tartışmalı kavramına dengeli bir bakış geliştirmek.", odak: "Anlamakta zorlandığım bir âlimin sözlerine nasıl yaklaşmalıyım?",
        not: "Osmanlı'da İbnü'l-Arabî hakkında verilen en meşhur fetvalardan biri Şeyhülislâm Kemalpaşazâde'ye aittir. Fetvada İbnü'l-Arabî'nin büyük bir âlim olduğu, eserlerinde şeriata uygun olan çok şey bulunduğu, bazı sözlerinin ise zâhire aykırı göründüğü belirtilir. Bu sözler için önerilen tavır şudur: Onları anlamayan kişi susmalıdır; çünkü bu sözler, keşif ehlinin özel bir ıstılahla söylediği şeylerdir ve zâhir ehlinin anlayışına göre yorumlanmaları yanlış sonuçlara götürebilir. Bu fetva, inkâr ile körü körüne kabul arasında üçüncü bir yol önerir.",
        tedebbur: [["Kemalpaşazâde'nin “anlamayan sussun” tavsiyesi, anlamadığın derin bir söz karşısında nasıl bir tavır öneriyor?", "Anlamadığın bir sözü hemen reddetmek veya hemen kabul etmek yerine, onu askıya almayı düşün."], ["Vahdet-i vücûd ile vahdet-i şühûd arasındaki fark, aynı tecrübenin farklı yorumlanabileceği hakkında ne söylüyor?", "Bir yaşantının kendisi ile o yaşantıya getirilen açıklamanın ayrı şeyler olabileceğini düşün."]] },
      15: { amac: "Tasavvufun aşk dilini ve Kur'an'a bağlılığını Mevlânâ'da görmek.", odak: "Mevlânâ'nın aşkı, şeriatla nasıl bir ilişki içinde?",
        not: "Mevlânâ'ya nispet edilen bir rubâide şöyle denir: “Ben yaşadıkça Kur'an'ın kölesiyim; ben Muhammed Muhtâr'ın yolunun toprağıyım. Biri benden bundan başka bir söz naklederse, ondan da bîzârım, o sözden de bîzârım.” Mevlânâ, Şems ile karşılaşmasından sonra da fetva vermeye ve fıkıh öğretmeye devam etmiştir. Bu söz ve hayatı, onun aşk dilini şeriattan bağımsız bir “evrensel maneviyat” olarak okuyan modern yorumlara karşı, kendi ağzından bir düzeltme niteliği taşır.",
        tedebbur: [["Mevlânâ'nın Kur'an'a ve sünnete bağlılığını vurgulayan bu söz, onu yalnızca bir “aşk şairi” olarak tanıtan yaygın yorumlar hakkında ne düşündürüyor?", "Bir düşünürü kendi sözleriyle tanımanın önemini düşün."], ["Mevlânâ'nın hikâyeyi bir “ölçek”, içindeki manayı ise “tane” olarak görmesi, kendi okumalarına nasıl bir dikkat kazandırabilir?", "Bir hikâyenin kendisinde kalmak yerine, onun taşıdığı manayı aramayı düşün."]] },
      16: { amac: "Tasavvufun Türkçe ve halkın dilindeki sesini tanımak.", odak: "Yunus'un dilinde ibadet ile ahlâk nasıl birleşir?",
        not: "Yunus Emre'nin en çok bilinen beyitlerinden biri şudur: “Bir kez gönül yıktın ise, bu kıldığın namaz değil; yetmiş iki millet dahi elin yüzün yumaz değil.” Bu beyit namazı küçümsemez; aksine namazın, insanın kalbini kırarak Allah'ın rızasını kazanmaya çalışmakla bağdaşmadığını söyler. Yunus burada, Mâûn suresinin namaz ile yardımlaşmayı yan yana getiren uyarısını ve “Müslüman, dilinden ve elinden insanların güvende olduğu kimsedir” hadisini halkın anlayacağı bir dille ifade eder.",
        tedebbur: [["“Bir kez gönül yıktın ise” beyti, ibadetlerin insan ilişkilerinden ayrılamayacağını nasıl anlatıyor?", "Bir ibadetin kabulünün, kırdığın bir kalbi onarmakla ilişkisini düşün."], ["Bu yolun sonunda, tasavvufun senin hayatına kattığı en önemli şey ne oldu?", "Okuduğun bir kavramı, bu hafta yaşayacağın somut bir davranışa dönüştürmeyi düşün."]] }
    },
    sentez: "Bu yolda tanıdığın kavramlardan birini (ihlas, zühd, nefis muhasebesi veya ihsan) seç. Önce onu bir âyet veya hadisle tanımla, sonra bu yolda tanıdığın bir âlimin o kavramla ilgili bir sözünü veya tecrübesini anlat. Son olarak bu kavramı bir hafta boyunca nasıl yaşamaya çalışacağını ve bunun için kendine hangi soruyu soracağını yaz." },

  siyer: {
    buyukResim: "Siyer, çoğu zaman tarihler ve savaşlar listesi olarak okunur. Bu yol ise Hz. Peygamber'in hayatını, Kur'an'ın inişiyle iç içe bir hidayet hikâyesi olarak okumaya davet eder. Hz. Âişe'nin ifadesiyle “Onun ahlâkı Kur'an'dı”; yani Kur'an bir kitapta yazılı, siyerde ise yaşanmış hâldedir. Önce Peygamber'in doğumundan önceki Mekke'yi ve gençliğini görürsün. Sonra ilk vahiyle başlayan Mekke dönemini, inen surelerle birlikte okursun. Ardından hicret ve Medine'de bir toplumun nasıl kurulduğunu, en sonda da fetih, veda ve vefatı izlersin. Her olayda kendine şunu sor: Bu olayın Kur'an'daki yankısı ne ve bana ne söylüyor?",
    hedefler: ["Hz. Peygamber'in hayatının ana dönemlerini, o dönemlerde inen âyetlerle birlikte anlatabilmek.", "Siyerdeki olaylardan ahlâkî ve toplumsal dersler çıkarabilmek.", "Peygamber'in zorluk, zafer, kayıp ve başarı anlarındaki tavrını kendi hayatına örnek alabilmek.", "Kur'an'ı inişinin canlı bağlamında okumanın bir yolunu edinebilmek."],
    sure: "Yaklaşık 3 hafta", onbilgi: "Gerekmez.",
    etaplar: [
      ["Doğumdan önce ve gençlik", 0, 3, "Fil olayı, Kureyş'in güvenli ticareti, yetimlik ve Emîn lakabı: Peygamberlikten önceki bu yıllar, onun peygamberlik görevine nasıl hazırlandığını gösteriyor?"],
      ["İlk vahiy ve Mekke'de davet", 4, 10, "Alak'ta “Oku!”, Duhâ'da teselli, Tebbet'te düşmanlık, Abese'de uyarı: Mekke döneminde inen sureler, davetin hangi zorluklarına cevap veriyor?"],
      ["Hicret ve Medine'de toplum kurmak", 11, 13, "Hicret, Bedir, Uhud ve Hudeybiye: Bu olaylarda zafer ve yenilgi, görünüşte olan ile gerçekte olan arasındaki farkı nasıl öğretiyor?"],
      ["Fetih, veda ve miras", 14, 17, "Mekke'nin fethinde af, Nasr'da istiğfar, vedada tebliğ ve vefatta teslimiyet: Bir hayatın zirvesi ve sonu, onun bütününü nasıl özetliyor?"]
    ],
    adim: {
      0: { amac: "Hz. Peygamber'in doğumundan önceki Mekke'yi ve ilâhî korumayı görmek.", odak: "Fil olayı, peygamberliğin hangi zeminini hazırladı?",
        not: "İbn İshâk'ın naklettiğine göre Ebrehe'nin ordusu Mekke'ye yaklaştığında, Abdülmuttalib'in develerine el konulmuştu. Abdülmuttalib Ebrehe'nin huzuruna çıkınca, Ebrehe onun Kâbe için yalvarmasını beklerken o yalnızca develerini istedi. Ebrehe şaşırınca şöyle dediği nakledilir: “Ben develerin sahibiyim. Beytin de bir sahibi vardır; onu O koruyacaktır.” Sonra Kureyş'e şehri boşaltıp dağlara çekilmelerini söyledi. Bu olay, Hz. Peygamber'in doğduğu yıl gerçekleşmiştir.",
        tedebbur: [["Abdülmuttalib'in “Beytin bir sahibi vardır” sözü, insanın gücünün yetmediği yerde nasıl bir teslimiyet öğretiyor?", "Kendi sorumluluğunu yerine getirip, gücünü aşan şeyi Allah'a bırakmanın anlamını düşün."], ["Fil olayının Hz. Peygamber'in doğduğu yıl gerçekleşmesi, sana nasıl bir işaret gibi görünüyor?", "Kâbe'nin korunmasının, oradan yükselecek tevhid davetine hazırlanan bir zemin olduğunu düşün."]] },
      1: { amac: "Kureyş'in konumunu ve Kur'an'ın bu konuma bakışını kavramak.", odak: "Kureyş'in ayrıcalığı, İslâm'la nasıl değişti?",
        not: "Kureyş, Kâbe'nin hizmetini üstlendiği için kendisine “Hums” denen ayrıcalıklı bir statü tanımıştı. Bu ayrıcalık gereği, hac sırasında diğer Araplarla birlikte Arafat'a çıkmaz, Harem sınırları içindeki Müzdelife'de kalırdı. Bakara 199'da “Sonra insanların akın ettiği yerden siz de akın edin” emri bu ayrıcalığı kaldırmıştır (Buhârî, Âişe). Hz. Peygamber, peygamberlikten önce bile Kureyş'in bu âdetine uymayıp diğer insanlarla birlikte Arafat'ta durmuştur (Buhârî, Cübeyr b. Mut'im). Kureyş suresinin hatırlattığı güven ve rızık nimeti, bir ayrıcalık değil, bir kulluk sorumluluğudur.",
        tedebbur: [["Kureyş'in Kâbe'ye hizmet etmesinin bir ayrıcalık iddiasına dönüşmesi, dinî bir görevi bir statü aracına çevirmenin tehlikesi hakkında ne söylüyor?", "Kendi hayatında, bir hizmetin bir üstünlük duygusuna dönüştüğü bir anı düşün."], ["Hz. Peygamber'in peygamberlikten önce bile Kureyş'in ayrıcalığına uymaması, onun karakteri hakkında ne söylüyor?", "Kendi kabilesinin âdetine rağmen insanlarla eşit durmayı seçmesinin anlamını düşün."]] },
      2: { amac: "Yetimliğin ve çocukluk yıllarının Peygamber'in şahsiyetindeki izini görmek.", odak: "Yetim olarak büyümek, onu nasıl şekillendirdi?",
        not: "Duhâ 6'daki “Seni yetim bulup barındırmadı mı?” âyeti üzerine müfessirler şu hikmeti söyler: Hz. Peygamber, bir babanın terbiyesine minnet borcu olmadan, doğrudan Allah'ın gözetimi altında yetiştirilmiştir. Bu yetimlik tecrübesi, onun yetimlere olan derin şefkatinde açıkça görülür. Hz. Peygamber işaret ve orta parmağını yan yana getirerek “Ben ve yetimi koruyup gözeten kimse cennette böyleyiz” buyurmuştur (Buhârî, Sehl b. Sa'd). Kendi yaşadığı acıyı, başkalarının acısını dindirmenin bir sebebine dönüştürmüştür.",
        tedebbur: [["Hz. Peygamber'in kendi yetimlik acısını yetimlere şefkate dönüştürmesi, senin yaşadığın bir acıyı başkaları için nasıl bir merhamet kaynağına dönüştürebileceğini gösteriyor?", "Bir zorluğu yaşamış olmanın, aynı zorluğu yaşayanları anlamayı nasıl kolaylaştırdığını düşün."], ["Hayatında yetim veya kimsesiz birinin hakkını gözetmek için ne yapabilirsin?", "Doğrudan bir destek veya bir kurum aracılığıyla yapılabilecek somut bir adımı düşün."]] },
      3: { amac: "Peygamberlikten önceki karakterini tanımak.", odak: "Hz. Hatice onu nasıl tanıyordu?",
        not: "İlk vahyin ardından korku içinde eve dönen Hz. Peygamber'i teselli eden Hz. Hatice, onu şu sözlerle tarif etmiştir: “Allah'a yemin ederim ki Allah seni asla mahcup etmez. Çünkü sen akrabalık bağını gözetirsin, kimsesizin yükünü taşırsın, yoksula kazandırırsın, misafiri ağırlarsın ve hak yolunda başa gelen musibetlerde yardım edersin” (Buhârî). Bu sözler, on beş yıllık bir evlilikte onu en yakından tanıyan kişinin tanıklığıdır ve peygamberlikten önceki gençlik yıllarının bir özetidir.",
        tedebbur: [["Hz. Hatice'nin tanıklığında sayılan beş vasıf, peygamberliğe hazırlanan bir karakterin özelliklerini nasıl gösteriyor?", "Bu vasıfların hepsinin başkalarına yönelik iyilikler olduğunu fark et."], ["Seni en yakından tanıyan biri seni hangi vasıflarla tarif ederdi?", "Kendi karakterinin, sana en yakın olanların gözünde nasıl göründüğünü dürüstçe düşün."]] },
      4: { amac: "İlk vahyin nasıl karşılandığını ve davetin başlangıcını görmek.", odak: "Hakikati taşımak neden zorluk getirir?",
        not: "Hz. Hatice, Hz. Peygamber'i amcasının oğlu Varaka b. Nevfel'e götürdüğünde Varaka ona şöyle demiştir: “Keşke kavmin seni yurdundan çıkaracağı zaman genç olsaydım!” Hz. Peygamber şaşırarak sordu: “Onlar beni çıkaracaklar mı?” Varaka şöyle cevap verdi: “Evet. Senin getirdiğin gibi bir şey getiren hiç kimse yoktur ki düşmanlığa uğramamış olsun” (Buhârî). Daha ilk günden, getirilen hakikatin bir bedeli olacağı haber verilmiştir.",
        tedebbur: [["Varaka'nın “Senin getirdiğin gibi bir şey getiren herkes düşmanlığa uğramıştır” sözü, hakikati savunmanın bedeli hakkında ne söylüyor?", "Doğru bildiğin bir şeyi söylediğin için karşılaştığın bir zorluğu düşün."], ["Hz. Peygamber'in “Beni çıkaracaklar mı?” diye şaşırması, onun kavmine olan sevgisi hakkında ne söylüyor?", "Sevdiğin insanlar tarafından reddedilme ihtimalinin acısını düşün."]] },
      5: { amac: "İlk inen âyetlerin mesajını siyer bağlamında okumak.", odak: "Okuma bilmeyen bir peygambere ilk emrin “Oku!” olması ne anlatıyor?",
        not: "Ümmî bir peygambere ve büyük ölçüde okuma yazma bilmeyen bir topluma inen ilk kelimenin “Oku!” olması, İslâm medeniyetinin ilimle başlayacağının bir işaretidir. Bu işaret Medine döneminde somut uygulamalara dönüşmüştür. Hz. Peygamber, Zeyd b. Sâbit'e Yahudilerin yazısını öğrenmesini emretmiş, Zeyd de bu dili yaklaşık on beş günde öğrenip Peygamber'in yazışmalarını yürütmüştür (Buhârî ta'lîkan, Tirmizî). İlk emrin “Rabbinin adıyla” kaydı ise, bilginin Yaratan'dan koparılmadan elde edilmesi gerektiğini anlatır.",
        tedebbur: [["“Rabbinin adıyla oku” emri, bugün öğrendiğin bilgileri nasıl bir niyetle öğrenmen gerektiği hakkında ne söylüyor?", "Bilgiyi Allah'a bağlı olarak öğrenmek ile ondan kopuk bir şekilde öğrenmek arasındaki farkı düşün."], ["Hz. Peygamber'in Zeyd'e yabancı bir yazı öğrenmesini emretmesi, faydalı bilgiyi nereden olursa olsun almak hakkında ne söylüyor?", "Kendi alanının dışında öğrenmen gereken bir bilgi veya beceriyi düşün."]] },
      6: { amac: "Vahyin kesildiği zor günlerin ve tesellinin anlamını kavramak.", odak: "Duhâ'nın teselli edici mesajı gündelik hayatta nasıl bir karşılık bulur?",
        not: "Surenin adı olan “kuşluk vakti”, Hz. Peygamber'in sabah güneşi yükseldikten sonra kıldığı duhâ namazının da adıdır. Ebû Hüreyre şöyle anlatır: “Dostum bana üç şeyi tavsiye etti: Her aydan üç gün oruç tutmamı, iki rekât duhâ namazı kılmamı ve uyumadan önce vitir kılmamı” (Buhârî, Müslim). Vahyin kesildiği karanlık günlerden sonra “kuşluk vaktine” yemin ederek gelen teselli, müminin gününde de küçük bir ibadet anına dönüşmüştür: Günün aydınlığında Rabbine yönelmek.",
        tedebbur: [["Duhâ suresinin teselli mesajını, gün içinde kılacağın iki rekâtlık bir duhâ namazıyla hatırlamak sana ne kazandırabilir?", "Küçük ve düzenli bir ibadetin, zor zamanlarda bir dayanak olabileceğini düşün."], ["Ebû Hüreyre'ye yapılan üç tavsiye de küçük ama düzenli amellerdir. Senin hayatına hangi küçük ve sürekli bir ameli ekleyebilirsin?", "Büyük ama kesintili amellerden çok, küçük ama sürekli amellerin değerini düşün."]] },
      7: { amac: "Açık davetin, eziyetlerin ve Habeşistan hicretinin anlamını görmek.", odak: "İslâm'ın ilk dönemde nasıl anlatıldığını kendi ağızlarından dinlemek.",
        not: "Ümmü Seleme'nin anlattığına göre Ca'fer b. Ebî Tâlib, Necâşî'nin huzurunda İslâm'ı şöyle tanıtmıştır: “Ey hükümdar! Biz câhiliye ehli bir kavimdik. Putlara tapar, leş yer, hayâsızlık yapar, akrabalık bağlarını koparır, komşuya kötülük ederdik; güçlümüz zayıfımızı ezerdi. Allah bize, soyunu, doğruluğunu, güvenilirliğini ve iffetini bildiğimiz bir peygamber gönderdi. Bizi Allah'ı birlemeye, doğru sözlü olmaya, emanete riayet etmeye, akrabayı gözetmeye ve komşuya iyilik etmeye çağırdı” (Ahmed). Bu konuşma, İslâm'ın ilk muhataplar tarafından önce bir ahlâk devrimi olarak algılandığını gösterir.",
        tedebbur: [["Ca'fer'in İslâm'ı tanıtırken inanç esaslarından önce ahlâkî değişimi anlatması, bugün dini anlatırken neye öncelik vermemiz gerektiği hakkında ne söylüyor?", "Bir insanın dini, önce başkalarına nasıl davrandığında görür."], ["“Güçlümüz zayıfımızı ezerdi” cümlesi, bugünkü toplumda hangi durumlara karşılık geliyor?", "Kendi çevrende güçlü olanın zayıfı ezdiği bir durumu ve ona karşı ne yapabileceğini düşün."]] },
      8: { amac: "Akrabalık bağının hidayeti garanti etmediğini Tebbet üzerinden görmek.", odak: "Peygamber'in amcası olmak, Ebû Leheb'e neden fayda vermedi?",
        not: "Ebû Leheb'in asıl adı Abdüluzzâ'dır; “Ebû Leheb” (alevin babası) yüzünün parlaklığı sebebiyle aldığı bir künyedir. Kur'an'da adıyla kınanan tek kişidir. Hz. Peygamber'in öz amcası olmasına rağmen ona en sert düşmanlığı yapanlardan biri olmuş, oğulları Utbe ve Uteybe'ye, nişanlı oldukları Peygamber'in kızları Rukiyye ve Ümmü Külsûm'den ayrılmalarını emretmiştir. Surenin onun künyesini, gideceği yerin, alevli bir ateşin, adıyla birleştirmesi, kader ile seçimin ince bir ironisidir.",
        tedebbur: [["Peygamber'in amcası olmanın Ebû Leheb'i kurtarmaması, soy ve yakınlığın hidayetteki yeri hakkında ne söylüyor?", "Hz. Nûh'un oğlunu ve Hz. İbrâhim'in babasını da hatırla: Hidayet bir mirasla değil, kişisel bir seçimle kazanılır."], ["Ebû Leheb'in düşmanlığının en çok kendi ailesine zarar vermesi, kin ve düşmanlığın kimi en çok yaktığı hakkında ne düşündürüyor?", "Düşmanlığın, onu besleyenin hayatını nasıl daralttığını düşün."]] },
      9: { amac: "Davetteki bir öncelik hatasının ilâhî uyarıyla düzeltilmesini görmek.", odak: "Davette öncelik kime verilmelidir?",
        not: "Abese suresindeki uyarıya benzer bir uyarı, En'âm 52'de de yer alır: “Sabah akşam Rablerinin rızasını isteyerek O'na dua edenleri yanından kovma.” Sa'd b. Ebî Vakkās'ın anlattığına göre müşrik ileri gelenleri, Hz. Peygamber'den yanındaki fakir ve zayıf Müslümanları uzaklaştırmasını, ancak o zaman onunla oturabileceklerini söylemişti. Hz. Peygamber'in içinden buna meyletmesi üzerine bu âyet inmiştir (Müslim). Kehf 28'de de aynı ilke tekrarlanır: “Dünya hayatının süsünü isteyerek gözlerini onlardan çevirme.”",
        tedebbur: [["Hem Abese'de hem En'âm 52'de aynı uyarının tekrarlanması, toplumsal statünün değerlendirmelerimizi ne kadar kolay etkileyebileceği hakkında ne söylüyor?", "Bir toplantıda veya grupta, farkında olmadan önemli gördüğün ve görmezden geldiğin kişileri düşün."], ["Davette veya bir hizmette, “daha etkili” görünen insanlara öncelik vermenin tehlikesi nedir?", "Tek bir kişinin bile arınmasının, kalabalıkları etkilemekten daha değerli olabileceğini düşün."]] },
      10: { amac: "Hüzün yılını, Tâif'i ve Mi'racı bir bütün olarak okumak.", odak: "En büyük acıdan sonra en yüksek yolculuk neden geldi?",
        not: "Tâif'ten taşlanarak çıkarıldıktan sonra Hz. Peygamber'in yaptığı dua şöyle nakledilir: “Allah'ım! Kuvvetimin azlığını, çaresizliğimi ve insanlar nezdindeki değersizliğimi sana arz ediyorum. Ey merhametlilerin en merhametlisi! Sen zayıfların Rabbisin, sen benim de Rabbimsin... Eğer bana gazap etmiyorsan, hiçbir şeye aldırmam; fakat senin afiyetin benim için daha geniştir.” Bu dua, senedinde bazı zayıflıklar bulunsa da siyer âlimlerince yaygın olarak nakledilmiş ve kabul görmüştür. Duadaki ölçü dikkat çekicidir: Asıl kaygı insanların reddi değil, Allah'ın razı olup olmadığıdır.",
        tedebbur: [["“Eğer bana gazap etmiyorsan, hiçbir şeye aldırmam” cümlesi, insanların reddi karşısında nasıl bir iç ölçü öneriyor?", "İnsanların onayı ile Allah'ın rızası arasında hangisinin seni daha çok etkilediğini düşün."], ["Hüzün yılının ardından Mi'racın gelmesi, zorlukla gelen ilâhî ikram hakkında ne düşündürüyor?", "İnşirâh'taki “Zorlukla beraber kolaylık vardır” âyetini hatırla."]] },
      11: { amac: "Hicretin bir kopuş değil, yeni bir başlangıç olduğunu görmek.", odak: "En zor anlarda bile umut nasıl korunur?",
        not: "Hicret sırasında Mekkelilerin vaat ettiği ödül için Hz. Peygamber'in peşine düşen Sürâka b. Mâlik, yaklaştığında atının ayaklarının birkaç kez kuma gömüldüğünü görmüş ve geri dönmeye karar vermiştir (Buhârî). Bazı rivayetlere göre Hz. Peygamber bu kovalanma anında Sürâka'ya, bir gün İran hükümdarı Kisrâ'nın bileziklerini takacağını müjdelemiştir. Yıllar sonra Hz. Ömer döneminde İran fethedilince, Kisrâ'nın bilezikleri Sürâka'ya takılmıştır. Kovalanan bir yolcunun, kendisini kovalayana bir imparatorluğun hazinelerini vaat etmesi, hicretin bir kaçış değil, bir geleceğe yürüyüş olduğunu gösterir.",
        tedebbur: [["Kovalanan bir insanın kendisini kovalayana gelecek vaat etmesi, en zor anlarda bile nasıl bir umut taşınabileceğini gösteriyor?", "Kendi zorluğunun içinde geleceğe dair bir umudu nasıl canlı tutabileceğini düşün."], ["“Üzülme, Allah bizimle” (Tevbe 40) cümlesi, korkunun en yoğun olduğu anda söylenmişti. Bu cümle senin hangi korkuna cevap veriyor?", "Allah'ın beraberliğinin, tehlikeyi ortadan kaldırmasa da korkuyu nasıl dönüştürdüğünü düşün."]] },
      12: { amac: "Zafer ve yenilgide istişarenin ve itaatin yerini görmek.", odak: "Vahiy ile insan görüşü arasında nasıl bir ilişki vardı?",
        not: "Bedir'de ordunun konakladığı yeri gören Hubâb b. Münzir, Hz. Peygamber'e şunu sordu: “Ey Allah'ın Resûlü! Bu yer, Allah'ın sana bildirdiği ve ileri ya da geri gitmememiz gereken bir yer mi, yoksa bir görüş, savaş ve tedbir meselesi mi?” Hz. Peygamber bunun bir görüş olduğunu söyleyince Hubâb, suyu arkaya alacak daha uygun bir yer önerdi ve Hz. Peygamber bu öneriyi kabul etti (İbn İshâk). Uhud'dan önce de Hz. Peygamber şehirde kalmayı tercih ettiği hâlde çoğunluğun görüşüne uyarak dışarı çıktı. Uhud'daki yenilgiden sonra bile Kur'an “Onlarla istişare et” (Âl-i İmrân 159) emrini tekrarlamıştır.",
        tedebbur: [["Hubâb'ın sorusu, vahiy ile insanî tedbir arasındaki ayrımı nasıl gösteriyor? Bu ayrım bugün dinî ve dünyevî kararları birbirinden ayırmamızda nasıl yardımcı olur?", "Her kararın dinî bir zorunluluk olmadığını, bazılarının akıl ve tecrübeye bırakıldığını düşün."], ["Uhud'daki yenilgiye rağmen istişare emrinin tekrarlanması, kötü bir sonuç veren bir yöntemi hemen terk etmemek hakkında ne söylüyor?", "İstişarenin değerinin, her seferinde iyi sonuç vermesine bağlı olmadığını düşün."]] },
      13: { amac: "Hudeybiye'nin görünüşte yenilgi, gerçekte fetih oluşunu kavramak.", odak: "Bir krizde çözüm nereden gelebilir?",
        not: "Hudeybiye antlaşmasından sonra Hz. Peygamber sahabeye kurbanlarını kesip tıraş olmalarını emretti; ancak antlaşmanın ağır şartları karşısında sarsılmış olan sahabeden kimse yerinden kalkmadı. Bunu üç kez tekrarladı. Üzüntüyle çadırına giren Hz. Peygamber durumu eşi Ümmü Seleme'ye anlattı. Ümmü Seleme şöyle dedi: “Ey Allah'ın Resûlü! Bunu istiyor musun? Öyleyse çık, kimseyle tek kelime konuşma, kurbanını kes ve berberini çağırıp tıraş ol.” Hz. Peygamber böyle yapınca sahabe de kalkıp kurbanlarını kesti ve birbirini tıraş etti (Buhârî).",
        tedebbur: [["Ümmü Seleme'nin tavsiyesi, sözle ikna edilemeyen insanların örnekle nasıl harekete geçtiğini gösteriyor. Senin hayatında söz yerine örneğin daha etkili olduğu bir durum var mı?", "Birini bir şeye ikna etmeye çalışmak yerine, onu kendin yapmayı düşün."], ["Hz. Peygamber'in bir kriz anında eşinin görüşünü alıp uygulaması, aile içi istişare hakkında ne söylüyor?", "En yakınındakilerin görüşünü, özellikle zor anlarda, ne kadar önemsediğini düşün."]] },
      14: { amac: "Fethin bir intikam değil, bir af ve emanet anı olduğunu görmek.", odak: "En güçlü olduğun anda nasıl davranırsın?",
        not: "Mekke'nin fethedildiği gün Kâbe'nin anahtarı, Kâbe'nin bakımını üstlenen ailenin temsilcisi Osman b. Talha'dan alınmıştı. Hz. Ali ve Hz. Abbâs anahtarın kendi ailelerine verilmesini istedi. Ancak Hz. Peygamber anahtarı Osman b. Talha'ya geri verdi ve “Bu anahtar ebediyen sizin elinizde kalacaktır” buyurdu. Müfessirler, “Allah size emanetleri ehline vermenizi emreder” (Nisâ 58) âyetinin bu olayla ilgili olduğunu nakleder. Zaferin zirvesinde bile bir görev, akrabalık bağına göre değil, ehliyet ve emanete göre verilmiştir.",
        tedebbur: [["Hz. Peygamber'in anahtarı akrabalarına değil, eski bir rakip ailesine geri vermesi, gücün zirvesinde adaletin nasıl korunacağını gösteriyor?", "Kendi elinde bir yetki olduğunda, onu yakınların lehine kullanma eğilimini düşün."], ["Genel af ilanı ile anahtarın iadesi birlikte düşünüldüğünde, fethin asıl amacı neydi?", "Bir zaferin, karşı tarafı yok etmek mi yoksa onu kazanmak mı amaçladığını düşün."]] },
      15: { amac: "Zafer anında tevazu ve istiğfarı Peygamber'in tavrında görmek.", odak: "Nasr suresinin emri, fetih gününde nasıl yaşandı?",
        not: "İbn İshâk'ın naklettiğine göre Hz. Peygamber, fetih günü Mekke'ye girerken, Allah'ın kendisine verdiği zafer karşısındaki tevazuu sebebiyle başını o kadar eğmişti ki sakalı neredeyse devesinin semerine değiyordu. Sekiz yıl önce gizlice terk etmek zorunda kaldığı şehre, on bin kişilik bir orduyla girerken onun tavrı bir galibin gururu değil, bir kulun şükrüydü. Nasr suresinin emrettiği hamd ve istiğfar, böylece sözden önce bir duruşla yaşanmıştı.",
        tedebbur: [["Başını eğerek bir şehre girmek, başarı anında nasıl bir tavrın modelidir?", "Kendi hayatındaki bir başarı anında, kibir yerine şükrü nasıl seçebileceğini düşün."], ["Zafer anında istiğfar etmek, bir başarının içindeki hangi kusurların farkında olmayı gerektirir?", "Hiçbir başarının kusursuz olmadığını ve bir başarının yolunda yapılmış hataları düşün."]] },
      16: { amac: "Veda haccını ve vefatı bir emanetin teslimi olarak okumak.", odak: "Tebliğin sorumluluğu Peygamber'den sonra kime geçti?",
        not: "Câbir b. Abdullah'ın rivayetine göre Hz. Peygamber Arafat'taki hutbesinin sonunda şöyle sordu: “Siz bana soracaksınız; ne diyeceksiniz?” Sahabe “Tebliğ ettiğine, görevini yerine getirdiğine ve nasihat ettiğine şahitlik ederiz” dedi. Bunun üzerine işaret parmağını göğe kaldırıp insanlara doğru indirerek üç kez “Allah'ım, şahit ol!” dedi (Müslim). Hutbede ayrıca “Burada bulunanlar, bulunmayanlara tebliğ etsin” buyurmuştur (Buhârî). Böylece tebliğ, Peygamber'den ümmete devredilmiş bir emanet hâline gelmiştir.",
        tedebbur: [["“Burada bulunanlar bulunmayanlara tebliğ etsin” emri, bugün senin de bu emanetin bir parçası olduğun anlamına geliyor mu?", "Öğrendiğin bir hakikati, bilmeyen birine nasıl ulaştırabileceğini düşün."], ["Hz. Peygamber'in hayatının sonunda insanlardan tebliğine şahitlik istemesi, bir görevi tamamlamanın anlamı hakkında ne söylüyor?", "Kendi sorumluluklarını, sonunda kendisine şahitlik edilecek bir şekilde yerine getirmeyi düşün."]] },
      17: { amac: "Siyeri Peygamber'in evinden bakan bir tanıkla tamamlamak.", odak: "Siyer ile Kur'an arasındaki ilişkiyi tek bir cümle nasıl özetler?",
        not: "Sa'd b. Hişâm, Hz. Âişe'ye Hz. Peygamber'in ahlâkını sorduğunda Hz. Âişe şöyle cevap verdi: “Sen Kur'an okumuyor musun? Onun ahlâkı Kur'an'dı” (Müslim). Bu cevap, siyerin ve Kur'an'ın iki ayrı kaynak değil, aynı hakikatin yazılı ve yaşanmış iki hâli olduğunu söyler. Bu yolda her olayı bir sureyle birlikte okumanın anlamı da budur: Kur'an'da emredilen sabır, af, tevazu ve adalet, Peygamber'in hayatında birer olay olarak karşımıza çıkar.",
        tedebbur: [["“Onun ahlâkı Kur'an'dı” sözü, Kur'an'ı okurken Peygamber'in hayatından örnekler aramaya nasıl davet ediyor?", "Okuduğun bir âyetin, Peygamber'in hayatında hangi olayda yaşandığını düşün."], ["Bu yolda okuduğun olaylardan hangisi, Kur'an'ın bir emrini en canlı şekilde yaşanmış olarak gösterdi?", "Tâif'teki duayı, fetihteki affı veya Hudeybiye'deki sabrı hatırla."]] }
    },
    sentez: "Siyerden bir olay seç (örneğin Tâif, Hudeybiye veya Mekke'nin fethi). Olayı kısaca anlat, o dönemde inen veya o olayla ilişkili bir âyeti bul ve Hz. Peygamber'in o olaydaki tavrının bu âyeti nasıl yaşadığını açıkla. Sonunda, bu olayın senin hayatındaki benzer bir duruma nasıl ışık tuttuğunu yaz." },
  "usul-kavramlari": {
    buyukResim: "Bir fakih, bir âyetten veya hadisten nasıl hüküm çıkarır? Hakkında hiçbir nas bulunmayan yeni bir meselede neye dayanır? Bu yol, bu soruların cevabını veren fıkıh usulünün aletlerini tek tek tanıtır. Önce delillerin ve hükümlerin genel haritasını, aklın iyiyi ve kötüyü bilip bilemeyeceği tartışmasını ve sünnetin konumunu görürsün. Sonra lafızların nasıl anlaşıldığını öğrenirsin: genel ve özel lafızlar, emir ve nehiy, nassın açık ve dolaylı anlamları. Ardından nas bulunmayan yerlerde başvurulan yöntemlere geçersin: icmâ, kıyas, istihsân, maslahat, örf, sedd-i zerâi' ve istishâb. En sonda şeriatın amaçlarını ve müctehid ile mukallidin konumunu öğrenirsin. “Fıkıh Nasıl Düşünür?” yolu sana meseleleri gösterdi; bu yol o meselelerin arkasındaki aletleri tanıtır.",
    hedefler: ["Fıkıh usulünün temel delillerini ve hüküm türlerini açıklayabilmek.", "Lafızların anlaşılmasındaki mezhep farklarının hükümlere nasıl yansıdığını gösterebilmek.", "Nas bulunmayan meselelerde kullanılan yöntemleri ve sınırlarını değerlendirebilmek.", "Bir fıkıh meselesini okurken arkasındaki usul aletini tanıyabilmek."],
    sure: "Yaklaşık 3-4 hafta", onbilgi: "“Fıkıh Nasıl Düşünür?” yolunu önce tamamlamak faydalıdır.",
    etaplar: [
      ["Deliller ve temeller", 0, 2, "Delillerin sıralaması, aklın rolü ve sünnetin konumu, fıkıh usulünün temel taşlarıdır. Bu üç meseleden hangisinde alınan bir tavır, diğer bütün usul tercihlerini etkiler?"],
      ["Lafzın dili", 3, 6, "Hâs, âmm, emir ve delâlet, nassın lafzını anlamanın kurallarıdır. Bu kurallar sence dilin doğal işleyişini mi yansıtıyor, yoksa fakihlerin bir tercihi mi?"],
      ["Nas bulunmayan yerde", 7, 14, "İcmâ, kıyas, istihsân, maslahat, örf, sedd-i zerâi', istishâb ve sahabe kavli: Bu sekiz yöntem, nasların sustuğu yerde fıkhı hem sınırlayan hem de genişleten araçlardır. Hangileri daha çok “sınırlayıcı”, hangileri daha çok “genişletici” işlev görüyor?"],
      ["Amaçlar ve müctehid", 15, 17, "Makâsıd, ictihad ve taklid, fıkhın hem amacını hem de onu yürüten insanları anlatır. Bu üç kavram, bugün bir Müslümanın fıkıhla ilişkisini nasıl şekillendirmeli?"]
    ],
    adim: {
      0: { amac: "Fıkıh usulünün genel haritasını edinmek.", odak: "Bir hüküm nelerden oluşur?",
        not: "Usulcüler hükümleri ikiye ayırır: teklîfî hükümler ve vaz'î hükümler. Teklîfî hükümler (farz, vacip, haram gibi) mükellefin ne yapması gerektiğini bildirir. Vaz'î hükümler ise bu teklîfî hükümlerin hangi şartlarda geçerli olacağını belirler: sebep (namaz vaktinin girmesi), şart (abdest), mâni' (hayız), sıhhat ve fesad, azîmet ve ruhsat. Bu ayrımın önemli bir sonucu vardır: Vaz'î hükümler mükellef olmayanları da ilgilendirebilir. Örneğin bir çocuk başkasının malına zarar verirse, teklîfî bir sorumluluğu olmadığı hâlde, zararın tazmini (vaz'î hüküm) onun malından karşılanır.",
        tedebbur: [["Teklîfî ve vaz'î hüküm ayrımı, bir ibadetin “farz” olması ile “geçerli” olması arasındaki farkı nasıl açıklıyor?", "Bir kişinin abdestsiz namaz kılmasının, farzı yerine getirmemiş olmak mı yoksa geçersiz bir namaz kılmak mı olduğunu düşün."], ["Bir çocuğun verdiği zararın tazmin edilmesi, sorumluluk ile hak arasındaki ilişki hakkında ne söylüyor?", "Zarar görenin hakkının, zarar verenin sorumlu olup olmamasından bağımsız olarak korunmasını düşün."]] },
      1: { amac: "Aklın iyiyi ve kötüyü bilme gücü tartışmasını öğrenmek.", odak: "Vahiy gelmeden insan sorumlu olur mu?",
        not: "Bu tartışmanın en somut sonucu, kendisine peygamber daveti ulaşmamış kimselerin (ehl-i fetret) durumudur. Eş'arîler İsrâ 15'e dayanarak onların kurtuluşta olduğunu söyler. Buhara Mâtürîdîleri de buna yakındır; Semerkant Mâtürîdîleri ise aklen Allah'ı tanımanın vacip olduğunu kabul eder. Ahmed b. Hanbel'in rivayet ettiği bir hadis üçüncü bir yol gösterir: Kıyamet günü sağır, akıl hastası, çok yaşlı ve fetret döneminde ölen dört kişi Allah'a hüccet getirecek; Allah onlara bir elçi gönderip onları sınayacak ve emrine uyan kurtulacaktır. İbn Teymiyye ve İbnü'l-Kayyim bu görüşü tercih eder.",
        tedebbur: [["Kendisine davet ulaşmamış kişilerin âhirette sınanacağı görüşü, Allah'ın adaleti hakkında nasıl bir tasavvur sunuyor?", "Bilmediği bir şeyden dolayı birinin sorumlu tutulmasının adaletle bağdaşıp bağdaşmayacağını düşün."], ["Aklın iyiyi ve kötüyü bilebilmesi, vahyin değerini azaltır mı?", "Aklın genel ilkeleri bilebileceğini, ama ayrıntıları ve ibadet şekillerini ancak vahyin bildirebileceğini düşün."]] },
      2: { amac: "Sünnetin Kur'an'la ilişkisini usul açısından değerlendirmek.", odak: "Sünnet, Kur'an'da olmayan yeni bir hüküm getirebilir mi?",
        not: "Şâtıbî, el-Muvâfakāt'ta sünnetin manasıyla Kur'an'a döndüğünü savunur: Her sünnetin Kur'an'da bir aslı vardır; sünnet ya Kur'an'ın mücmelini açıklar, ya mutlakını kayıtlar ya da onun genel ilkelerini bir olaya uygular. Cumhur ise sünnetin bazen Kur'an'da bulunmayan bağımsız bir hüküm (istiklâl) getirebileceğini söyler. Bir kadının halası veya teyzesiyle aynı anda nikâhlanmasının yasaklanması buna örnek gösterilir. Şâtıbî bu örneği de, iki kız kardeşin bir arada nikâhlanmasını yasaklayan âyetin (Nisâ 23) gerekçesinin genişletilmesi olarak açıklar.",
        tedebbur: [["Şâtıbî'nin “sünnet manasıyla Kur'an'a döner” görüşü, sünneti okurken Kur'an'daki dayanağını aramaya nasıl davet ediyor?", "Bildiğin bir sünnetin Kur'an'daki asıl dayanağını bulmaya çalış."], ["Sünnetin bağımsız hüküm getirebileceği görüşü ile Şâtıbî'nin görüşü arasındaki fark, sünnetin bağlayıcılığını değiştirir mi?", "İki görüşün de sünneti bağlayıcı saydığını, farkın yalnızca onun Kur'an'la ilişkisinin nasıl kurulduğunda olduğunu düşün."]] },
      3: { amac: "Lafzın anlam bakımından kısımlarını ve hükme etkisini görmek.", odak: "Tek bir kelimenin iki anlamı, bir hükmü nasıl ikiye böler?",
        not: "Bakara 228'deki “kur'” kelimesi tartışmasının sahabe döneminden başladığı bilinir: Hz. Ömer, Hz. Ali ve İbn Mes'ûd bunu “hayız” olarak, Hz. Âişe ve Zeyd b. Sâbit ise “temizlik” olarak anlamıştır. Şâfiîler kendi görüşlerini bir dilbilgisi inceliğiyle de destekler: Âyette sayı (selâse) müennes olarak kullanılmıştır; Arapçada sayı, saydığı şeyin cinsiyetinin tersine gelir. Bu durumda sayılan şeyin müzekker olması gerekir; “temizlik” (tuhr) müzekker, “hayız” (hayza) ise müennestir. Hanefîler ise sayının “kur'” kelimesinin lafzına göre geldiğini söyler.",
        tedebbur: [["Aynı kelimeyi sahabe arasında bile farklı anlayanlar olması, müşterek lafızlarda ihtilafın kaçınılmazlığı hakkında ne söylüyor?", "Dilin doğal çok anlamlılığının, farklı ama meşru yorumları nasıl mümkün kıldığını düşün."], ["Bir dilbilgisi kuralının bir hükmü belirlemesi, fıkıh için Arapça bilgisinin önemi hakkında ne söylüyor?", "Bir çevirinin bu tür incelikleri taşıyıp taşıyamayacağını düşün."]] },
      4: { amac: "Genel ve özel lafızların ilişkisini öğrenmek.", odak: "Genel bir hüküm, istisnasız mıdır?",
        not: "Usul kitaplarında İbn Abbâs'a nispet edilen bir söz sıkça nakledilir: “Tahsis edilmemiş hiçbir âmm lafız yoktur.” Bu sözün istisnaları da hemen hatırlatılır: “Allah her şeyi bilendir” (Bakara 282) gibi âyetler hiçbir şekilde daraltılamaz. Şâfiîler bu sözü, âmmın delâletinin zannî olduğuna delil gösterir: Neredeyse her genel lafız daraltılmaya açık olduğuna göre, hiçbir âmm lafız kapsamının tamamını kesin olarak ifade etmez. Hanefîler ise tahsisin bir delille sabit olması gerektiğini, delil yoksa âmmın bütün fertleri kesin olarak kapsadığını savunur.",
        tedebbur: [["“Tahsis edilmemiş âmm yoktur” sözü doğruysa, genel bir âyete dayanarak hüküm verirken nasıl bir dikkat gerekir?", "Genel bir âyetin, başka bir âyet veya hadisle daraltılıp daraltılmadığını araştırmanın önemini düşün."], ["Âmmın kesin mi zannî mi olduğu tartışması, âyet ile hadis arasındaki ilişkiyi nasıl etkiliyor?", "Fâtiha ve besmele gibi meselelerde bu tartışmanın nasıl belirleyici olduğunu hatırla."]] },
      5: { amac: "Emir ve nehyin neyi ifade ettiğini öğrenmek.", odak: "Bir emir her zaman farz mı bildirir?",
        not: "Usulcüler emrin aslında vücûb (gereklilik) ifade ettiğini iki delille gösterir. Birincisi, “Onun emrine aykırı davrananlar, başlarına bir belâ gelmesinden veya elem verici bir azaba uğramaktan sakınsın” (Nûr 63) âyetidir; emre muhalefet bir tehditle karşılanmıştır. İkincisi misvak hadisidir: “Ümmetime zor gelmeseydi, her namazda misvak kullanmalarını emrederdim” (Buhârî, Müslim). Misvak zaten tavsiye edilen bir sünnetti; Hz. Peygamber'in yine de “emrederdim” demesi, emrin tavsiyeden öte bir gereklilik ifade ettiğini gösterir.",
        tedebbur: [["Misvak hadisindeki inceliği nasıl açıklarsın? Hz. Peygamber'in bir şeyi emretmekten kaçınması, ümmete karşı merhameti hakkında ne söylüyor?", "Bir şeyin çok faziletli olmasına rağmen farz kılınmamasının, insanların gücünü gözetmek olduğunu düşün."], ["Bir emrin vücûb mu yoksa tavsiye mi ifade ettiğini belirleyen karîneler nelerdir?", "Emrin bağlamını, tehdit içerip içermediğini ve Hz. Peygamber'in uygulamasını düşün."]] },
      6: { amac: "Nassın açık ve dolaylı anlamlarını ayırt etmek.", odak: "Bir âyetteki şart, şart bulunmadığında hükmün olmadığını mı gösterir?",
        not: "Nisâ 101'de yolculukta namazın kısaltılması “eğer kâfirlerin size fitne vermesinden korkarsanız” şartına bağlanır. Ya'lâ b. Ümeyye, Hz. Ömer'e “Artık insanlar güvende; neden hâlâ kısaltıyoruz?” diye sordu. Hz. Ömer “Senin hayret ettiğin şeye ben de hayret ettim ve bunu Resûlullah'a sordum” dedi. Hz. Peygamber şöyle cevap vermişti: “Bu, Allah'ın size verdiği bir sadakadır; O'nun sadakasını kabul edin” (Müslim). Bu olay, sahabenin bir şartın tersinden hüküm çıkarmayı (mefhûm-ı muhâlif) düşündüğünü, ancak sünnetin bu çıkarımı düzelttiğini gösterir.",
        tedebbur: [["Hz. Ömer'in kendisi de aynı soruyu sormuş olması, bir âyeti anlamaya çalışırken soru sormanın değeri hakkında ne söylüyor?", "Akla gelen bir soruyu bastırmak yerine, onu ehline sormanın ilim yolundaki yerini düşün."], ["Ruhsatın bir “sadaka” olarak nitelenmesi, kolaylıklardan faydalanmaya nasıl bakmamız gerektiğini gösteriyor?", "Bir ruhsatı kullanmamanın bazen bir ikramı geri çevirmek gibi olabileceğini düşün."]] },
      7: { amac: "İcmâın delil değerini ve sınırlarını öğrenmek.", odak: "Ümmetin bir konuda ittifak etmesi neden bağlayıcıdır?",
        not: "İcmâın Kur'an'daki delili olarak genellikle Nisâ 115 gösterilir: “Kim kendisine doğru yol apaçık belli olduktan sonra Peygamber'e karşı çıkar ve müminlerin yolundan başkasına uyarsa, onu döndüğü yolda bırakırız.” Beyhakî ve Sübkî, İmam Şâfiî'nin icmâın Kur'an'daki delilini bulmak için Kur'an'ı defalarca baştan sona okuduğunu ve sonunda bu âyette karar kıldığını nakleder. Hadislerden ise “Ümmetim dalâlet üzerinde birleşmez” rivayeti delil gösterilir; bu rivayetin senetleri tek tek zayıf olsa da âlimler onların toplamının bir manevî tevâtür oluşturduğunu söyler.",
        tedebbur: [["Şâfiî'nin icmâın delilini Kur'an'da bulmak için gösterdiği çaba, bir ilkeyi kabul etmeden önce onun dayanağını aramanın önemi hakkında ne söylüyor?", "Kabul ettiğin bir dinî ilkenin delilini bilip bilmediğini düşün."], ["Ahmed b. Hanbel'in “icmâ iddia eden yalan söylemiş olabilir” uyarısı, kitaplarda karşılaştığın “bu konuda icmâ vardır” ifadelerine nasıl yaklaşman gerektiğini gösteriyor?", "Bir icmâ iddiasını, farklı görüş bildiren âlimler olup olmadığını araştırarak sınamayı düşün."]] },
      8: { amac: "Kıyasın mantığını ve meşruiyetini kavramak.", odak: "Hz. Peygamber kıyas yaptı mı?",
        not: "Hz. Peygamber'in bazı cevaplarında kıyasın açık örnekleri görülür. Cüheyne kabilesinden bir kadın, haccetmeden ölen annesi adına hac yapıp yapamayacağını sorduğunda şöyle buyurmuştur: “Annenin bir borcu olsaydı onu öder miydin? Allah'ın borcunu ödeyin; Allah vefa gösterilmeye daha layıktır” (Buhârî). Hz. Ömer oruçluyken eşini öptüğünü söyleyip endişelendiğinde de Hz. Peygamber “Oruçluyken ağzına su alıp çalkalasan ne olur?” diye sormuştur (Ebû Dâvûd). Her iki örnekte de bilinen bir hükümden yola çıkılarak benzer bir duruma hüküm verilmektedir.",
        tedebbur: [["Hz. Peygamber'in bir soruya doğrudan hüküm vermek yerine bir benzetmeyle cevap vermesi, nasıl bir öğretim yöntemidir?", "Muhatabın kendi aklıyla sonuca ulaşmasını sağlamanın, ezberletmekten farkını düşün."], ["Ağzı çalkalamak ile öpmek arasındaki benzerlik nedir? Bu iki durumu birleştiren illeti bulmaya çalış.", "Her ikisinin de orucu bozan fiilin başlangıcı olduğu hâlde o fiile varmadığını düşün."]] },
      9: { amac: "İstihsânın ne olduğunu ve neden tartışıldığını öğrenmek.", odak: "Kıyastan dönmek ne zaman meşrudur?",
        not: "Serahsî istihsânı şöyle tanımlar: “İstihsân, kıyası terk edip insanlar için daha kolay ve daha uygun olanı almaktır.” Hanefîler bu yöntemi Zümer 18. âyetle destekler: “Sözü dinleyip de onun en güzeline uyan kullarımı müjdele.” Şâfiî'nin istihsâna yönelttiği “şeriat koymak” eleştirisi, Hanefîlerin istihsânı keyfî bir “beğenme” olarak değil, daha güçlü bir delil sebebiyle kıyastan dönme olarak tanımlamasıyla büyük ölçüde cevaplanmıştır. Kerhî'nin tanımı da bunu vurgular: Bir meselede benzerlerinde verilen hükümden, daha güçlü bir sebep dolayısıyla farklı bir hükme geçmek.",
        tedebbur: [["“İnsanlar için daha kolay olanı almak” ilkesi, keyfîliğe kapı açmadan nasıl uygulanabilir?", "Kolaylığın bir delile dayanması ile yalnızca bir arzuya dayanması arasındaki farkı düşün."], ["İstihsân tartışmasının büyük ölçüde terimin farklı anlaşılmasından kaynaklanması, ilmî tartışmalarda kavramları netleştirmenin önemi hakkında ne söylüyor?", "Bir tartışmaya girmeden önce kullanılan terimlerin ne anlama geldiğini sormanın değerini düşün."]] },
      10: { amac: "Maslahatın delil olarak kullanımını görmek.", odak: "Hiçbir nassın bahsetmediği bir uygulama nasıl meşru olur?",
        not: "Şâtıbî, el-İ'tisâm'da maslahat-ı mürseleye örnek olarak zanaatkârların tazmin sorumluluğunu gösterir. Kural olarak kendisine bir eşya emanet edilen kişi, kusuru olmadıkça onu tazmin etmez. Ancak terzi, boyacı gibi zanaatkârlar kendilerine bırakılan eşyalarda bu kurala dayanarak ihmalkâr davranınca, Hz. Ali onları tazminle sorumlu tutmuş ve “İnsanları ancak bu düzeltir” demiştir. Bu uygulama doğrudan bir nassa dayanmaz; ama insanların mallarını korumak gibi şeriatın açık bir amacına hizmet eder.",
        tedebbur: [["Hz. Ali'nin uygulaması, bir kuralın kötüye kullanıldığında nasıl değiştirilebileceğini gösteriyor. Bugün kötüye kullanılan hangi kurallar akla geliyor?", "Bir kuralın amacına hizmet etmediği, aksine onu engellediği durumları düşün."], ["Maslahatın sınırını Gazâlî'nin şartlarıyla (zarûrî, küllî ve kesin olması) belirlemek, keyfî kullanımları nasıl engeller?", "Bir maslahat iddiasının, gerçekten genel bir yarar mı yoksa belirli bir grubun çıkarı mı olduğunu sorgulamayı düşün."]] },
      11: { amac: "Örfün hükümdeki yerini ve şartlarını öğrenmek.", odak: "Toplumun alışkanlıkları hangi şartlarla hükme esas olur?",
        not: "Örfün delil olarak kullanılmasının dayanaklarından biri İbn Mes'ûd'un şu sözüdür: “Müslümanların güzel gördüğü şey Allah katında da güzeldir; Müslümanların çirkin gördüğü şey Allah katında da çirkindir” (Ahmed, mevkûf). Fakihler örfün hükme esas olabilmesi için bazı şartlar belirlemiştir: Örfün yaygın ve süregelen bir uygulama olması (muttarid), hükmün bağlandığı işlem sırasında mevcut olması, tarafların açıkça aksini şart koşmamış olması ve bir nassa aykırı olmaması. Bu şartlar, örfün bir keyfîlik aracına dönüşmesini engeller.",
        tedebbur: [["İbn Mes'ûd'un sözü, toplumun ahlâkî sezgisine nasıl bir değer veriyor? Bu sezginin yanılabileceği durumlar var mı?", "Bir toplumun yaygın bir yanlışı “güzel” görebileceğini ve bu yüzden nassa aykırı olmama şartının neden gerekli olduğunu düşün."], ["Bugün senin yaşadığın toplumun örfüne bağlı olarak değişen hangi uygulamalar var?", "Mehir, düğün âdetleri, ticari teamüller gibi örneklerle düşün."]] },
      12: { amac: "Harama götüren yolları kapatma ilkesini ve sınırlarını öğrenmek.", odak: "Her harama götürebilecek şey yasaklanmalı mıdır?",
        not: "Karâfî, el-Furûk'ta zerîaları (harama götürebilecek yolları) üç gruba ayırır. Birincisi, kapatılması üzerinde ittifak edilenlerdir: Müslümanların geçtiği yola kuyu kazmak veya yiyeceklerine zehir katmak gibi. İkincisi, açık bırakılması üzerinde ittifak edilenlerdir: Şarap yapımında kullanılabileceği gerekçesiyle üzüm bağı dikmenin yasaklanmaması gibi. Üçüncüsü ise ihtilaflı olanlardır: vadeli satışlar gibi. Karâfî'nin şu sözü de meşhurdur: “Vesileler, maksatların hükmünü alır.” Harama götüren vesile haram, vacibe götüren vesile ise vaciptir.",
        tedebbur: [["Üzüm bağı örneği, sedd-i zerâi' ilkesinin sınırını nasıl gösteriyor?", "Kötüye kullanılma ihtimali olan her şeyi yasaklamanın, hayatı nasıl imkânsız hâle getireceğini düşün."], ["“Vesileler, maksatların hükmünü alır” ilkesini kendi hayatına uygula. Bir iyiliğe götüren hangi vesileleri ihmal ediyorsun?", "Feth-i zerâi' kavramını, yani iyiliğe götüren yolları açmayı düşün."]] },
      13: { amac: "Kesinliğin şüpheyle kalkmayacağı ilkesini öğrenmek.", odak: "Şüphe anında neye göre karar vermeliyim?",
        not: "İstishâbın en açık nebevî temeli abdest şüphesine dair hadistir: Namazda abdestinin bozulup bozulmadığından şüphe eden kişi hakkında Hz. Peygamber şöyle buyurmuştur: “Bir ses duymadıkça veya bir koku almadıkça namazdan çıkmasın” (Buhârî, Müslim). Abdest kesin olarak alınmıştır; bozulduğu ise şüphelidir. Kesin olan şüpheyle ortadan kalkmaz. Bu ilkenin bir uygulaması da “eşyada aslolan ibâhadır” kaidesidir: Haramlığına dair bir delil bulunmadıkça, bir şeyin mubah olduğu kabul edilir.",
        tedebbur: [["Abdest şüphesi hadisi, vesvese ile mücadelede nasıl bir yol gösteriyor?", "Şüphe her geldiğinde ona göre davranmanın, insanı nasıl bir kısır döngüye soktuğunu düşün."], ["“Eşyada aslolan ibâhadır” ilkesi, yeni karşılaştığın bir şey hakkında hüküm verirken nasıl bir başlangıç noktası sunuyor?", "Her yeni şeye şüpheyle yaklaşmak ile haramlığına dair bir delil aramak arasındaki farkı düşün."]] },
      14: { amac: "Sahabe görüşünün bağlayıcılığı tartışmasını öğrenmek.", odak: "Sahabenin bir görüşü, sonraki nesiller için neden önemlidir?",
        not: "Sahabenin fetvaları ve uygulamaları büyük ölçüde Abdürrezzâk es-San'ânî ve İbn Ebî Şeybe'nin Musannef adlı eserlerinde derlenmiştir. Bu eserler, sahabe ve tâbiûnun binlerce görüşünü konulara göre toplar ve mezheplerin oluşumundan önceki fıkhın en zengin arşividir. İbnü'l-Kayyim, İ'lâmü'l-muvakkıîn'de sahabe görüşüne uymanın gerekliliğini kırk altı ayrı gerekçeyle savunur. Bu gerekçelerin özü, sahabenin vahyin indiği ortamı bizzat yaşaması, dili en iyi bilmesi ve Hz. Peygamber'in amacını en yakından gözlemlemesidir.",
        tedebbur: [["Sahabenin vahyin indiği ortamı bizzat yaşaması, onların görüşlerine nasıl bir değer kazandırıyor?", "Bir olayı yaşayan biri ile onu sonradan okuyan biri arasındaki anlama farkını düşün."], ["Sahabe kendi aralarında ihtilaf ettiğinde, onların görüşlerinin dışına çıkmamak ne anlama gelir?", "Ahmed b. Hanbel'in, sahabenin görüşlerinden birini seçmekle yetinip yeni bir görüş üretmemesini düşün."]] },
      15: { amac: "Şeriatın amaçlarını ve aralarındaki ilişkiyi kavramak.", odak: "Beş zarurî değer her zaman aynı sırayla mı korunur?",
        not: "Klasik makâsıd sıralamasında din, canın önünde yer alır. Ancak Nahl 106'nın iniş sebebi bu sıralamanın mutlak olmadığını gösterir: Ammâr b. Yâsir, işkence altında Hz. Peygamber'i kötüleyen sözler söylemek zorunda kalmış, sonra ağlayarak Hz. Peygamber'e gelmişti. Hz. Peygamber “Kalbini nasıl buluyorsun?” diye sormuş, “İmanla dolu” cevabını alınca “Tekrar yaparlarsa sen de tekrar et” buyurmuştur. Âyet de “Kalbi imanla dolu olduğu hâlde zorlanan kimse müstesna” der. Böylece canın korunması için dinin dış ifadesinden geçici olarak vazgeçilmesine izin verilmiştir. Bazı âlimler beş değerin yanına “ırz”ı (namus) da ekler.",
        tedebbur: [["Ammâr'ın durumu, dinin korunmasının kalpteki iman ile dildeki ifade arasında nasıl bir ayrım yapılarak gerçekleştiğini gösteriyor?", "Dinin özünün kalpte olduğunu ve dış ifadenin zorlama karşısında esneyebileceğini düşün."], ["Makâsıd değerleri birbiriyle çatıştığında, sıralamayı belirleyen ölçüler nelerdir?", "Zararın büyüklüğünü, geri dönüşü olup olmamasını ve kalıcılığını düşün."]] },
      16: { amac: "İctihadın meşruiyetini ve farklı sonuçlara açıklığını görmek.", odak: "Aynı emri farklı anlayan iki grup da haklı olabilir mi?",
        not: "Hendek savaşından sonra Hz. Peygamber sahabeye “Hiçbiriniz ikindiyi Benî Kurayza'dan başka yerde kılmasın” buyurdu. Yolda ikindi vakti girince sahabe ikiye ayrıldı: Bir grup emrin lafzına bağlı kalarak namazı Benî Kurayza'ya varınca kıldı; diğer grup ise emrin amacının acele etmek olduğunu düşünerek namazı yolda kıldı. Durum Hz. Peygamber'e anlatıldığında, hiçbir grubu kınamadı (Buhârî). Bu olay, lafza bağlı kalma ile amaca bakma eğilimlerinin ikisinin de meşru olduğunu gösteren ilk ictihad ihtilaflarından biridir.",
        tedebbur: [["Hz. Peygamber'in iki grubu da kınamaması, ihtilaf eden insanlara bakışın nasıl olması gerektiği hakkında ne söylüyor?", "Senden farklı bir sonuca varan birinin de iyi niyetli bir çaba gösterdiğini kabul etmeyi düşün."], ["Sen olsaydın hangi grupta olurdun? Bu tercih, senin dinî meselelere yaklaşımın hakkında ne söylüyor?", "Lafza mı yoksa amaca mı daha çok ağırlık verdiğini dürüstçe düşün."]] },
      17: { amac: "Taklid ve ittiba arasındaki farkı ve mezhep imamlarının tavrını öğrenmek.", odak: "Mezhep imamları kendilerinin nasıl takip edilmesini istediler?",
        not: "Mezhep imamlarının kendileri, delilsiz taklide karşı uyarılarda bulunmuştur. Ebû Hanîfe'nin şöyle dediği nakledilir: “Delilimizin nereden alındığını bilmeden bizim sözümüzle fetva vermek hiç kimseye helal değildir.” İmam Mâlik de şöyle demiştir: “Ben ancak bir insanım; hata da ederim, isabet de ederim. Görüşüme bakın; Kitap ve sünnete uyanı alın, uymayanı bırakın” (İbn Abdilber). Bu sözler, mezheplere bağlılığın körü körüne bir taklid değil, delile ulaşmanın güvenilir bir yolu olarak görülmesi gerektiğini gösterir.",
        tedebbur: [["İmamların kendilerinin delilsiz taklide karşı uyarması, bugün bir mezhebe bağlılığı nasıl anlamamız gerektiğini gösteriyor?", "Mezhebi bir otorite olarak değil, delile götüren güvenilir bir rehber olarak görmeyi düşün."], ["Bu yolun sonunda, kendi mezhebinin bir görüşünü delil ve usulüyle birlikte açıklayabilir misin?", "Bu yolda öğrendiğin usul aletlerinden en az ikisini kullanarak bir meseleyi açıklamayı dene."]] }
    },
    sentez: "Bu yolda öğrendiğin usul kavramlarından üçünü seç ve her biri için şu soruları cevapla: Bu kavram nedir? Hangi mezhepler onu nasıl kullanır? Hangi fıkıh meselesinde belirleyici olmuştur? Sonunda, bu üç kavramın birbiriyle nasıl bir ilişki içinde olduğunu ve bir meseleye birlikte nasıl uygulanabileceğini kısa bir paragrafla yaz." },

  "dusunce-tarihi": {
    buyukResim: "İslâm düşüncesinin tarihi, yalnızca ekollerin ve kitapların bir listesi değildir. Bu tarih, her biri bugünkü tartışmalarımızın kökünde yatan büyük kırılma anlarıyla şekillenmiştir. Bu yol seni bu anlara götürür: Büyük günah tartışmasının ve Hâricîlerin doğuşuna, devletin bir inancı dayattığı Mihne'ye, Eş'arî ve Mâtürîdî'nin Ehl-i sünnet kelâmını kurmasına, Gazâlî ile İbn Rüşd arasındaki felsefe tartışmasına, Moğol istilası sonrası arayışlara, Osmanlı ilim düzenine ve modern dönemin ıslah ve ihya hareketlerine. Her kırılmada bir âlimin hayatını ve meselenin kendisini birlikte okursun. Amaç, bugün karşılaştığın bir tartışmanın hangi tarihî köke dayandığını görebilmektir.",
    hedefler: ["İslâm düşünce tarihinin büyük kırılma anlarını ve bu anların sebeplerini açıklayabilmek.", "Bugünkü dinî ve fikrî tartışmaların tarihî köklerini görebilmek.", "Farklı dönemlerdeki âlimlerin, kendi dönemlerinin krizlerine nasıl cevap verdiğini değerlendirebilmek.", "Düşünce tarihine taassupsuz ve bağlamını gözeten bir bakış geliştirebilmek."],
    sure: "Yaklaşık 3-4 hafta", onbilgi: "“İnancın Derin Soruları” yolu faydalı bir hazırlıktır.",
    etaplar: [
      ["İlk ayrılıklar ve Mihne", 0, 3, "Büyük günah tartışması ve Mihne, inancın siyasetle iç içe geçtiği iki kırılmadır. Birincisinde bir grup diğerlerini tekfir etti, ikincisinde devlet bir inancı dayattı. Bu iki tecrübe, din ile siyaset ilişkisi hakkında ne öğretiyor?"],
      ["Ehl-i sünnet kelâmının kuruluşu", 4, 6, "Eş'arî Basra'da, Mâtürîdî Semerkant'ta, birbirinden habersiz olarak benzer bir orta yolu kurdu. İki ayrı coğrafyada benzer sonuçlara varılması sana ne düşündürüyor?"],
      ["Felsefe, Moğol ve kriz", 7, 10, "Gazâlî felsefeyi eleştirdi, İbn Rüşd onu savundu; İbn Teymiyye Moğol yıkımının ardından selefe dönüş çağrısı yaptı, İbn Haldûn ise toplumların yükseliş ve çöküşünü inceledi. Bu dört âlim, kendi dönemlerinin krizine hangi farklı cevapları verdi?"],
      ["Osmanlı ve ihya", 11, 14, "Ebussuûd şeriat ile kanunu, Kâtip Çelebi tartışan gruplar arasında ölçüyü, Rabbânî ve Dihlevî ise çöküş karşısında ihyayı aradı. Bu âlimler, bir medeniyeti ayakta tutmak için hangi dengeleri gözettiler?"],
      ["Modern dönem", 15, 17, "Efgânî siyasi uyanışı, Abduh eğitim ve aklı, Said Nursi ise imanın kurtarılmasını öne çıkardı. Modern dönemin krizine verilen bu üç farklı cevabı nasıl değerlendiriyorsun?"]
    ],
    adim: {
      0: { amac: "İslâm tarihindeki ilk büyük fikrî kırılmayı tanımak.", odak: "Bir siyasi anlaşmazlık nasıl bir inanç tartışmasına dönüştü?",
        not: "Hâricîler, Sıffîn savaşında Hz. Ali'nin Muâviye ile hakem yoluyla anlaşmayı (tahkîm) kabul etmesine itiraz ederek ondan ayrıldılar. Sloganları “Hüküm ancak Allah'ındır” (lâ hukme illâ lillâh) idi; bu, Yûsuf 40'taki bir âyetin ifadesiydi. Hz. Ali bu slogan için şöyle demiştir: “Hak bir söz, ama onunla bâtıl kastediliyor” (Müslim). Hâricîler, insanların hakem tayin etmesini Allah'ın hükmüne ortak koşmak saydı ve kendilerine katılmayan Müslümanları büyük günah işlemekle suçlayarak tekfir ettiler. Büyük günah tartışması böyle siyasi bir ayrılıktan doğmuştur.",
        tedebbur: [["Hz. Ali'nin “Hak bir söz, ama onunla bâtıl kastediliyor” tespiti, bugün kutsal metinlerin siyasi amaçlarla kullanılmasına nasıl uygulanabilir?", "Doğru bir âyetin yanlış bir bağlamda ve yanlış bir amaçla kullanılabileceğini düşün."], ["Hâricîlerin tekfir anlayışı, bugünkü aşırı akımlarda nasıl yansımalar buluyor?", "Kendisi gibi düşünmeyeni dinden çıkarma eğiliminin tarihî köklerini düşün."]] },
      1: { amac: "Bir zâhidin, siyaset ve kader tartışmalarının ortasındaki tavrını görmek.", odak: "Zalim bir yöneticiye karşı isyan meşru mudur?",
        not: "İbnü'l-Eş'as, Emevî valisi Haccâc'a karşı büyük bir isyan başlattığında (81-83/700-702), Basra'nın pek çok âlimi bu isyana katıldı. Hasan-ı Basrî ise katılmadı ve insanları da katılmamaya çağırdı. İbn Sa'd'ın naklettiğine göre gerekçesi şuydu: “Haccâc, Allah'ın bir cezasıdır. Allah'ın cezasını kılıçlarınızla karşılamayın; onu tevbe ve Allah'a yalvararak karşılayın.” İsyan büyük bir kanla bastırıldı. Hasan'ın bu tavrı, zalim yöneticiye karşı silahlı isyanın fitneye yol açacağı ve sabırla ıslahın tercih edilmesi gerektiği görüşünün, sonraki Ehl-i sünnet siyaset düşüncesindeki temellerinden biri olmuştur.",
        tedebbur: [["Hasan-ı Basrî'nin zulmü açıkça eleştirdiği hâlde isyana katılmaması, eleştiri ile isyan arasındaki farkı nasıl gösteriyor?", "Bir yanlışa karşı sesini yükseltmek ile ona silahla karşı çıkmak arasındaki farkı düşün."], ["Zulmü “Allah'ın bir cezası” olarak görmek, bir edilgenlik mi yoksa bir öz eleştiri çağrısı mı?", "Bir toplumun başına gelenlerde kendi payını sorgulamasının anlamını düşün."]] },
      2: { amac: "Devletin bir inancı dayattığı ilk büyük tecrübeyi tanımak.", odak: "Bir inanç devlet gücüyle dayatıldığında ne olur?",
        not: "Mihne sırasında sorgulanan Ahmed b. Hanbel'in tavrı tek bir cümleyle özetlenir: “Bana Allah'ın kitabından veya Resûlünün sünnetinden bir şey getirin, onu söyleyeyim.” Sorgulayanlar ona aklî deliller ve kelâmî tartışmalarla karşılık verdiğinde, o yalnızca nas istemiştir. Bu tavır, meselenin özünü gösterir: Ahmed'e göre Allah'ın sıfatları gibi gaybî konularda, devletin desteklediği bir kelâmî yorumu halka dayatmak meşru değildi. Mihne, Mu'tezile'nin devlet desteğini kaybetmesine ve Ehl-i hadisin halk nezdindeki itibarının artmasına yol açarak düşünce tarihinin seyrini değiştirmiştir.",
        tedebbur: [["Bir inancın devlet gücüyle dayatılması, o inancın kendisine nasıl bir zarar veriyor?", "Mihne'nin sonunda Mu'tezile'nin halk nezdinde itibarını kaybetmesini düşün."], ["Ahmed b. Hanbel'in “Bana nas getirin” tavrı, gaybî konularda nasıl bir sınır çiziyor?", "Aklın her konuda söz söyleyebileceği ile bazı konularda vahyin sınırında durması gerektiği arasındaki dengeyi düşün."]] },
      3: { amac: "Mihne'nin sembol ismini ve onun sonrasındaki tavrını tanımak.", odak: "Zorluktan sonra gelen bolluk da bir imtihan mıdır?",
        not: "Mihne sona erip halife Mütevekkil Ahmed b. Hanbel'e hediyeler göndermeye ve onu saraya davet etmeye başlayınca, Ahmed bu ikramlardan rahatsız olmuştur. Oğlu Sâlih'in naklettiğine göre bu dönemi, kırbaçlandığı ve hapsedildiği yıllardan daha ağır bir imtihan olarak görmüş ve gönderilen hediyeleri kabul etmemiştir. Ayrıca kendisini kırbaçlatanları helal ettiği de nakledilir. Bu tavır, onun direnişinin bir iktidar mücadelesi değil, bir ilke bağlılığı olduğunu gösterir: Ne baskı ne de ikram onu ilkesinden uzaklaştırmıştır.",
        tedebbur: [["Ahmed b. Hanbel'in ikramı baskıdan daha ağır bir imtihan olarak görmesi, refahın insanı nasıl değiştirebileceği hakkında ne söylüyor?", "Zorluk anlarında koruduğun bir ilkeyi, rahatlık anlarında ne kadar koruyabildiğini düşün."], ["Kendisine işkence yapanları affetmesi, onun direnişinin niteliği hakkında ne söylüyor?", "Bir davayı savunurken kişisel kin beslememenin önemini düşün."]] },
      4: { amac: "Ehl-i sünnet kelâmının kurucularından birinin dönüşümünü görmek.", odak: "Bir âlimin kendi geçmişiyle hesaplaşması nasıl olur?",
        not: "İbn Asâkir'in naklettiğine göre Eş'arî, Mu'tezile'den ayrıldığını Basra Camii'nde minbere çıkarak ilan etmiştir: “Kim beni tanıyorsa tanıyor; tanımayana kendimi tanıtayım. Ben Kur'an'ın mahluk olduğunu söylüyordum... Şimdi bu inançlardan tövbe ediyorum.” Ardından üzerindeki elbiseyi çıkarıp atarak “Bu elbiseden nasıl sıyrılıyorsam, eski inançlarımdan da öyle sıyrılıyorum” demiştir. Zehebî ise onun son sözlerinin şöyle olduğunu nakleder: “Ehl-i kıbleden hiç kimseyi tekfir etmediğime şahit ol; çünkü hepsi aynı mabuda işaret ediyor, farklılık yalnızca ifadelerdedir.”",
        tedebbur: [["Eş'arî'nin kırk yaşında yıllarca savunduğu görüşleri açıkça terk etmesi, ilmî dürüstlük hakkında ne söylüyor?", "Uzun süre savunduğun bir görüşün yanlış olduğunu fark ettiğinde, bunu kabul etmenin zorluğunu düşün."], ["Eş'arî'nin son sözü, kelâmî tartışmaların ateşli olduğu bir dönemde nasıl bir ölçü sunuyor?", "Farklı görüşteki Müslümanların aynı Allah'a yöneldiğini kabul etmenin, tartışmaları nasıl yumuşatabileceğini düşün."]] },
      5: { amac: "Ehl-i sünnet kelâmının ikinci kurucusunu ve iki ekol arasındaki ilişkiyi görmek.", odak: "Eş'arîler ile Mâtürîdîler ne kadar farklıdır?",
        not: "Eş'arî ve Mâtürîdî ekolleri arasındaki ihtilaflı meseleler, sonraki âlimlerin ilgisini çekmiştir. Tâceddîn es-Sübkî, bir kasidesinde iki ekol arasındaki ihtilaflı meseleleri on üç olarak sayar ve bunların bir kısmının yalnızca lafzî olduğunu belirtir. Osmanlı Şeyhülislâmı Kemalpaşazâde de bu konuda on iki meseleyi ele alan bir risale yazmıştır. Bu çalışmaların ortak sonucu, iki ekolün temel inanç esaslarında birleştiği, ayrılıkların ise ayrıntılarda ve yöntemde olduğudur. Bu yüzden ikisi birlikte “Ehl-i sünnet” olarak anılır.",
        tedebbur: [["Ehl-i sünnetin iki ayrı kelâm ekolünü birlikte kabul etmesi, inanç birliği ile yorum çeşitliliğinin bir arada bulunabileceği hakkında ne söylüyor?", "Temel esaslarda birleşip ayrıntılarda farklılaşmanın, bir geleneği nasıl zenginleştirdiğini düşün."], ["İki ekol arasındaki ihtilafların bir kısmının “lafzî” olması, tartışmalarda kavramları netleştirmenin önemi hakkında ne söylüyor?", "Aynı şeyi farklı kelimelerle söyleyen iki kişinin, birbirini ne kadar kolay yanlış anlayabileceğini düşün."]] },
      6: { amac: "Ehl-i sünnet kimliğinin tarihsel ve itikadî çerçevesini kavramak.", odak: "Ehl-i sünnet olmak ne demektir?",
        not: "Lâlekâî'nin naklettiğine göre İbn Abbâs, “O gün bazı yüzler ağarır, bazı yüzler kararır” (Âl-i İmrân 106) âyetini şöyle tefsir etmiştir: “Ehl-i sünnet ve cemaatin yüzleri ağarır; bid'at ve ayrılık ehlinin yüzleri kararır.” “Ehl-i sünnet ve'l-cemaat” ifadesindeki iki kelime iki ayrı vurguyu taşır: Sünnet, Hz. Peygamber'in yoluna bağlılığı; cemaat ise ümmetin birliğini korumayı ve ayrılıkçılıktan kaçınmayı anlatır. Ehl-i sünnet kimliği, Hâricîlerin tekfirciliğine ve Şîa'nın sahabe hakkındaki tutumuna karşı, sahabenin tamamına saygıyı ve ümmetin birliğini koruma çabası olarak şekillenmiştir.",
        tedebbur: [["“Sünnet” ve “cemaat” kelimelerinin birlikte kullanılması, doğru inanç ile birlik arasında nasıl bir bağ kuruyor?", "Doğru inancı korurken ümmetin birliğini gözetmenin önemini düşün."], ["Eş'arî, Mâtürîdî ve Eserî çizgilerin birbirini Ehl-i sünnet dairesinde sayıp saymaması, bugünkü tartışmalarda nasıl bir yer tutuyor?", "Bir kimliği daraltarak tanımlamanın ve genişleterek tanımlamanın sonuçlarını düşün."]] },
      7: { amac: "Gazâlî'nin felsefeyle hesaplaşmasını ve ölçüsünü görmek.", odak: "Gazâlî felsefenin tamamını mı reddetti?",
        not: "Gazâlî, el-Munkız'da felsefî ilimleri ayrı ayrı değerlendirir: Matematik ve mantık ilimlerinin dinle olumlu veya olumsuz hiçbir ilişkisi olmadığını, bunları reddetmenin dine zarar vereceğini söyler; çünkü kesin delillerle sabit olan bir şeyi reddeden, dinin akılla çatıştığı izlenimini doğurur. Eleştirisini metafizik (ilâhiyat) alanına yöneltir. Bu ölçüyü, Hz. Ali'ye nispet edilen bir sözle özetler: “Hakkı adamlarla tanımaya çalışma; hakkı tanı, ehlini de tanırsın.” Yani bir fikrin değeri, onu söyleyenin kimliğine göre değil, kendisine göre belirlenmelidir.",
        tedebbur: [["“Hakkı adamlarla tanımaya çalışma; hakkı tanı, ehlini de tanırsın” ilkesi, bugün farklı kaynaklardan gelen bilgilere nasıl yaklaşmamız gerektiğini gösteriyor?", "Bir fikri, söyleyenin kimliğine göre kabul veya reddetmenin tehlikesini düşün."], ["Gazâlî'nin matematik ve mantığı reddetmenin dine zarar vereceği uyarısı, din ile bilim ilişkisine nasıl bir çerçeve sunuyor?", "Kesin bilgiyi reddetmenin, dinin inandırıcılığını nasıl zedeleyebileceğini düşün."]] },
      8: { amac: "Felsefenin şer'î meşruiyetini savunan bir fakih-filozofu tanımak.", odak: "Felsefe ile uğraşmak dinen nasıl değerlendirilmeli?",
        not: "İbn Rüşd, Faslü'l-makāl'e fıkhî bir soruyla başlar: Felsefe ile uğraşmanın şer'î hükmü nedir? Cevabını Haşr 2'deki “İbret alın, ey basiret sahipleri!” emrine dayandırır: Kur'an varlıklar üzerinde akıl yürütmeyi emrettiğine göre, ehliyeti olan kişi için felsefe ile uğraşmak vaciptir. Bununla birlikte insanları üç sınıfa ayırır: kesin delillerle ikna olanlar (burhân ehli), tartışmayla ikna olanlar (cedel ehli) ve hitabetle ikna olanlar (hitâbet ehli). Felsefî te'vîllerin halka açıklanmaması gerektiğini, çünkü bunun halkın imanını sarsabileceğini savunur.",
        tedebbur: [["İbn Rüşd'ün insanları ikna yollarına göre üç sınıfa ayırması, dinî bir konuyu farklı insanlara anlatırken nasıl bir dikkat gerektiğini gösteriyor?", "Herkese aynı dille konuşmanın her zaman doğru olmadığını düşün."], ["İbn Rüşd'ün düşüncesinin İslâm dünyasından çok Latin Batı'da etkili olması, bir medeniyetin kendi düşünürlerine nasıl sahip çıkması gerektiği hakkında ne düşündürüyor?", "Bir düşünürün kendi toplumunda unutulup başka bir yerde değer bulmasının sebeplerini düşün."]] },
      9: { amac: "Moğol istilası sonrası bir âlimin fikrî ve siyasi cevabını görmek.", odak: "Yeni bir siyasi gerçeklik karşısında klasik kategoriler nasıl yeniden düşünülür?",
        not: "Moğolların hâkimiyetindeki Mardin şehri hakkında sorulan bir soruya İbn Teymiyye'nin verdiği cevap, “Mardin fetvası” olarak meşhurdur. Klasik fıkıh dünyayı “dârülislâm” ve “dârülharp” olarak ikiye ayırıyordu. İbn Teymiyye ise Mardin'in ne tam olarak birincisi ne de ikincisi olduğunu, “mürekkep” (karma) bir üçüncü kategori olduğunu söyler: Oradaki Müslümana Müslüman olarak muamele edilir, şeriatın dışına çıkanlara ise hak ettikleri muamele yapılır. Bu fetva, modern dönemde bazı aşırı gruplar tarafından çarpıtılarak kullanılmış; 2010'da Mardin'de düzenlenen uluslararası bir konferansta âlimler fetvanın bağlamını ve doğru anlaşılmasını yeniden ele almıştır.",
        tedebbur: [["İbn Teymiyye'nin klasik ikili ayrımın yetmediği bir durumda üçüncü bir kategori önermesi, değişen şartlar karşısında fıkhın esnekliği hakkında ne söylüyor?", "Eski kategorilerin yeni gerçeklikleri anlatmakta yetersiz kaldığı durumları düşün."], ["Bir fetvanın bağlamından koparılarak çarpıtılması, klasik metinleri okurken nasıl bir dikkat gerektiğini gösteriyor?", "Bir sözün söylendiği zamanı, yeri ve soruyu bilmeden onu anlamanın imkânsızlığını düşün."]] },
      10: { amac: "Tarihi ve toplumu ilmî bir yöntemle inceleyen bir düşünürü tanımak.", odak: "Bir tarihî haberin doğruluğu nasıl sınanır?",
        not: "İbn Haldûn, Mukaddime'nin başında tarihçilerin sık düştüğü hataları gösterir. Örneklerinden biri, Mesûdî gibi tarihçilerin Hz. Mûsâ'nın çölde İsrâiloğulları'ndan altı yüz binden fazla savaşçı saydığı rivayetidir. İbn Haldûn bu rakamı senedine bakarak değil, “imkân” ölçüsüyle reddeder: O dönemde Mısır ve Şam'ın böyle bir orduyu besleyecek nüfusu ve kaynağı yoktu; ayrıca bu büyüklükte bir ordu savaş alanında birbirini göremez ve yönetilemezdi. İbn Haldûn'a göre bir haber, umrânın (toplumsal hayatın) yasalarına uygun olup olmadığına bakılarak sınanmalıdır.",
        tedebbur: [["İbn Haldûn'un bir haberi “imkân” ölçüsüyle sınaması, hadis yolunda öğrendiğin metin tenkidiyle nasıl bir benzerlik taşıyor?", "Bir haberin senedi kadar içeriğinin de akla ve gerçekliğe uygunluğunun önemini düşün."], ["Bugün karşılaştığın bir haberi “imkân” ölçüsüyle sınamayı dene. Hangi sorular sorarsın?", "Haberin anlattığı şeyin, bilinen şartlar altında gerçekleşip gerçekleşemeyeceğini düşün."]] },
      11: { amac: "Osmanlı'da şeriat ile devlet düzeni arasındaki dengeyi görmek.", odak: "Bir fetva nasıl bir dille verilir?",
        not: "Ebussuûd'un fetvaları, Osmanlı fetva üslubunun en olgun örneklerindendir. Bu fetvalarda soru, kişilerin gerçek isimleri yerine “Zeyd”, “Amr” ve “Hind” gibi temsilî isimlerle sorulur; cevap ise çoğu zaman “Olur”, “Olmaz” veya kısa bir hüküm cümlesinden ibarettir. Bu üslubun bir amacı vardır: Fetva, olayı kişilerden ve tarafların duygularından arındırarak soyut bir hukukî soruya dönüştürür. Böylece müftü taraf olmaz, yalnızca hükmü bildirir. Ebussuûd'un binlerce fetvası, Osmanlı toplumunun gündelik hayatının da eşsiz bir kaynağıdır.",
        tedebbur: [["Bir meseleyi kişilerden arındırarak soyut bir soruya dönüştürmek, adil bir hüküm vermeye nasıl yardım eder?", "Bir anlaşmazlıkta tarafları tanımanın, değerlendirmeyi nasıl etkileyebileceğini düşün."], ["Kısa ve net bir fetva üslubunun avantajları ve dezavantajları nelerdir?", "Bir hükmün gerekçesini bilmeden onu uygulamanın sınırlarını düşün."]] },
      12: { amac: "Dinî tartışmalarda ölçülü bir dilin değerini görmek.", odak: "Kızışmış bir tartışmada nasıl bir tavır alınmalı?",
        not: "Kâtip Çelebi, Mîzânü'l-hak'ta Kadızâdeliler ile sûfîler arasındaki tartışmaları (tütün, kahve, musafaha, devran, kabir ziyareti ve benzeri) tek tek ele alır ve her birinde iki tarafın delillerini değerlendirir. Kitabın sonunda vaizlere ve tartışmacılara dikkat çekici bir öğüt verir: Halkın yerleşmiş âdetlerini zorla ve bir anda değiştirmeye çalışmak, fayda yerine fitne doğurur. Bir âdet şeriata açıkça aykırı değilse, onu yok etmeye çalışmak yerine insanları yumuşak bir dille uyarmak ve hakkı ölçülü bir şekilde anlatmak gerekir.",
        tedebbur: [["Kâtip Çelebi'nin “halkın âdetlerini zorla değiştirmeye çalışmak fitne doğurur” uyarısı, bugün dinî tartışmalarda nasıl bir ölçü sunuyor?", "Doğru bildiğin bir şeyi anlatırken üslubun, mesajın kabulünü nasıl etkilediğini düşün."], ["İki tarafın delillerini adil bir şekilde değerlendirmek, kızışmış bir tartışmayı nasıl yatıştırabilir?", "Karşı tarafın en güçlü delilini anlamaya çalışmanın, tartışmanın niteliğini nasıl değiştirdiğini düşün."]] },
      13: { amac: "Bir çöküş döneminde ihyanın nasıl gerçekleştiğini görmek.", odak: "Bir âlim, devlet düzenini nasıl etkileyebilir?",
        not: "İmâm-ı Rabbânî, Ekber Şah'ın dinleri birleştiren politikasına karşı silahlı bir mücadele değil, ikna yoluyla bir ıslah yolu seçmiştir. Mektûbât'ındaki mektupların önemli bir kısmı Babür devletinin önde gelen emirlerine yazılmıştır; bu mektuplarda onları şeriata bağlılığa ve devleti ıslah etmeye davet eder. Bu çabanın meyveleri sonraki nesillerde görülmüştür: Rabbânî'nin oğlunun etkisinde yetişen Babür hükümdarı Evrengzîb (Âlemgîr), Hanefî fıkhının geniş bir derlemesi olan Fetâvâ-yı Hindiyye'nin (Fetâvâ-yı Âlemgîriyye) hazırlanmasını desteklemiştir.",
        tedebbur: [["Rabbânî'nin isyan yerine mektuplarla ikna yolunu seçmesi, bir toplumu ıslah etmenin yolları hakkında ne söylüyor?", "Bir değişimin zorla mı yoksa ikna yoluyla mı daha kalıcı olacağını düşün."], ["Bir âlimin çabasının meyvelerini ancak birkaç nesil sonra vermesi, uzun vadeli düşünmenin değeri hakkında ne söylüyor?", "Kendi yaptığın bir işin sonucunu göremeyecek olsan bile onu yapmaya değer bulup bulmadığını düşün."]] },
      14: { amac: "Çöküş çağında İslâm'ı bütüncül olarak yeniden düşünen bir âlimi tanımak.", odak: "Toplumlar nasıl gelişir?",
        not: "Dihlevî, Hüccetullâhi'l-bâliğa'da insan toplumlarının gelişimini dört aşamalı bir teoriyle açıklar ve bu aşamalara “irtifâkāt” adını verir: Birincisi, yeme, içme ve barınma gibi temel ihtiyaçların karşılandığı aşamadır. İkincisi, ev ve aile hayatının, ticaretin ve meslek ahlâkının düzenlendiği aşamadır. Üçüncüsü, şehirlerin yönetimi ve adaletin kurulmasıdır. Dördüncüsü ise farklı şehirler ve devletler arasındaki ilişkileri düzenleyen, hilâfet olarak adlandırdığı uluslararası düzendir. Dihlevî'ye göre şeriatın hükümleri, bu aşamaların her birinde insanların maslahatını gözetecek şekilde gelmiştir.",
        tedebbur: [["Dihlevî'nin toplumların gelişimini aşamalarla açıklaması, şeriatın hükümlerinin toplumsal hayatla ilişkisini anlamaya nasıl yardım ediyor?", "Bir hükmün, toplumun hangi gelişim aşamasıyla ilgili olduğunu sormayı düşün."], ["Dihlevî'nin hükümlerin hikmetlerini açıklama çabası, bugün dinî hükümleri anlatırken nasıl bir yol gösteriyor?", "Bir hükmün gerekçesini anlamanın, ona bağlılığı nasıl güçlendirdiğini düşün."]] },
      15: { amac: "Modern dönemin ilk büyük uyanış çağrısını tanımak.", odak: "Modern ilim kurumları ile geleneksel ulema arasında nasıl bir gerilim yaşandı?",
        not: "Efgânî, 1870'te İstanbul'da yeni kurulan Darülfünun'da sanatların (zanaatların) önemi üzerine bir konferans vermiştir. Konferansta nübüvveti de bir tür “sanat” olarak nitelendirdiği yönündeki ifadeleri, Şeyhülislâm Hasan Fehmi Efendi başta olmak üzere ulemanın sert tepkisine yol açmıştır. Tartışmanın ardından Efgânî İstanbul'dan ayrılmak zorunda kalmıştır. Bu olay, modern eğitim kurumları ile geleneksel ilmiye arasındaki gerilimin ve dinî kavramların modern bir dille ifade edilmesinin doğurduğu tartışmaların erken bir örneğidir.",
        tedebbur: [["Dinî bir kavramı modern bir dille anlatmak, hangi faydaları ve hangi riskleri taşır?", "Bir kavramı yeni bir dille anlatırken onun anlamını değiştirme tehlikesini düşün."], ["Efgânî'nin siyasi uyanış çağrısı ile ilmî derinlik arasındaki dengeyi nasıl değerlendiriyorsun?", "Bir hareketin hızlı etki bırakması ile kalıcı bir ilmî temel oluşturması arasındaki farkı düşün."]] },
      16: { amac: "Islah düşüncesinin önde gelen ismini ve tartışmalı yönlerini görmek.", odak: "Kolaylaştırıcı bir fetva nerede sınırı aşar?",
        not: "Abduh, Mısır müftüsü iken 1903'te Güney Afrika'nın Transvaal bölgesindeki Müslümanlardan gelen bir soruya fetva vermiştir. Sorular, Hristiyanların kestiği hayvanların etini yemenin ve şapka giymenin hükmü hakkındaydı. Abduh her ikisini de caiz görmüş; Ehl-i kitabın yemeğinin helal olduğunu bildiren Mâide 5'i delil göstermiş ve şapka giymenin, bir küfür alameti olarak değil, bir ihtiyaç olarak giyildiğinde dinden çıkarmayacağını söylemiştir. Fetva, gelenekçi çevrelerden sert tepkiler almış ve modern dönemde Batılı toplumlarda yaşayan Müslümanların meselelerine dair ilk büyük tartışmalardan biri olmuştur.",
        tedebbur: [["Abduh'un fetvası, farklı bir toplumda yaşayan Müslümanların meselelerini düşünmenin ilk örneklerinden biridir. Bugün azınlık olarak yaşayan Müslümanlar için bu tür sorular neden önemli?", "Bir hükmün, uygulandığı toplumun şartlarına göre nasıl farklı sonuçlar doğurabileceğini düşün."], ["Bir fetvanın kolaylaştırıcı olması ile dinin sınırlarını aşındırması arasındaki farkı nasıl ayırt edersin?", "Fetvanın bir nassa dayanıp dayanmadığını ve bir ihtiyaca cevap verip vermediğini düşün."]] },
      17: { amac: "Modern dönemde iman hizmetini merkeze alan bir âlimi tanımak.", odak: "Hürriyet ve şeriat birbiriyle nasıl ilişkilendirilebilir?",
        not: "Said Nursi, 1911'de Doğu Anadolu'daki aşiretler arasında dolaşarak onların meşrutiyet ve hürriyet hakkındaki sorularına cevap vermiş, bu konuşmaları daha sonra Münâzarât adıyla yayımlanmıştır. Bu eserde meşrutiyeti, Kur'an'ın “Onların işleri aralarında istişareyledir” (Şûrâ 38) ilkesinin bir uygulaması olarak savunur ve istibdada karşı “hürriyet-i şer'iyye” kavramını geliştirir: Şeriatın sınırları içinde, insanın onurunu koruyan ve başkasına tahakküm etmeyen bir hürriyet. Bu, onun daha sonraki dönemlerinde siyasetten uzaklaşıp iman hizmetine yönelmesinden önceki bir düşünce evresidir.",
        tedebbur: [["“Hürriyet-i şer'iyye” kavramı, hürriyet ile dinî sorumluluk arasında nasıl bir denge kuruyor?", "Bir insanın hem özgür hem de sorumlu olmasının ne anlama geldiğini düşün."], ["Said Nursi'nin önce siyasi bir mücadeleye girip sonra iman hizmetine yönelmesi, kendi döneminin krizini nasıl teşhis ettiği hakkında ne söylüyor?", "Bir toplumun asıl krizinin siyasi mi yoksa imanî mi olduğu sorusunu düşün."]] }
    },
    sentez: "Bugün karşılaştığın bir dinî veya fikrî tartışmayı seç. Bu tartışmanın kökünü bu yolda gördüğün kırılmalardan birine bağla: O kırılmada hangi soru soruldu, hangi cevaplar verildi ve bu cevaplar bugünkü tartışmayı nasıl şekillendiriyor? Sonunda, o kırılmadaki bir âlimin tavrından bugün için çıkardığın bir dersi yaz." },
  iman: {
    buyukResim: "İman, bir bilgi listesi değil, insanın kalbinde doğan, büyüyen, zayıflayan ve korunması gereken canlı bir hakikattir. Bu yol, imanı bu canlılığıyla ele alır. Önce imanın esaslarını, insanın yaratılıştan getirdiği yatkınlığı (fıtrat) ve iman edilen Allah'ı tanıtan İhlâs suresini görürsün. Sonra imanın ne olduğu üzerine yapılan büyük tartışmalara girersin: İman ile amel ilişkisi, imanın artıp eksilmesi ve delilsiz imanın geçerliliği. Ardından imanın sınırlarını, yani büyük günah ve tekfir meselelerini öğrenirsin. En sonda imanı kalpte kökleştirmenin ve delil ile tefekkürle güçlendirmenin yollarına ulaşırsın. Yolun sorusu şu: İmanım nedir, nasıl artar ve nasıl korunur?",
    hedefler: ["İmanın esaslarını Kur'an'daki dayanaklarıyla birlikte açıklayabilmek.", "İmanın tanımı, artıp eksilmesi ve amelle ilişkisi konusundaki görüşleri değerlendirebilmek.", "Büyük günah ve tekfir konularında Ehl-i sünnetin ölçülü tavrını kavrayabilmek.", "Kendi imanını taklitten tahkike doğru güçlendirmek için somut adımlar belirleyebilmek."],
    sure: "Yaklaşık 3 hafta", onbilgi: "Gerekmez.",
    etaplar: [
      ["İmanın temelleri", 0, 2, "İmanın esasları, fıtrat ve İhlâs suresi birlikte okunduğunda, iman bir dışarıdan öğrenilen bilgi mi, yoksa insanın içinde zaten bulunan bir şeyin uyanması mı?"],
      ["İmanın tanımı ve dereceleri", 3, 6, "Ebû Hanîfe'nin tanımı, imanın artıp eksilmesi ve taklidî iman tartışmaları, imanın hem bir kesinlik hem de derecelenen bir hâl olduğunu gösteriyor. Bu iki yön nasıl bir arada bulunur?"],
      ["İmanın sınırları", 7, 9, "Büyük günah ve tekfir tartışmaları, kimin mümin sayılacağı sorusunun ne kadar hassas olduğunu gösterir. Ehl-i sünnetin bu konudaki ölçülü tavrı, toplumsal barış için neden önemlidir?"],
      ["İmanın kökleşmesi ve korunması", 10, 14, "Mâtürîdî aklı, kalp konusu iç dünyayı, Gazâlî eğitimi, Said Nursi tahkiki, Asr suresi ise toplumu öne çıkarır. İmanı korumak için bu beş unsurdan hangisine en çok ihtiyacın var?"]
    ],
    adim: {
      0: { amac: "İmanın esaslarını ve Kur'an'daki dayanaklarını öğrenmek.", odak: "İmanın esasları Kur'an'da nerede bir arada anılır?",
        not: "Âmentü'de sayılan iman esasları, Kur'an'ın birkaç yerinde toplu olarak geçer. Bakara 285'te Peygamber ve müminlerin “Allah'a, meleklerine, kitaplarına ve peygamberlerine” iman ettiği bildirilir. Nisâ 136'da ise bunlara âhiret günü eklenir ve “Kim Allah'ı, meleklerini, kitaplarını, peygamberlerini ve âhiret gününü inkâr ederse, derin bir sapıklığa düşmüştür” denir. Bakara 177 de iyiliği (birr) bu esaslara iman ve ardından gelen amellerle tanımlar. Kader esası ise Cibrîl hadisinde açıkça sayılır ve Kamer 49'daki “Biz her şeyi bir ölçüye göre yarattık” âyetine dayandırılır.",
        tedebbur: [["Bakara 177'nin iyiliği önce iman esaslarıyla, sonra yetime, yoksula ve yolcuya yardımla tanımlaması, iman ile ahlâkın ilişkisi hakkında ne söylüyor?", "İmanın kalpte kalan bir kabul değil, davranışa dönüşen bir bağlılık olduğunu düşün."], ["İman esaslarını sayabilmek ile her birinin hayatına etkisini hissetmek arasında nasıl bir fark var?", "Meleklere imanın, amellerinin yazıldığını bilmek olarak senin davranışlarını nasıl etkilediğini düşün."]] },
      1: { amac: "İmanın insanın yaratılışındaki kökünü kavramak.", odak: "İnsan imana yatkın olarak mı doğar?",
        not: "A'râf 172'de Allah'ın, Âdemoğullarının sırtlarından zürriyetlerini çıkarıp onlara “Ben sizin Rabbiniz değil miyim?” (Elestü bi-rabbiküm) diye sorduğu ve onların “Evet, şahit olduk” dediği bildirilir. Bu olay “mîsâk” veya “elest bezmi” olarak anılır. Ehl-i sünnet âlimlerinin çoğu bunu ruhlar âleminde gerçekleşmiş gerçek bir ahid olarak anlar. Bazı müfessirler ise bunu temsilî bir anlatım olarak yorumlar: Allah insanlara akıl ve kâinatta kendisini gösteren deliller vermiştir; bu, onların ağzından bir şahitlik alınmış gibidir. Her iki yorum da imanın insan için yabancı değil, onun yaratılışına işlenmiş bir şey olduğunu anlatır.",
        tedebbur: [["Elest bezmindeki ahid hatırlanmıyorsa, insan bundan nasıl sorumlu olur?", "Fıtratın bir hafıza değil, bir yatkınlık ve özlem olarak varlığını sürdürdüğünü düşün."], ["Hayatında, bir hakikati ilk kez duyduğunda onu sanki önceden biliyormuş gibi hissettiğin bir an oldu mu?", "Fıtratın, hakikatle karşılaştığında onu tanıyan bir iç ses olabileceğini düşün."]] },
      2: { amac: "İman edilen Allah'ı tevhidin boyutlarıyla tanımak.", odak: "Tevhid yalnızca Allah'ın bir olduğunu söylemek midir?",
        not: "Âlimler tevhidi farklı boyutlarıyla sınıflandırmıştır. Mâtürîdî ve Eş'arî kelâmcılar tevhidi Allah'ın zâtında, sıfatlarında ve fiillerinde bir olması olarak açıklar: Zâtı bölünmez ve benzersizdir, sıfatları yaratılmışların sıfatlarına benzemez, fiillerinde ortağı yoktur. İbn Teymiyye ise tevhidi rubûbiyet (yaratma ve yönetmede birlik), ulûhiyet (ibadette birlik) ve isim ve sıfatlarda birlik olarak üçe ayırır ve Mekke müşriklerinin birincisini kabul ettiği hâlde ikincisini reddettiğini vurgular. İhlâs suresi bu boyutların hepsini dört âyette toplar.",
        tedebbur: [["Mekke müşriklerinin Allah'ı yaratıcı olarak kabul edip ibadette O'na ortak koşması, bugün “inanıyorum ama” diyen tavırlara nasıl bir ayna tutuyor?", "Allah'a inanmak ile hayatın her alanında yalnızca O'na yönelmek arasındaki farkı düşün."], ["İhlâs suresinin her âyetini tevhidin bir boyutuyla eşleştirmeye çalış.", "“Ehad” zâtı, “Samed” ihtiyaç ve yönelişi, “doğurmamış ve doğmamış” benzersizliği anlatıyor olabilir."]] },
      3: { amac: "İman ile amel arasındaki ilişkiyi kavramak.", odak: "İmanın bir “tadı” var mıdır?",
        not: "Hz. Peygamber şöyle buyurmuştur: “Üç şey kimde bulunursa, imanın tadını (halâvetü'l-îmân) bulur: Allah ve Resûlünün kendisine her şeyden daha sevimli olması, sevdiği kişiyi yalnızca Allah için sevmesi ve Allah onu küfürden kurtardıktan sonra küfre dönmekten, ateşe atılmaktan hoşlanmadığı gibi hoşlanmaması” (Buhârî, Müslim). Bu hadis, imanın yalnızca bir tasdik veya ameller bütünü değil, sevgi ve hoşnutluk içeren bir tecrübe olduğunu gösterir. Âlimler bu tadın, ibadetlerde huzur bulmak ve Allah için zorluklara katlanmayı tatlı bulmak şeklinde hissedildiğini söyler.",
        tedebbur: [["Hadiste sayılan üç şeyden hangisi sende en güçlü, hangisi en zayıf?", "Sevgilerinin sıralamasını ve kimi neden sevdiğini dürüstçe düşün."], ["İmanın bir “tat” olarak tarif edilmesi, ibadetlerini bir yük olarak mı yoksa bir lezzet olarak mı yaşadığını sorgulamaya nasıl davet ediyor?", "İbadette huzur bulamadığın zamanların sebebini düşün."]] },
      4: { amac: "İmanın tanımında Ebû Hanîfe'nin yaklaşımını görmek.", odak: "Amel imanın parçası değilse, onun önemi azalır mı?",
        not: "Ebû Hanîfe'ye nispet edilen el-Âlim ve'l-müteallim adlı eserde, ameli imanın parçası saymamanın gerekçesi bir örnekle açıklanır: Hayız hâlindeki bir kadın namaz kılmaz ve orucu erteler; Allah ona bu amelleri bir süreliğine düşürmüştür. Ama hiç kimse onun bu süre içinde imanının azaldığını veya düştüğünü söylemez. Demek ki amel iman olmasaydı bile iman yerinde durur; amel ise imana tabidir. Aynı eserde amelin önemsiz olmadığı da vurgulanır: Ameli terk eden, imanını kaybetmez ama Allah'ın emrine aykırı davranmış olur.",
        tedebbur: [["Hayızlı kadın örneği, iman ile amel arasındaki ilişkiyi nasıl açıklıyor? Bu örnek ikna edici mi?", "Bir amelin bir mazeret sebebiyle düşmesi ile tembellik sebebiyle terk edilmesi arasındaki farkı düşün."], ["Ebû Hanîfe'nin tanımı, büyük günah işleyen bir mümine bakışını nasıl etkiler?", "Bir insanın hatasını onun imanından ayırmanın, ona ümit kapısını açık tutmak olduğunu düşün."]] },
      5: { amac: "İmanın derecelerini Gazâlî'nin bir benzetmesiyle kavramak.", odak: "Aynı şeye inanan insanların imanı aynı derecede midir?",
        not: "Gazâlî, İhyâ'nın akideye ayrılan bölümünde imanın derecelerini bir benzetmeyle anlatır: Evde Zeyd'in bulunduğunu üç şekilde bilebilirsin. Birincisi, güvendiğin birinin “Zeyd evde” demesiyle; bu, avamın taklide dayalı imanına benzer. İkincisi, Zeyd'in sesini duyup onun evde olduğu sonucuna varmakla; bu, delillerle elde edilen kelâmcıların imanına benzer. Üçüncüsü, eve girip Zeyd'i bizzat görmekle; bu, ârif ve sıddîkların müşahedeye dayalı imanına benzer. Üçünde de bilinen şey aynıdır; fark, bilginin kesinlik ve canlılık derecesindedir.",
        tedebbur: [["Gazâlî'nin üç derecesinden hangisi senin imanına en çok benziyor?", "İmanının bir haberden mi, bir akıl yürütmeden mi, yoksa bir iç tecrübeden mi beslendiğini düşün."], ["Haber ile, ses ile ve görerek bilmek arasındaki fark, imanını bir üst dereceye taşımak için ne yapman gerektiğini gösteriyor?", "Dinlemekten düşünmeye, düşünmekten yaşamaya geçmenin yollarını düşün."]] },
      6: { amac: "Delilin seviyesinin herkes için aynı olmadığını görmek.", odak: "Basit bir insanın imanı nasıl bir delile dayanabilir?",
        not: "Menâkıb kaynaklarında Ebû Hanîfe'nin Allah'ın varlığını inkâr eden bir grupla tartışması anlatılır. Ebû Hanîfe onlara şunu sorar: “Yükünü kendisi alan, kendisi boşaltan, fırtınada dalgalar arasında kendi yolunu bulan, kaptanı olmayan bir gemi düşünebilir misiniz?” Onlar bunun imkânsız olduğunu söyleyince şöyle der: “Bir gemi bile kaptansız yol alamıyorsa, bu muazzam kâinat nasıl yöneticisiz olabilir?” Bu menkıbe, imanın delilinin her zaman karmaşık kelâmî akıl yürütmeler olması gerekmediğini, herkesin anlayabileceği bir sağduyu deliliyle de kurulabileceğini gösterir.",
        tedebbur: [["Ebû Hanîfe'nin gemi benzetmesi, kendi imanının delillerini başkasına anlatırken nasıl bir yol gösteriyor?", "Karmaşık kavramlar yerine, karşındakinin hayatından bir örnekle konuşmanın etkisini düşün."], ["Senin imanının en güçlü delili nedir? Bunu bir cümleyle ifade edebilir misin?", "Kâinattaki düzen, kendi iç dünyan veya Kur'an'ın etkisi gibi farklı delilleri düşün."]] },
      7: { amac: "Büyük günahın tanımını ve imanla ilişkisini öğrenmek.", odak: "Bir günahın “büyük” olmasını ne belirler?",
        not: "İbn Abbâs'a büyük günahların yedi tane olup olmadığı sorulduğunda, “Yediden çok yetmişe daha yakındır” dediği nakledilir. Ondan ayrıca şu ölçü de rivayet edilir: “Israrla işlenen küçük günah küçük kalmaz; istiğfarla birlikte büyük günah da büyük kalmaz.” Bu söz, bir günahın ağırlığının yalnızca türüyle değil, kişinin ona karşı tavrıyla da belirlendiğini gösterir. Küçük bir günahta ısrar etmek, onu hafife almak anlamına gelir; büyük bir günahtan sonra pişmanlıkla Allah'a dönmek ise onun ağırlığını hafifletir.",
        tedebbur: [["“Israrla küçük günah küçük kalmaz” sözü, hafife aldığın küçük alışkanlıklarına nasıl bakmanı öneriyor?", "Tekrarlanan küçük bir hatanın, karakterde nasıl kalıcı bir iz bırakabileceğini düşün."], ["Büyük günahın kişiyi imandan çıkarmaması, günah işleyen birine karşı tavrını nasıl etkilemeli?", "Günahı yanlış bulmak ile günah işleyeni dışlamak arasındaki farkı düşün."]] },
      8: { amac: "Tekfirin ölçüsünü ve tehlikesini kavramak.", odak: "Bir insanın imanı hakkında kim hüküm verebilir?",
        not: "Üsâme b. Zeyd bir savaşta, kılıcını kaldırdığı anda “Lâ ilâhe illallah” diyen bir adamı, bunu korkudan söylediğini düşünerek öldürdü. Durum Hz. Peygamber'e anlatılınca Üsâme'ye şöyle sordu: “Lâ ilâhe illallah dediği hâlde onu öldürdün mü?” Üsâme “O bunu silahtan korktuğu için söyledi” deyince Hz. Peygamber şöyle buyurdu: “Onun bunu korkudan mı söylediğini anlamak için kalbini yarıp baktın mı?” Hz. Peygamber bu sözü o kadar çok tekrarladı ki Üsâme, “Keşke o gün yeni Müslüman olsaydım” diye temenni etti (Müslim).",
        tedebbur: [["“Kalbini yarıp baktın mı?” sorusu, başkalarının niyetleri ve imanları hakkında hüküm verme eğilimimize nasıl bir sınır çiziyor?", "Bir insanın dışını görebildiğini, ama kalbini ancak Allah'ın bildiğini düşün."], ["Hz. Peygamber'in bu sözü defalarca tekrarlaması, tekfir hatasının ağırlığı hakkında ne söylüyor?", "Bir insanı dinden çıkarmanın, onun hayatını ve onurunu tehlikeye atmak olduğunu düşün."]] },
      9: { amac: "Nesefî akaidinde büyük günah, mağfiret ve şefaat dengesini okumak.", odak: "Allah'ın affı ile günahın ciddiyeti nasıl dengelenir?",
        not: "Ebû Zerr şöyle anlatır: Hz. Peygamber “Lâ ilâhe illallah deyip bu inanç üzere ölen kimse cennete girer” buyurdu. Ebû Zerr “Zina etse de, hırsızlık yapsa da mı?” diye sordu. Hz. Peygamber “Zina etse de, hırsızlık yapsa da” buyurdu. Ebû Zerr soruyu iki kez daha tekrarladı; üçüncüsünde Hz. Peygamber “Ebû Zerr'in burnu sürtülse de!” diye ekledi (Buhârî, Müslim). Ehl-i sünnet âlimleri bu hadisi, büyük günahın imanı yok etmediğine ve mümin için ebedî cehennem olmadığına delil gösterir; ancak bu, günahın cezasız kalacağı değil, Allah'ın dilerse affedeceği anlamına gelir.",
        tedebbur: [["Ebû Zerr'in şaşkınlığı ve sorusunu tekrarlaması, Allah'ın rahmetinin genişliği karşısında insanın hissettiklerini nasıl yansıtıyor?", "Allah'ın rahmetinin, insanın adalet anlayışını aşan bir genişlikte olduğunu düşün."], ["Bu hadis, günah işleyen birine ümitsizlik yerine nasıl bir yol gösterir? Aynı zamanda günaha karşı bir gevşekliğe yol açmaması için nasıl okunmalıdır?", "Ümit ile korkunun bir kuşun iki kanadı gibi dengede olması gerektiğini düşün."]] },
      10: { amac: "Bilgi ile iman arasındaki farkı Mâtürîdî'nin bakışıyla görmek.", odak: "Bir şeyi bilmek, ona iman etmek demek midir?",
        not: "Mâtürîdî ve Hanefî kelâmcılar, imanın yalnızca bir bilgi (marifet) değil, bir tasdik ve teslimiyet olduğunu vurgular. Bunun en açık delili Neml 14. âyettir: Firavun ve kavmi için “Kalpleri onların doğruluğuna kesin olarak inandığı hâlde, zulüm ve büyüklenme yüzünden onları inkâr ettiler” denir. Ehl-i kitaptan bazıları için de “Onu kendi oğullarını tanıdıkları gibi tanırlar” (Bakara 146) buyrulur. Demek ki bir hakikati kesin olarak bilmek, ona iman etmek için yeterli değildir; iman, bilinen hakikate kalbin boyun eğmesini ve onu kabullenmesini de gerektirir.",
        tedebbur: [["Firavun'un hakikati bildiği hâlde kibir yüzünden inkâr etmesi, bilgi ile iman arasındaki mesafeyi nasıl gösteriyor?", "Doğru olduğunu bildiğin bir şeyi, gururun veya çıkarın yüzünden kabullenmekte zorlandığın bir anı düşün."], ["İmanın bir “teslimiyet” olması, onu yalnızca bilgi biriktirerek güçlendirmenin yetersiz olduğunu mu gösterir?", "Bilginin kalbin teslimiyetiyle birleşmediğinde nasıl kuru kalabileceğini düşün."]] },
      11: { amac: "İmanın kalpte nasıl kökleştiğini görmek.", odak: "Kalbe yerleşen bir iman neden kolayca sarsılmaz?",
        not: "Bizans imparatoru Herakleios, Ebû Süfyân'a Hz. Peygamber hakkında bir dizi soru sormuştur. Sorularından biri şuydu: “Onun dinine girenlerden, bu dinden hoşlanmayarak geri dönen oluyor mu?” Ebû Süfyân “Hayır” deyince Herakleios şöyle demiştir: “İman böyledir; onun ferahlığı kalplere karıştığında artık oradan çıkmaz” (Buhârî). Henüz Müslüman olmayan bir hükümdarın bu tespiti, gerçek imanın kalpte bir lezzet ve sükûnet hâline geldiğinde, dış baskılarla kolayca sökülüp atılamayacağını gösterir.",
        tedebbur: [["Herakleios'un “iman kalplere karıştığında oradan çıkmaz” tespiti, senin imanının kalbine ne kadar karıştığını sorgulamaya nasıl davet ediyor?", "İmanının bir alışkanlık mı yoksa kalbine işlemiş bir hakikat mi olduğunu düşün."], ["İmanın kalpte kökleşmesi için neler gereklidir? Zikir, ibadet ve tefekkürün bu süreçteki rolü nedir?", "Ra'd 28'deki “Kalpler ancak Allah'ı anmakla huzur bulur” âyetini hatırla."]] },
      12: { amac: "İman eğitiminin aşamalarını Gazâlî'den öğrenmek.", odak: "Bir çocuğa iman nasıl öğretilir?",
        not: "Gazâlî, İhyâ'nın akide bölümünde iman eğitiminin aşamalarını anlatır: Çocuğa önce akide esasları ezberletilir; sonra yaşı ilerledikçe bunların anlamı yavaş yavaş açılır. Bu ezber, kalbe ekilmiş bir tohum gibidir. Tohumun kök salması ise kelâmî tartışmalarla değil, Kur'an okumak, tefsirini öğrenmek, hadisleri ve anlamlarını okumak ve ibadetlerle meşgul olmakla gerçekleşir. Gazâlî'ye göre kelâmî deliller bu tohumu bir yabancı tehlikeye karşı koruyan bir çit gibidir; ama ağacı büyüten şey ibadet ve tefekkürdür.",
        tedebbur: [["Gazâlî'nin tohum ve çit benzetmesi, imanı güçlendirmede delil ile ibadetin farklı rollerini nasıl açıklıyor?", "Delilin imanı koruduğunu, ibadetin ise onu büyüttüğünü düşün."], ["Çocukluğunda öğrendiğin akide esaslarının anlamı, zamanla senin için nasıl açıldı?", "Ezberlediğin bir duanın veya bir âyetin anlamını yıllar sonra fark ettiğin bir anı düşün."]] },
      13: { amac: "Tahkikî imanın modern dönemdeki önemini kavramak.", odak: "İman insana ne kazandırır?",
        not: "Said Nursi, Yirmi Üçüncü Söz'de imanın insana kazandırdıklarını anlatır ve şu cümleyle özetler: “İman insanı insan eder; belki insanı sultan eder.” Ona göre iman, insanın kâinattaki konumunu değiştirir: İmansız bir insan, sonsuz ihtiyaçları ve sınırlı gücüyle kâinat karşısında yalnız ve âciz bir varlıktır. İman eden insan ise her şeye gücü yeten bir Rabbe dayanır; böylece aczi bir güce, fakrı bir zenginliğe dönüşür. İmanın bu yönü, onu yalnızca âhiret için değil, dünya hayatının anlamı için de vazgeçilmez kılar.",
        tedebbur: [["“İman insanı insan eder” cümlesi, imanın insanın kendi değerine bakışını nasıl değiştirdiğini anlatıyor?", "Kendi aczini ve ihtiyacını hissettiğin bir anda, Allah'a dayanmanın nasıl bir güç verdiğini düşün."], ["Said Nursi'nin taklidî imanın modern dönemde yetersiz kalabileceği uyarısına katılıyor musun? Senin imanını sarsabilecek şüphelere karşı nasıl hazırlanıyorsun?", "Kendi imanının delillerini bilmenin, onu şüphelere karşı nasıl koruyabileceğini düşün."]] },
      14: { amac: "İmanın bir topluluk içinde korunmasını görmek.", odak: "İman yalnızca bireysel bir mesele midir?",
        not: "Hz. Peygamber şöyle buyurmuştur: “Mümin, müminin aynasıdır” (Ebû Dâvûd). Âlimler bu hadisi şöyle açıklar: Ayna, insana kusurlarını gösterir ama bunu kimseye söylemez; gördüğünü abartmadan, olduğu gibi gösterir. Asr suresinin “hakkı ve sabrı tavsiye etmek” emri de bu aynalık ilişkisinin bir ifadesidir: Müminler birbirinin imanını, birbirine nasihat ederek, kusurlarını yumuşak bir dille göstererek ve zorluklarda sabrı hatırlatarak korur. İman, yalnız bırakıldığında zayıflayabilir; bir topluluk içinde ise güçlenir.",
        tedebbur: [["“Mümin müminin aynasıdır” hadisi, bir arkadaşına nasıl nasihat etmen gerektiğini gösteriyor?", "Aynanın kusuru yalnızca karşısındakine gösterdiğini ve başkalarına söylemediğini düşün."], ["Senin imanını besleyen bir “hakkı ve sabrı tavsiye eden” çevren var mı? Yoksa nasıl oluşturabilirsin?", "Bu yolun sonunda imanını korumak için atacağın somut bir adımı düşün."]] }
    },
    sentez: "Bu yolun sonunda kendi imanını anlatan kısa bir yazı yaz. İmanını hangi delillere dayandırıyorsun? Gazâlî'nin üç derecesinden hangisinde olduğunu düşünüyorsun? İmanını taklitten tahkike taşımak için önümüzdeki ay neler yapacaksın? Yazını, Asr suresinin dört şartından birini kendi hayatına uygulayacağın bir kararla bitir." },

  tesettur: {
    buyukResim: "Tesettür çoğu zaman yalnızca bir kıyafet meselesi olarak tartışılır. Kur'an ise örtünmeyi daha geniş bir ahlâkın, haya ve iffetin bir parçası olarak anlatır: Örtünme emri, hem erkeklere hem kadınlara gözlerini sakınmalarını emreden âyetlerle birlikte gelir. Bu yol, tesettürü bu bütünlük içinde ele alır. Önce örtünmenin insanın yaratılışındaki kökünü, takva ve haya ile ilişkisini görürsün. Sonra âyetlerin nasıl tefsir edildiğini ve mezheplerin avret sınırları konusundaki görüşlerini öğrenirsin. Ardından bakış ve kadın-erkek ilişkilerinin edebine geçersin. En sonda bu hükümlerin arkasındaki usul aletlerini ve çağdaş tartışmaları değerlendirirsin. Yolun sorusu şu: Örtünme neyi korumayı amaçlar?",
    hedefler: ["Tesettürün Kur'an'daki dayanaklarını ve haya ahlâkıyla ilişkisini açıklayabilmek.", "Mezheplerin avret sınırları ve yüz örtüsü konusundaki görüşlerini gerekçeleriyle ayırt edebilmek.", "Bakış ahlâkının ve kadın-erkek ilişkilerinin edebini kavrayabilmek.", "Tesettür hakkındaki çağdaş tartışmaları usul aletleriyle değerlendirebilmek."],
    sure: "Yaklaşık 2-3 hafta", onbilgi: "“Fıkıh Nasıl Düşünür?” yolu faydalı bir hazırlıktır.",
    etaplar: [
      ["Haya ve fıtrat", 0, 1, "Takva elbisesi ve haya duygusu, örtünmenin dışarıdan gelen bir kural değil, insanın içinden gelen bir ihtiyaç olduğunu mu gösteriyor?"],
      ["Âyetler ve mezhepler", 2, 5, "İbn Abbâs, Taberî ve Kurtubî aynı âyetlere baktılar. Onların tefsirlerindeki farklar, mezheplerin görüşlerine nasıl yansıdı?"],
      ["Bakış ve ilişkiler", 6, 6, "Göz sakınma emrinin kadınlardan önce erkeklere yöneltilmesi, tesettürün yalnızca kadının sorumluluğu olmadığını nasıl gösteriyor?"],
      ["Usul ve çağdaş tartışmalar", 7, 13, "Âmm, sedd-i zerâi', örf, kıyas ve zaruret kavramları, tesettür hükümlerinin hangi kısmının sabit, hangi kısmının şartlara göre değişebilir olduğunu ayırt etmeye nasıl yardım ediyor?"]
    ],
    adim: {
      0: { amac: "Örtünmenin insanlık tarihinin başındaki kökünü görmek.", odak: "Kur'an örtünmeyi ilk kez hangi kıssada anlatır?",
        not: "A'râf suresi örtünmeyi insanlığın ilk kıssasıyla anlatır: Hz. Âdem ve Hz. Havvâ yasak ağaçtan yediklerinde “ayıp yerleri kendilerine göründü ve cennet yapraklarından üzerlerini örtmeye başladılar” (A'râf 22). Birkaç âyet sonra Allah, insanlara ayıp yerlerini örtecek bir elbise ve süs indirdiğini, ama asıl hayırlı olanın “takva elbisesi” olduğunu bildirir (A'râf 26). Ardından da şeytanın, Âdem ile Havvâ'nın elbiselerini soyarak onlara ayıp yerlerini gösterdiği gibi, insanları da aldatmasına karşı uyarır (A'râf 27). Kıssa, örtünme ihtiyacının insanın yaratılışında bulunduğunu ve şeytanın ilk hedeflerinden birinin bu haya duygusu olduğunu gösterir.",
        tedebbur: [["Âdem ile Havvâ'nın kendiliğinden yapraklarla örtünmeye başlaması, örtünme ihtiyacının insanın doğasında olduğu hakkında ne söylüyor?", "Örtünmenin dışarıdan dayatılan bir kural değil, fıtratın bir talebi olabileceğini düşün."], ["“Takva elbisesi” ifadesi, dış örtünmenin bir iç örtünmeyle tamamlanması gerektiği hakkında ne söylüyor?", "Kıyafetin dışı örttüğünü, takvanın ise kalbi ve davranışları örttüğünü düşün."]] },
      1: { amac: "Haya duygusunun imandaki yerini kavramak.", odak: "Haya bir ahlâk mı, bir iman meselesi mi?",
        not: "Hz. Peygamber şöyle buyurmuştur: “Her dinin bir ahlâkı vardır; İslâm'ın ahlâkı hayadır” (İbn Mâce, Muvatta). Başka hadislerde “Haya imandandır” (Buhârî, Müslim) ve “Haya hayırdan başka bir şey getirmez” (Buhârî, Müslim) buyrulur. Bu hadisler, hayayı yalnızca bir utangaçlık duygusu değil, insanı kötülükten alıkoyan ve iyiliğe yönelten bir iman meyvesi olarak tanımlar. Tesettür, bu haya ahlâkının dışa yansıyan bir ifadesidir; ancak haya, kıyafetten çok daha geniştir: Bakışı, sözü ve davranışı da kapsar.",
        tedebbur: [["“İslâm'ın ahlâkı hayadır” hadisi, hayayı bütün ahlâkın özü olarak tanımlıyor. Haya senin hayatında hangi davranışlarda kendini gösteriyor?", "Hayanın yalnız kıyafette değil, konuşmada, bakışta ve davranışta da görüldüğünü düşün."], ["Hayanın “hayırdan başka bir şey getirmemesi”, onu bir zayıflık olarak gören modern anlayışlara nasıl bir cevap veriyor?", "Hayanın insanı koruyan bir sınır olduğunu ve onun kaybının neleri beraberinde getirdiğini düşün."]] },
      2: { amac: "Avret sınırları konusundaki mezhep görüşlerini ve delillerini öğrenmek.", odak: "Ayaklar avret midir?",
        not: "Ümmü Seleme, Hz. Peygamber'e kadınların eteklerini ne kadar uzatacaklarını sordu. Hz. Peygamber “Bir karış uzatsınlar” buyurdu. Ümmü Seleme “O zaman ayakları açılır” deyince “Bir zirâ (kol boyu) uzatsınlar, daha fazla değil” buyurdu (Tirmizî, Nesâî; sahih). Bu hadis, Hanefî mezhebi içindeki ayakların avret olup olmadığı tartışmasında, ayakların örtülmesi gerektiğini savunanların delillerinden biridir. Ümmü Seleme'nin sorusu da dikkat çekicidir: Sahabe kadınları hükmü yalnızca kabul etmekle kalmamış, onu nasıl uygulayacaklarını titizlikle sormuşlardır.",
        tedebbur: [["Ümmü Seleme'nin hükmün uygulanmasına dair ayrıntılı soruları, bir hükmü anlamak ile onu hayata geçirmek arasındaki ilişki hakkında ne söylüyor?", "Bir hükmü öğrendikten sonra, onu kendi hayatında nasıl uygulayacağını sormanın önemini düşün."], ["Mezhepler arasındaki yüz, el ve ayaklar konusundaki farklar, tesettürün özünde bir ittifak olduğu hâlde ayrıntılarda bir genişlik bulunduğunu nasıl gösteriyor?", "Temelde birleşip ayrıntılarda farklılaşmanın, farklı ihtiyaç ve durumlara nasıl cevap verebildiğini düşün."]] },
      3: { amac: "Tefsirin önde gelen sahabesinin hükümlerin illetine bakışını görmek.", odak: "Bir âyetin uygulanması, şartlar değişince nasıl değişebilir?",
        not: "Nûr 58'de evdeki hizmetçilerin ve çocukların üç vakitte (sabah namazından önce, öğle sıcağında elbiselerin çıkarıldığı zaman ve yatsıdan sonra) odalara izin alarak girmesi emredilir. İkrime'nin naklettiğine göre İbn Abbâs bu âyetin pek uygulanmadığını hatırlatmış ve sebebini şöyle açıklamıştır: O dönemde evlerin kapıları ve perdeleri yoktu; hizmetçi veya çocuk, kişi ailesiyle birlikteyken içeri girebiliyordu. Allah bu yüzden izin istemeyi emretti. Sonra Allah insanlara genişlik verdi, evlere perdeler ve kapılar yapıldı (Ebû Dâvûd). Bu açıklama, bir hükmün amacının, yani mahremiyetin korunmasının, farklı araçlarla gerçekleşebileceğini gösterir.",
        tedebbur: [["İbn Abbâs'ın açıklaması, bir hükmün amacı ile o amaca ulaşmanın aracı arasındaki farkı nasıl gösteriyor?", "Mahremiyetin korunması amacının sabit, onu sağlayan araçların ise değişebilir olduğunu düşün."], ["Bu tür bir akıl yürütmenin sınırı nedir? Hangi hükümlerde araç ile amaç ayrılabilir, hangilerinde ayrılamaz?", "Bir hükmün kendisinin mi yoksa yalnızca uygulama şeklinin mi değiştiğini sormayı düşün."]] },
      4: { amac: "Rivayet tefsirinin imamının kadınların kamusal hayattaki yerine dair görüşünü görmek.", odak: "Bir âlim, döneminin yaygın görüşünden farklı düşünebilir mi?",
        not: "Mâverdî'nin el-Ahkâmü's-sultâniyye'de naklettiğine göre Taberî, kadının her konuda hâkim (kadı) olabileceğini caiz görmüştür. Bu görüş, Hanefîlerin kadının had ve kısas dışındaki konularda hâkim olabileceği görüşünden de, cumhurun kadının hâkim olamayacağı görüşünden de farklıdır. Taberî'nin bu görüşü, onun mezhebinin (Cerîriyye) bağımsız bir ictihad geleneği olduğunu ve klasik dönemde bile kadının kamusal rolü konusunda farklı görüşlerin bulunduğunu gösterir. Bu çeşitlilik, örtünme ile kamusal hayata katılımın birbirini dışlamadığını da düşündürür.",
        tedebbur: [["Taberî'nin farklı görüşü, klasik fıkıh geleneğinin kadının kamusal rolü konusunda tek sesli olmadığını nasıl gösteriyor?", "Bir geleneği tek bir görüşle özdeşleştirmenin onu nasıl daralttığını düşün."], ["Tesettür ile kamusal hayata katılım arasındaki ilişkiyi nasıl görüyorsun? Biri diğerinin şartı mı, engeli mi?", "Örtünmenin, kadının kamusal alanda saygınlığını koruyan bir çerçeve olabileceğini düşün."]] },
      5: { amac: "Tesettürün kıyafetin ötesinde bir davranış ahlâkı olduğunu görmek.", odak: "Tesettür yalnızca kumaşla mı sağlanır?",
        not: "Nûr 31'in sonunda şöyle buyrulur: “Gizledikleri zinetleri bilinsin diye ayaklarını yere vurmasınlar.” Kurtubî bu âyeti tefsir ederken, o dönemde kadınların ayaklarındaki halhalların sesini duyurmak için yere vurduklarını belirtir ve âyetten, dikkat çekmek amacıyla yapılan her davranışın yasak olduğu sonucunu çıkarır. Bu genel ilkeye, “Bir kadın koku sürünüp de kokusunu duysunlar diye bir topluluğun yanından geçerse...” diye başlayan uyarı hadisini (Ebû Dâvûd, Tirmizî, Nesâî) de ekler. Böylece tesettür, yalnızca örtünmek değil, dikkat çekme amacı taşıyan ses, koku ve davranışlardan da sakınmak olarak anlaşılır.",
        tedebbur: [["Halhal sesinin yasaklanması, tesettürün amacının görünmemek değil, dikkat çekmemek olduğunu nasıl gösteriyor?", "Örtülü olduğu hâlde dikkat çeken bir davranışın, tesettürün ruhuna aykırı olabileceğini düşün."], ["Bu ilke bugün hangi davranışlara uygulanabilir? Sosyal medyada paylaşılan görüntüler de bu kapsamda düşünülebilir mi?", "Dikkat çekme amacının, kıyafetten çok bir niyet ve tavır meselesi olduğunu düşün."]] },
      6: { amac: "Bakış ahlâkını bir kıssa ve bir hadisle derinleştirmek.", odak: "İffet bir kadının mı, yoksa herkesin mi sorumluluğudur?",
        not: "Kur'an'da iffetin en çarpıcı örneği bir erkek peygamberin kıssasıdır: Hz. Yûsuf, kendisine sahip olan kadının davetine karşı “Allah'a sığınırım” der ve sonunda “Rabbim! Zindan bana bunların beni çağırdığı şeyden daha sevimlidir” (Yûsuf 33) diyerek hapse girmeyi tercih eder. Hz. Peygamber de kıyamet günü Arş'ın gölgesinde gölgelenecek yedi kişiden birini şöyle anlatır: “Güzel ve mevki sahibi bir kadının davetine ‘Ben Allah'tan korkarım’ diyerek karşılık veren adam” (Buhârî, Müslim). Bu örnekler, iffet ve bakış ahlâkının yalnızca kadınlara değil, erkeklere de yönelen bir sorumluluk olduğunu gösterir.",
        tedebbur: [["Kur'an'ın iffetin en çarpıcı örneğini bir erkek peygamberin kıssasıyla anlatması, iffeti yalnızca kadınlardan bekleyen anlayışlara nasıl bir cevap veriyor?", "Erkeklerin de bakışlarından ve davranışlarından sorumlu olduğunu düşün."], ["Hz. Yûsuf'un zindanı tercih etmesi, bir ilke için bedel ödemeyi göze almak hakkında ne söylüyor?", "Kendi hayatında, bir değeri korumak için bir kolaylıktan vazgeçtiğin bir anı düşün."]] },
      7: { amac: "Nûr 31'deki mahrem listesi üzerinden âyetlerin birlikte okunmasını görmek.", odak: "Bir listede sayılmayan biri, o hükmün dışında mı kalır?",
        not: "Nûr 31, kadının zinetini gösterebileceği kişileri sayar: kocası, babası, kayınpederi, oğulları, üvey oğulları, kardeşleri, kardeşlerinin ve kız kardeşlerinin oğulları ve diğerleri. Ancak listede amca ve dayı yoktur. Cumhur, amca ve dayının mahrem olduğunu Nisâ 23'teki evlenilmesi haram olanlar listesiyle birlikte okuyarak kabul eder; çünkü onlar baba hükmündedir. Tâbiûndan İkrime ve Şa'bî ise bu sükûtun bir hikmeti olduğunu, amca ve dayının kadını kendi oğullarına tarif edebileceği için onların yanında da tam bir rahatlık içinde olmamanın daha uygun olduğunu söylemiştir. Bu tartışma, bir âyetteki sükûtun nasıl yorumlanacağının ve âyetlerin birbiriyle nasıl birlikte okunacağının güzel bir örneğidir.",
        tedebbur: [["Bir âyetin bir şeyi zikretmemesi, onun hükmün dışında kaldığı anlamına mı gelir? Cumhurun yaklaşımı ile İkrime'nin yaklaşımını karşılaştır.", "Âyetlerin birbirini tamamlayan bir bütün olarak okunması gerektiğini düşün."], ["İkrime ve Şa'bî'nin gerekçesi, mahremiyetin yalnızca evlilik yasağıyla değil, ince sosyal ilişkilerle de ilgili olduğunu nasıl gösteriyor?", "Mahremiyetin bir hukuk kategorisi olduğu kadar bir incelik ve edep meselesi de olduğunu düşün."]] },
      8: { amac: "Sedd-i zerâi' ilkesinin değişen şartlarda uygulanmasını görmek.", odak: "Bir izin, şartlar değiştiğinde geri alınabilir mi?",
        not: "Hz. Peygamber kadınların mescide gelmesini yasaklamamış, “Allah'ın kadın kullarını Allah'ın mescitlerinden menetmeyin” buyurmuştur. Ancak Hz. Âişe, kendi döneminde şöyle demiştir: “Resûlullah kadınların sonradan ortaya çıkardıklarını görseydi, İsrâiloğulları'nın kadınlarının menedildiği gibi onları mescitten menederdi” (Buhârî, Müslim). Öte yandan İbn Ömer bu hadisi naklettiğinde oğlu Bilâl'in “Vallahi biz onları meneceğiz” demesine çok kızmış, ona sert bir şekilde karşılık vermiş ve “Ben sana Resûlullah'tan haber veriyorum, sen ise ‘Meneceğiz’ diyorsun!” demiştir (Müslim). Bu iki tavır, sedd-i zerâi' ilkesinin bir nassın açık iznini ne ölçüde kısıtlayabileceği konusundaki gerilimi gösterir.",
        tedebbur: [["Hz. Âişe'nin ihtiyatı ile İbn Ömer'in nassa bağlılığı arasındaki gerilimi nasıl değerlendiriyorsun?", "Bir izni şartlar gerektirdiği için kısıtlamak ile nassın açık iznini ortadan kaldırmak arasındaki farkı düşün."], ["Sedd-i zerâi' ilkesi, kadınların kamusal hayattaki yeri konusunda hangi durumlarda meşru bir tedbir, hangi durumlarda meşru bir hakkın engellenmesi olur?", "Somut bir tehlikeye karşı alınan tedbir ile genel bir şüpheye dayanan yasak arasındaki farkı düşün."]] },
      9: { amac: "Kıyafette örfün belirlediği ile nassın belirlediğini ayırt etmek.", odak: "Kıyafetin şekli mi, yoksa nitelikleri mi belirlenmiştir?",
        not: "Fakihler, tesettüre uygun bir kıyafetin şeklini değil, belirli niteliklerini belirlemiştir: Örtülmesi gereken yerleri örtmesi, içini gösterecek kadar ince olmaması, vücut hatlarını belli edecek kadar dar olmaması ve karşı cinsin kıyafetine benzememesi. Bu niteliklerin içinde kıyafetin rengi, kesimi ve modeli ise her toplumun örfüne bırakılmıştır. Hz. Peygamber'in uyardığı bir başka sınır da “şöhret elbisesi”dir: “Kim dünyada şöhret elbisesi giyerse, Allah ona kıyamet günü zillet elbisesi giydirir” (Ebû Dâvûd, İbn Mâce). Âlimler bunu, insanları kendine baktırmak ve böbürlenmek için giyilen her türlü elbise olarak açıklar.",
        tedebbur: [["Kıyafetin niteliklerinin nasla, şeklinin ise örfle belirlenmesi, farklı kültürlerdeki Müslümanların tesettürünü nasıl etkiler?", "Endonezya'daki bir Müslüman kadın ile Türkiye'deki bir Müslüman kadının farklı kıyafetlerle aynı hükmü yerine getirebileceğini düşün."], ["“Şöhret elbisesi” uyarısı, tesettürlü bir kıyafetin de bir gösteriş aracına dönüşebileceği hakkında ne söylüyor?", "Örtünmenin amacı ile modanın ve gösterişin dili arasındaki gerilimi düşün."]] },
      10: { amac: "Tarihselci yoruma usul açısından bir cevap geliştirmek.", odak: "“Tanınıp eziyet görmesinler” ifadesi hükmün illeti midir?",
        not: "Usulcülere göre bir vasfın hükmün illeti olabilmesi için açık (zâhir) ve belirli (munzabıt) olması gerekir; yani varlığı veya yokluğu herkes tarafından tespit edilebilmelidir. Ahzâb 59'daki “Bu, onların tanınıp eziyet görmemeleri için daha uygundur” ifadesindeki “eziyet görmemek” vasfı ise kişiden kişiye, ortamdan ortama değişen, ölçülmesi zor bir durumdur. Ayrıca âyetteki “daha uygundur” (ednâ) kelimesi bir sebep bildirmekten çok bir faydayı ve tercihi bildirir. Bu yüzden usulcülerin çoğu bu ifadeyi hükmün illeti değil, hikmeti olarak görür; hikmet değişse de hüküm devam eder.",
        tedebbur: [["Bir vasfın “belirli” olması şartı, hükümlerin keyfî olarak değiştirilmesini nasıl engelliyor?", "Herkesin farklı değerlendirebileceği bir gerekçeye bağlanan bir hükmün, nasıl bir belirsizliğe yol açacağını düşün."], ["Hikmetin değişse de hükmün devam etmesi ilkesi, yolculukta namazı kısaltma örneğiyle nasıl açıklanabilir?", "Meşakkat olmasa bile yolcunun namazı kısaltabildiğini, çünkü hükmün meşakkate değil yolculuğa bağlandığını düşün."]] },
      11: { amac: "Zaruret ve ihtiyaç hâllerinde tesettürün sınırlarını öğrenmek.", odak: "Tedavi için tesettürden ne ölçüde taviz verilebilir?",
        not: "Fakihler, tedavi gibi ihtiyaç hâllerinde tesettür hükümlerinin zaruret ölçüsünde gevşeyebileceğini kabul eder. Kâsânî gibi Hanefî fakihleri bunun için bir sıralama önerir: Mümkünse önce bir kadın hekime başvurulmalıdır; bulunamazsa bir erkek hekim, ancak tedavi için gerekli olan yere ve gerekli olduğu kadar bakabilir. Asr-ı saadette de kadınlar tedavi görevini üstlenmiştir: Rubeyyi' bint Muavviz, “Biz Resûlullah'la birlikte gazvelere çıkar, insanlara su verir, onlara hizmet eder, ölüleri ve yaralıları Medine'ye taşırdık” demiştir (Buhârî).",
        tedebbur: [["Önce kadın hekime başvurma tavsiyesi, bugün kadın hekimlerin yetişmesinin dinî bir ihtiyaç olduğu hakkında ne düşündürüyor?", "Bir hükmün gereğini yerine getirmek için gerekli imkânları oluşturmanın da bir sorumluluk olduğunu düşün."], ["Rubeyyi'nin anlattıkları, Asr-ı saadette kadınların kamusal hayattaki yeri hakkında ne söylüyor?", "Tesettürün, kadının topluma hizmet etmesine engel değil, onun bir çerçevesi olduğunu düşün."]] },
      12: { amac: "Kadın ve erkek kıyafetleri arasındaki ayrımın ölçüsünü öğrenmek.", odak: "Karşı cinse benzemenin ölçüsü nedir?",
        not: "Hz. Peygamber, “kadınlara benzeyen erkeklere ve erkeklere benzeyen kadınlara” lanet etmiştir (Buhârî). Bu hadisin ölçüsü üzerine İbn Teymiyye gibi âlimler önemli bir açıklama yapar: Kadın ve erkek kıyafetleri arasındaki ayrım, büyük ölçüde her toplumun örfüne göre belirlenir. Bir toplumda kadınlara özgü sayılan bir kıyafet, başka bir toplumda erkeklere özgü olabilir. Değişmeyen ölçü ise kadının daha çok örtünmesi ve iki cins arasındaki farkın korunmasıdır. Bu yaklaşım, nassın sabit amacı ile örfe bağlı uygulaması arasındaki ilişkinin bir başka örneğidir.",
        tedebbur: [["Karşı cinse benzeme yasağının örfe göre belirlenmesi, bir toplumun kıyafet anlayışını değerlendirirken nasıl bir dikkat gerektirir?", "Başka bir kültürün kıyafetini kendi örfüne göre yargılamanın hatasını düşün."], ["İki cins arasındaki farkın korunması neden önemli görülmüştür?", "Fıtrattaki farklılığın, toplumsal hayatta da bir anlam taşıdığını düşün."]] },
      13: { amac: "Kendi geleneğine karşı delile dayalı bir görüş savunan bir muhaddisi tanımak.", odak: "Bir âlim, kendi çevresinin görüşüne karşı çıkmalı mı?",
        not: "Elbânî, Cilbâbü'l-mer'eti'l-müslime adlı eserinde Müslüman kadının kıyafetinin taşıması gereken şartları sekiz maddede toplar: Bütün bedeni (yüz ve eller hariç) örtmesi, kendisinin bir süs olmaması, kalın olması, bol olması, kokulu olmaması, erkek kıyafetine benzememesi, inkârcı kadınların kendilerine özgü kıyafetlerine benzememesi ve bir şöhret elbisesi olmaması. Kitabın ilk baskısının adı Hicâbü'l-mer'eti'l-müslime idi; yüz örtüsünün farz olmadığı görüşü yüzünden kendi çevresinden sert eleştiriler alınca, bu eleştirilere er-Reddü'l-mufhim adlı ayrı bir eserle cevap vermiştir.",
        tedebbur: [["Elbânî'nin kendi çevresinin görüşüne karşı delile dayanarak farklı bir görüş savunması, ilmî bağımsızlık hakkında ne söylüyor?", "Bir grubun içinde olup onun yaygın görüşüne karşı çıkmanın zorluğunu düşün."], ["Bu yolun sonunda tesettürün amacını tek bir cümleyle nasıl ifade edersin?", "Haya, iffet, kimlik ve saygınlık kavramlarından hangisinin bu amacı en iyi anlattığını düşün."]] }
    },
    sentez: "Tesettür hakkında bir arkadaşının sorabileceği bir soruyu seç (örneğin “Başörtüsü gerçekten farz mı?” veya “Yüzü örtmek gerekir mi?”). Bu soruya, bu yolda öğrendiklerinle kısa bir cevap yaz: İlgili âyet ve hadisler, mezheplerin görüşleri ve bu görüşlerin arkasındaki usul gerekçesi. Sonunda tesettürün haya ahlâkıyla ilişkisini ve senin için ne ifade ettiğini bir paragrafla anlat." },
  faiz: {
    buyukResim: "Faiz, çoğu zaman yalnızca “banka faizi helal mi, haram mı?” sorusuna indirgenir. Kur'an ise ribâ yasağını daha geniş bir ahlâkın, ölçüde ve tartıda adaletin, malı biriktirip saymaya karşı uyarının ve helal kazancın bir parçası olarak anlatır. Bu yol, faizi bu bütünlük içinde ele alır. Önce Kur'an'ın ticaret ahlâkını ve rızık anlayışını görürsün. Sonra ribâ yasağını ve onun illetine dair tartışmaları, ardından ribâya götüren yolları ve hileleri öğrenirsin. En sonda katılım finansı, para vakıfları, ev kredisi, kripto ve sigorta gibi tarihî ve çağdaş meselelere geçer, borç ve ticaret hayatının edebiyle yolu tamamlarsın. Yolun sorusu şu: Ribâ yasağı neyi korumayı amaçlar ve bugün bu amaca nasıl sadık kalabiliriz?",
    hedefler: ["Ribâ yasağını Kur'an'ın adalet ve helal kazanç ahlâkı içinde konumlandırabilmek.", "Ribânın türlerini ve illeti konusundaki mezhep görüşlerini açıklayabilmek.", "Meşru çıkış yolları ile hileler arasındaki farkı ayırt edebilmek.", "Katılım finansı, kripto ve sigorta gibi çağdaş meseleleri klasik kavramlarla değerlendirebilmek."],
    sure: "Yaklaşık 3 hafta", onbilgi: "“Fıkıh Nasıl Düşünür?” ve “Modern Hayat ve Fıkıh” yolları faydalı bir hazırlıktır.",
    etaplar: [
      ["Kur'an'ın ticaret ahlâkı", 0, 2, "Ölçüde hile, malı biriktirip saymak ve rızkın kaynağını unutmak: Bu üç uyarı, ribâ yasağının hangi ahlâkî zemine dayandığını gösteriyor?"],
      ["Ribâ ve sınırları", 3, 7, "Ribânın illeti, ona götüren yolların kapatılması ve hilelerin eleştirisi, yasağın hem lafzını hem de ruhunu korumaya çalışır. Bu üç yaklaşımdan hangisi bugün en çok ihmal ediliyor?"],
      ["Tarihî ve çağdaş çözümler", 8, 12, "Murâbaha, para vakıfları, ev kredisi, kripto ve sigorta: Bu meselelerin her birinde ihtiyaç ile ilke arasında nasıl bir denge kuruluyor?"],
      ["Gündelik hayatın edebi", 13, 14, "Borç ve ticaret hayatının edebi, ribâ yasağının yalnızca büyük finans kurumlarını değil, senin gündelik ilişkilerini de ilgilendirdiğini nasıl gösteriyor?"]
    ],
    adim: {
      0: { amac: "Kur'an'ın ticaret ahlâkını bir sure üzerinden görmek.", odak: "Ölçüde ve tartıda küçük bir hile, neden bu kadar ağır bir uyarıyla karşılanıyor?",
        not: "Süveyd b. Kays'ın anlattığına göre Hz. Peygamber, Medine çarşısında bir satıcıdan şalvar satın alırken, tartıyla ücret karşılığında tartım yapan adama “Tart ve ağır bastır” buyurmuştur (Ebû Dâvûd, Tirmizî). Yani yalnızca eksik tartmamakla yetinmemiş, karşı tarafın lehine fazlasıyla tartmayı istemiştir. Ölçü ve tartı ahlâkının Kur'an'daki önemi, Hz. Şuayb'ın kıssasında da görülür: Medyen halkına gönderilen bu peygamberin davetinde tevhidden hemen sonra ölçü ve tartıyı tam yapmak gelir (Hûd 84-85). Kur'an böylece ticaret ahlâkını bir peygamber davetinin merkezine yerleştirir.",
        tedebbur: [["Bir surenin bir şehrin ticaret ahlâkını değiştirmesi, Kur'an'ın toplumsal hayata etkisi hakkında ne söylüyor?", "Bir âyetin, okunduğu toplumda somut bir davranış değişikliğine yol açmasının anlamını düşün."], ["Senin işinde, hakkında, zamanında veya hizmetinde “ölçüyü eksik tuttuğun” bir alan var mı?", "Müfessirlerin tatfîfi işte, hakta ve hizmette eksik vermeyi de kapsayacak şekilde genişlettiğini hatırla."]] },
      1: { amac: "Malı biriktirmenin ahlâkî boyutunu görmek.", odak: "Zekâtı verilmiş mal da “biriktirilmiş” sayılır mı?",
        not: "Zeyd b. Vehb'in anlattığına göre Rebeze'de Ebû Zerr'e oraya neden geldiğini sordu. Ebû Zerr, Şam'dayken Muâviye ile Tevbe 34'teki “Altın ve gümüşü biriktirip Allah yolunda harcamayanlar” âyeti hakkında tartıştıklarını anlattı: Muâviye âyetin Ehl-i kitap hakkında olduğunu söylemiş, Ebû Zerr ise hem onlar hem de Müslümanlar hakkında olduğunu savunmuştu (Buhârî). Ebû Zerr, ihtiyaç fazlası malın biriktirilmesini bu âyetin kapsamında görüyordu. Cumhur ise İbn Ömer'in “Zekâtı verilen mal, toprağın altında da olsa kenz (biriktirilmiş hazine) değildir” sözünü esas almıştır.",
        tedebbur: [["Ebû Zerr'in sıkı tavrı ile cumhurun görüşü arasındaki fark, zekâtın bir alt sınır mı yoksa bir üst sınır mı olduğu hakkında ne düşündürüyor?", "Zekâtı vermenin farz olanı yerine getirmek olduğunu, ama cömertliğin bununla sınırlı olmadığını düşün."], ["Hümeze suresindeki “malını sayıp duran” insan tasviri, malın insanın kalbinde nasıl bir yer edindiğini gösteriyor?", "Malı saymanın, ona güvenmenin bir işareti olduğunu ve “malının kendisini ebedî kılacağını sanmak” ile ilişkisini düşün."]] },
      2: { amac: "Rızık arama ile tevekkül arasındaki dengeyi görmek.", odak: "Tevekkül, rızık için çalışmayı gereksiz kılar mı?",
        not: "Hz. Ömer'e nispet edilen bir olayda, mescitte ibadete dalıp çalışmayı bırakmış bir grubu görür ve onlara kim olduklarını sorar. “Biz mütevekkilleriz” deyince şöyle der: “Hayır, siz mütevekkil değil, başkalarının sırtından geçinenlersiniz (müteakkil). Hiçbiriniz ‘Allah'ım bana rızık ver’ deyip rızık aramaktan geri durmasın; bilir ki gökten altın ve gümüş yağmaz.” Bu söz, tevekkülün çalışmayı terk etmek değil, çalışırken kalbi Allah'a bağlamak olduğunu, helal kazanç için çalışmanın da bir ibadet olduğunu vurgular.",
        tedebbur: [["Tevekkül ile tembellik arasındaki farkı kendi hayatından bir örnekle nasıl açıklarsın?", "Sebeplere sarılıp sonucu Allah'a bırakmak ile sebepleri terk edip sonucu beklemek arasındaki farkı düşün."], ["Helal kazanç için çalışmayı bir ibadet olarak görmek, işine bakışını nasıl değiştirebilir?", "Gündelik işini Allah'ın rızasını gözeterek yapmanın, onu nasıl bir ibadete dönüştürebileceğini düşün."]] },
      3: { amac: "Ribâ yasağının Kur'an'daki aşamalarını ve ahlâkî zeminini görmek.", odak: "Kur'an ribâyı ilk kez nasıl anlatır?",
        not: "Kur'an'da ribâdan söz eden ilk âyet Mekkî bir suredeki Rûm 39'dur: “İnsanların mallarında artsın diye verdiğiniz ribâ, Allah katında artmaz. Allah'ın rızasını dileyerek verdiğiniz zekâta gelince, işte onlar kat kat artıranlardır.” Bu âyet henüz bir yasak koymaz; ribâ ile zekâtı karşılaştırarak ahlâkî bir uyarı yapar. Medine'de inen Bakara 276'da da aynı karşıtlık tekrarlanır: “Allah ribâyı mahveder, sadakaları ise artırır.” Ribâ yasağı böylece bir ahlâkî karşılaştırmayla başlamış, sonra kesin bir yasağa dönüşmüştür: Görünüşte artan ribâ gerçekte eksiltir, görünüşte eksilten sadaka gerçekte artırır.",
        tedebbur: [["Ribânın “görünüşte artırıp gerçekte eksiltmesi”, sadakanın ise “görünüşte eksiltip gerçekte artırması” ne anlama geliyor?", "Bir toplumdaki servetin, ribâ ile birkaç elde toplanmasının ve sadaka ile dağılmasının sonuçlarını düşün."], ["Ribâ yasağının önce bir ahlâkî uyarı olarak gelmesi, bu yasağın asıl amacı hakkında ne söylüyor?", "Yasağın yalnızca bir hukuk kuralı değil, bir toplum ahlâkı olduğunu düşün."]] },
      4: { amac: "Ribânın illeti tartışmasının günümüze etkisini görmek.", odak: "Kâğıt paraya ribâ hükümleri uygulanır mı?",
        not: "Şâfiî mezhebine göre altın ve gümüşteki ribâ illeti, onların “para olma” (semeniyye) niteliğidir; ancak bu illet yalnızca altın ve gümüşe özgüdür, başka şeylere geçmez. Usulde buna “kāsır (geçişsiz) illet” denir. Bu görüş modern dönemde önemli bir soruyu doğurmuştur: Kâğıt para altın veya gümüş olmadığına göre, ona ribâ hükümleri uygulanır mı? Bazı çağdaş yazarlar uygulanmayacağını savunmuştur. Uluslararası İslâm Fıkıh Akademisi ise 1986'daki kararında, kâğıt paraların para olma niteliğine sahip olduğunu ve ribâ, zekât ve diğer bütün hükümlerde altın ve gümüş gibi değerlendirileceğini kabul etmiştir.",
        tedebbur: [["Bir illetin “geçişsiz” mi “geçişli” mi olduğu tartışması, kâğıt paranın hükmünü nasıl belirliyor?", "Ribâ yasağının amacının, altın ve gümüşün maddesini mi yoksa para olma işlevini mi korumak olduğunu düşün."], ["Kâğıt paraya ribâ hükmünün uygulanmaması, yasağın amacını nasıl boşa çıkarırdı?", "Bugün hemen bütün para işlemlerinin kâğıt veya dijital parayla yapıldığını düşün."]] },
      5: { amac: "Ribâya götüren yolların kapatılmasını gündelik bir örnekle görmek.", odak: "Bir borçlunun verdiği hediye neden şüphelidir?",
        not: "Ebû Bürde, Medine'ye geldiğinde sahabi Abdullah b. Selâm ile görüştü. Abdullah ona şu tavsiyede bulundu: “Sen ribânın yaygın olduğu bir yerdesin. Birinden alacağın varsa ve o sana bir yük saman, bir yük arpa veya bir yük yonca hediye ederse, onu alma; çünkü o ribâdır” (Buhârî). Borç ilişkisinden kaynaklanan her türlü ek fayda, borç verenin borç karşılığında bir şey alması anlamına gelebilir. Âlimler, aralarında önceden bir hediyeleşme âdeti bulunan kişileri bu yasağın dışında tutar; çünkü o durumda hediye borçtan değil, dostluktan kaynaklanır.",
        tedebbur: [["Abdullah b. Selâm'ın tavsiyesi, borç ilişkilerinde ribânın ne kadar ince yollardan girebileceğini gösteriyor. Senin hayatında böyle ince bir durum var mı?", "Borç verdiğin birinden aldığın bir iyiliğin, borç ilişkisinden mi yoksa dostluktan mı kaynaklandığını düşün."], ["Önceden hediyeleşme âdeti olanların bu yasağın dışında tutulması, sedd-i zerâi' ilkesinin amacı hakkında ne söylüyor?", "İlkenin bütün hediyeleri değil, borç ilişkisinin doğurduğu menfaatleri hedeflediğini düşün."]] },
      6: { amac: "Hilenin Kur'an ve sünnetteki ibretlik örneklerini görmek.", odak: "Bir yasağı şeklen ihlal etmeden delmek mümkün müdür?",
        not: "Kur'an, “Cumartesi ashabı” kıssasında hilenin ibretlik bir örneğini anlatır: Cumartesi günü balık tutmaları yasaklanan bir kavim, Cumartesi ağlarını kurup Pazar günü topluyordu; böylece şeklen yasağı çiğnemeden onu deliyorlardı. Kur'an bu kavmin “aşağılık maymunlar” hâline getirildiğini bildirir (A'râf 163-166). Hz. Peygamber de şöyle buyurmuştur: “Allah Yahudileri kahretsin! İç yağları kendilerine haram kılınınca onu eritip sattılar ve parasını yediler” (Buhârî, Müslim). İbnü'l-Kayyim, bu iki örneği haram bir amaca şekilce meşru yollarla ulaşmanın Kur'an ve sünnetteki temel delilleri olarak gösterir.",
        tedebbur: [["Cumartesi ashabının hilesi ile bugün ribâ yasağını şeklen delen bazı finans uygulamaları arasında nasıl bir benzerlik var?", "Bir yasağın lafzına uyup amacını çiğnemenin, onu açıkça ihlal etmekten daha mı ağır olduğunu düşün."], ["Kendi hayatında bir kuralı “şeklen” yerine getirip ruhunu ihmal ettiğin bir durum var mı?", "Bir ibadeti veya bir sözü, amacını gözetmeden yalnızca şeklen yerine getirmenin anlamını düşün."]] },
      7: { amac: "Ekonomik adaletin piyasadaki boyutunu bir Hanbelî fakihten öğrenmek.", odak: "Fiyatlar serbest mi bırakılmalı, yoksa bir sınır mı konulmalı?",
        not: "Medine'de fiyatlar yükselince sahabe Hz. Peygamber'den fiyatlara bir sınır (narh) koymasını istedi. Hz. Peygamber şöyle buyurdu: “Fiyatları belirleyen, daraltan ve genişleten, rızık veren Allah'tır. Ben Rabbime, hiçbirinizin kan veya mal konusunda bir hak talebiyle beni takip etmediği bir hâlde kavuşmayı umuyorum” (Ebû Dâvûd, Tirmizî). İbnü'l-Kayyim, et-Turuku'l-hükmiyye'de bu hadisi yorumlar: Fiyatların arz ve talep gibi doğal sebeplerle yükseldiği durumlarda narh koymak zulümdür. Ancak tüccarların tekel oluşturduğu, malı stoklayarak fiyatları yapay olarak yükselttiği durumlarda adil bir narh koymak caiz, hatta vacip olabilir.",
        tedebbur: [["İbnü'l-Kayyim'in doğal fiyat artışı ile yapay fiyat artışı arasında yaptığı ayrım, bugünkü ekonomik tartışmalara nasıl bir ölçü sunuyor?", "Piyasanın serbestliği ile tüketicinin korunması arasındaki dengeyi düşün."], ["Hz. Peygamber'in “Hiçbirinizin bana bir hak talebiyle gelmeyeceği bir hâlde Rabbime kavuşmak istiyorum” sözü, yöneticilerin ekonomik kararlarındaki sorumluluğu hakkında ne söylüyor?", "Bir kararın, kimseyi haksız yere zarara uğratmaması gerektiğini düşün."]] },
      8: { amac: "Katılım finansının ideali olan ortaklık modelini görmek.", odak: "Faizsiz finansın asıl modeli satış mı, yoksa ortaklık mı?",
        not: "İmam Mâlik'in Muvatta'da naklettiğine göre Hz. Ömer'in oğulları Abdullah ve Ubeydullah, Irak'tan dönerken vali Ebû Mûsâ el-Eş'arî'den beytülmâle ait bir miktar parayı borç olarak aldılar. Bu parayla mal alıp Medine'de satarak kâr ettiler. Hz. Ömer, valinin bu borcu yalnızca kendi oğullarına verdiğini öğrenince kârın da beytülmâle verilmesini istedi. Meclisteki birinin “Keşke bunu bir mudârebe (kâr ortaklığı) yapsaydın” önerisi üzerine Hz. Ömer, ana parayı ve kârın yarısını beytülmâle aldı, diğer yarısını oğullarına bıraktı. Bu olay, sermaye ile emeğin kâr ve zararı paylaştığı mudârebe ortaklığının en önemli dayanaklarından biridir.",
        tedebbur: [["Mudârebede sermaye sahibi ile emek sahibinin kâr ve zararı paylaşması, faizli kredideki risk dağılımından nasıl farklıdır?", "Faizli kredide riskin tamamen borçluya yüklendiğini, mudârebede ise paylaşıldığını düşün."], ["Katılım bankalarının ortaklık yerine daha çok murâbahayı kullanması, ribâ yasağının amacını ne ölçüde gerçekleştiriyor?", "Şeklen faizsiz olmak ile riskin ve kazancın adil paylaşılması arasındaki farkı düşün."]] },
      9: { amac: "Osmanlı'daki para vakıfları tartışmasını ayrıntılı olarak görmek.", odak: "Bir toplumsal ihtiyaç, tartışmalı bir uygulamayı meşru kılar mı?",
        not: "Osmanlı'da yaygınlaşan para vakıfları, vakfedilen paranın “muâmele-i şer'iyye” denen ve görünüşte bir satış, gerçekte ise belirli bir getiri sağlayan işlemlerle işletilmesine dayanıyordu. Elde edilen gelir mahalle mekteplerine, camilere ve fakirlere harcanıyordu. Taşınır malın, özellikle paranın vakfedilmesinin caizliği İmam Züfer'den nakledilen bir görüşe dayandırıldı. Ebussuûd, bu vakıfların kaldırılmasının pek çok hayır kurumunu yok edeceğini, bunun da halka büyük zarar vereceğini savunarak onları caiz gördü. İmam Birgivî ise bu işlemlerin bir ribâ hilesi olduğunu ve paranın vakfının caiz olmadığını savunarak sert bir şekilde karşı çıktı.",
        tedebbur: [["Ebussuûd'un “bu vakıflar kaldırılırsa pek çok hayır kurumu yok olur” gerekçesi ile Birgivî'nin “bu bir ribâ hilesidir” itirazı arasındaki gerilimi nasıl değerlendiriyorsun?", "Bir uygulamanın topluma sağladığı fayda ile onun meşruiyetinin ayrı sorular olduğunu düşün."], ["Para vakıfları tartışması, bugünkü katılım bankacılığı tartışmalarıyla nasıl bir benzerlik taşıyor?", "Bir toplumsal ihtiyaca cevap verirken ribâ yasağının sınırlarını koruma çabasını düşün."]] },
      10: { amac: "Haramın yaygınlaştığı bir ortamda ihtiyacın hükmünü öğrenmek.", odak: "Helalin bulunması zorlaştığında ne yapılmalı?",
        not: "Cüveynî, Ğıyâsü'l-ümem adlı eserinde dikkat çekici bir varsayım üzerinde durur: Bir zamanda haram, insanların ellerindeki mallara o kadar yayılır ki helal mal neredeyse bulunamaz hâle gelirse ne olur? Cüveynî'ye göre böyle bir durumda insanlar yalnızca canlarını kurtaracak kadar (zaruret ölçüsünde) değil, normal bir hayat sürdürmelerine yetecek kadar (hâcet ölçüsünde) bu mallardan faydalanabilir; çünkü aksi takdirde toplum çöker. Ancak lüks ve israf için faydalanmak caiz değildir. Bu görüş, çağdaş dönemde faizin yaygın olduğu ekonomilerde yaşayan Müslümanların durumuna dair tartışmalarda sıkça hatırlanır.",
        tedebbur: [["Cüveynî'nin zaruret ile hâcet arasında yaptığı ayrım, ev kredisi gibi bir ihtiyacı değerlendirirken nasıl bir ölçü sunuyor?", "Bir evin “hayatı sürdürmek için gerekli” mi yoksa “lüks” mü olduğunu, kişinin durumuna göre düşün."], ["Bu tür ruhsatların kötüye kullanılmasını nasıl önleyebiliriz?", "Ruhsatın sınırını belirleyen ölçüleri ve kişinin kendi ihtiyacını dürüstçe değerlendirmesinin önemini düşün."]] },
      11: { amac: "Yeni bir varlığı değerlendirirken fayda-zarar dengesini kullanmak.", odak: "Bir şeyde fayda da varsa, zararı onu haram yapar mı?",
        not: "Bakara 219'da içki ve kumar hakkında şöyle buyrulur: “Sana içki ve kumarı soruyorlar. De ki: İkisinde de büyük bir günah ve insanlar için bazı faydalar vardır; ama günahları faydalarından daha büyüktür.” Bu âyet, bir şeyin hükmünü belirlerken yalnızca faydalarına veya yalnızca zararlarına değil, ikisinin dengesine bakmak gerektiğini gösterir. Âlimler bu âyetten “Zararı faydasından büyük olan şeyden kaçınılır” ilkesini çıkarır. Kripto varlıklar gibi yeni bir meselede de bu dengeyi kurmak gerekir: Bir teknolojinin faydaları ile onun spekülatif kullanımının kumara benzeyen zararlarını birbirinden ayırarak değerlendirmek.",
        tedebbur: [["Bakara 219'daki fayda-zarar dengesi yöntemi, kripto varlıklar hakkında bir değerlendirme yaparken nasıl uygulanabilir?", "Teknolojinin kendisi ile onun kumar benzeri kullanımlarını ayırmayı düşün."], ["Hayatında, faydası olduğu hâlde zararı daha büyük olan bir alışkanlık var mı?", "Bu âyetin sana yalnızca finansal değil, kişisel bir muhasebe yöntemi de sunduğunu düşün."]] },
      12: { amac: "Toplumsal dayanışmanın kurumsal boyutunu bir sahabe uygulamasında görmek.", odak: "Bir toplumun ortak bir felakete karşı dayanışması nasıl örgütlenir?",
        not: "Hz. Ömer döneminde, hicrî 18. yılda Hicaz'da büyük bir kıtlık yaşandı; bu yıla “Âmü'r-ramâde” (kül yılı) denir. Hz. Ömer bu dönemde devletin bütün imkânlarını seferber etti: Diğer bölgelerin valilerinden yiyecek yardımı istedi, Medine'de büyük sofralar kurdu ve kendisi de halk doyuncaya kadar et ve yağ yememeye yemin etti. Ayrıca kıtlık süresince hırsızlık cezasının uygulanmasını askıya aldı ve zekât toplamayı erteledi. Bu uygulama, ortak bir felakete karşı toplumsal dayanışmanın devlet eliyle örgütlenmesinin ve riskin topluma dağıtılmasının erken bir örneğidir.",
        tedebbur: [["Hz. Ömer'in halk doyuncaya kadar kendisinin de et yememesi, bir yöneticinin toplumsal felaketlerdeki tavrı hakkında ne söylüyor?", "Bir liderin, halkının sıkıntısını bizzat paylaşmasının anlamını düşün."], ["Âmü'r-ramâde uygulaması ile modern sosyal sigorta sistemleri arasında nasıl bir benzerlik görüyorsun?", "Riskin bir topluluk arasında paylaşılmasının, tekâfül fikriyle ilişkisini düşün."]] },
      13: { amac: "Borç ilişkisinin ahlâkını öğrenmek.", odak: "Borç alırken niyet neden bu kadar önemlidir?",
        not: "Hz. Peygamber şöyle buyurmuştur: “Kim insanların mallarını ödeme niyetiyle alırsa, Allah onun borcunu ödemesini kolaylaştırır. Kim de onları telef etme niyetiyle alırsa, Allah onu telef eder” (Buhârî). Bu hadis, borç ilişkisini yalnızca bir hukukî işlem değil, bir niyet ve güven meselesi olarak tanımlar. Ödeme niyetiyle borç alan kişi, zorluklarla karşılaşsa bile ilâhî bir yardımın vaadini taşır. Ödemeyi baştan düşünmeyen ise başkasının hakkını telef etmeye niyet ettiği için kendi helakini hazırlar.",
        tedebbur: [["Borç alırken ödeme niyetinin Allah'ın yardımına vesile olması, borç ilişkisinde niyetin gücü hakkında ne söylüyor?", "Bir borcu ödeme planı yaparak almak ile “bir şekilde öderim” diyerek almak arasındaki farkı düşün."], ["Borç vermenin sevabı ile borcun ağırlığı arasındaki dengeyi nasıl kuruyorsun?", "Hem borç vererek yardım etmenin hem de borçlanmaktan kaçınmanın değerini düşün."]] },
      14: { amac: "Ticaret hayatında ilmin gerekliliğini görmek.", odak: "Ticaret yapmak için hangi bilgiye sahip olmak gerekir?",
        not: "Hz. Ömer'in şöyle dediği nakledilir: “Dinde fakih olmayan, çarşımızda satış yapmasın” (Tirmizî). Bu söz, ticaret ile ilim arasındaki sıkı bağı gösterir: Alım satımın hükümlerini, ribânın türlerini ve haram işlemleri bilmeyen bir tüccar, farkında olmadan ribâya ve haksız kazanca düşebilir. Osmanlı'da da esnaf loncaları, mesleğe girenlere meslekî becerinin yanında ticaret ahlâkını ve ilgili fıkıh bilgisini de öğretirdi. Ahi geleneği bu anlayışın bir ifadesidir.",
        tedebbur: [["Hz. Ömer'in “dinde fakih olmayan satış yapmasın” sözü, kendi mesleğinin dinî hükümlerini bilmenin bir sorumluluk olduğunu nasıl gösteriyor?", "Kendi mesleğinde karşılaşabileceğin dinî soruları ve bunları kime soracağını düşün."], ["Bu yolun sonunda, kendi mali hayatında ribâ yasağının amacına uygun hangi adımı atabilirsin?", "Borç, yatırım, alışveriş veya bağış alanlarında somut bir karar düşün."]] }
    },
    sentez: "Kendi hayatından veya çevrenden bir mali durumu seç (örneğin bir ev alma kararı, bir yatırım, bir borç ilişkisi veya bir iş anlaşması). Bu durumu bu yolda öğrendiklerinle değerlendir: Ribâ yasağının hangi yönüyle ilgili? Bir hile veya sedd-i zerâi' meselesi var mı? Zaruret veya hâcet ölçüsü uygulanabilir mi? Sonunda, ribâ yasağının amacına uygun olarak nasıl davranacağını yaz." },

  yaratilis: {
    buyukResim: "Kur'an, insanı sürekli olarak bakmaya ve düşünmeye çağırır: göğe, yere, dağlara, devenin yaratılışına ve kendi yaratılışına. Bu yol, bu çağrının izinden gider. Önce Kur'an'ın kısa surelerde kâinatı ve insanı nasıl bir tefekkür konusu hâline getirdiğini görürsün. Sonra kelâmcıların âlemin yaratılmış olduğuna dair delillerini ve Mâtürîdî'nin kâinattaki düzenden Allah'a ulaşan akıl yürütmesini öğrenirsin. Ardından insanın yaratılışı ve evrim tartışmasına girersin. En sonda sebeplilik, tabiat ve yaratma arasındaki ilişkiyi Gazâlî, İbn Rüşd, Râzî ve Said Nursi üzerinden değerlendirirsin. Yolun sorusu şu: Kâinata baktığımda ne görüyorum?",
    hedefler: ["Kur'an'ın kâinat ve insan hakkındaki tefekkür çağrısını kısa sureler üzerinden kavrayabilmek.", "Kelâmcıların âlemin yaratılmışlığına dair delillerini açıklayabilmek.", "İnsanın yaratılışı ve evrim tartışmasındaki farklı görüşleri değerlendirebilmek.", "Bilimsel açıklamalar ile yaratılış inancı arasında tutarlı bir ilişki kurabilmek."],
    sure: "Yaklaşık 3 hafta", onbilgi: "Gerekmez.",
    etaplar: [
      ["Kur'an'ın tefekkür çağrısı", 0, 5, "Deveye, göğe, yere ve insanın kendi yaratılışına bakmak: Kur'an neden bu kadar sık “bakmazlar mı?” diye sorar? Bu sorunun cevabı, senin gündelik bakışını nasıl değiştirebilir?"],
      ["Kelâmın delilleri", 6, 8, "Hudûs delili, Mâtürîdî'nin düzen delili ve fıtrat, insanın Allah'ı akılla ve kalple tanıyabileceğini gösterir. Bu üç yol birbirini nasıl tamamlıyor?"],
      ["İnsanın yaratılışı", 9, 9, "Âdem'in yaratılışı ve evrim tartışmasında hangi görüşü en tutarlı buldun? Bu tercihin hangi usul ilkesine dayanıyor?"],
      ["Sebepler ve yaratma", 10, 14, "Gazâlî sebeplerin kendi başına etkisini reddetti, İbn Rüşd sebepleri savundu, Râzî kâinattaki delilleri saydı, Said Nursi ise tabiatın yaratıcı olamayacağını gösterdi. Bilimin “nasıl” sorusu ile imanın “kim” ve “niçin” soruları arasında nasıl bir ilişki kuruyorsun?"]
    ],
    adim: {
      0: { amac: "Kur'an'ın tefekküre çağırma yöntemini görmek.", odak: "“Bakmazlar mı?” sorusu, hangi bakışa davet ediyor?",
        not: "Müfessirlerin naklettiğine göre tâbiûn neslinin meşhur kadısı Şureyh, Gâşiye 17. âyeti okuduktan sonra yanındakilere “Haydi çıkalım da devenin nasıl yaratıldığına bakalım” dermiş. Âyetteki “bakmak” (nazar) fiili, kelâmcılar tarafından yalnızca gözle görmek değil, gördüğü şey üzerinde düşünmek ve ondan bir sonuç çıkarmak olarak anlaşılmıştır. Bu yüzden kelâmcıların çoğu, Allah'ı tanımak için kâinat üzerinde düşünmeyi (nazar ve istidlâl) bir görev olarak görmüş ve bu görüşlerine bu tür âyetleri delil göstermiştir.",
        tedebbur: [["Şureyh'in “devenin nasıl yaratıldığına bakalım” davetini bugün kendi hayatına nasıl uygulayabilirsin?", "Her gün gördüğün ama hiç üzerinde düşünmediğin bir varlığı seçip ona yeniden bakmayı düşün."], ["Bakmak ile görmek arasındaki fark nedir? Kur'an neden yalnızca “görmüyorlar mı?” değil, “bakmıyorlar mı?” diye soruyor?", "Bakmanın bir dikkat ve yöneliş gerektirdiğini düşün."]] },
      1: { amac: "Yaratılıştan dirilişe uzanan delili görmek.", odak: "Kâinattaki düzen, öldükten sonra dirilişin nasıl bir delilidir?",
        not: "Müşriklerden biri, çürümüş bir kemiği alıp Hz. Peygamber'in yanına gelmiş ve onu elinde ufalayarak “Ey Muhammed! Allah bunu çürüdükten sonra diriltecek mi?” diye sormuştur. Bunun üzerine Yâsîn suresinin son âyetleri inmiştir: “Kendi yaratılışını unutarak bize bir misal getirdi ve ‘Çürümüşken bu kemikleri kim diriltecek?’ dedi. De ki: Onları ilk defa yaratan diriltecek; O her türlü yaratmayı bilendir” (Yâsîn 78-79). Nebe' suresi de dirilişi bu aynı akıl yürütmeyle anlatır: Yeri döşek, dağları kazık yapan, insanları çiftler hâlinde yaratan Allah'ın onları yeniden diriltmesi zor değildir.",
        tedebbur: [["“Kendi yaratılışını unutarak” ifadesi, dirilişi inkâr eden kişinin hangi şeyi gözden kaçırdığını gösteriyor?", "Hiç yokken var olmanın, yeniden var olmaktan daha şaşırtıcı olduğunu düşün."], ["Kâinattaki düzen ile âhiret inancı arasında nasıl bir bağ kuruyorsun?", "Bu kadar düzenli bir kâinatın, sonunda her şeyi anlamsız bir yokluğa terk etmesinin hikmetle bağdaşıp bağdaşmayacağını düşün."]] },
      2: { amac: "Kur'an'ın insanın yaratılışına dair anlatımını doğru okumak.", odak: "Kur'an'daki yaratılış âyetleri bir biyoloji dersi midir?",
        not: "Târık 5-7'de insanın, bel ile göğüs kemikleri arasından çıkan atılan bir sudan yaratıldığı anlatılır. Müfessirler bu âyetteki ifadeleri farklı şekillerde açıklamıştır. Modern dönemde ise bu tür âyetleri çağdaş bilimsel bulgularla birebir eşleştirmeye çalışan “ilmî tefsir” yaygınlaşmıştır. Şâtıbî ise el-Muvâfakāt'ta önemli bir uyarıda bulunur: Kur'an, ilk muhataplarının, yani Arapların anlayabileceği bir dille ve onların bildiği kavramlarla inmiştir. Ona, onların bilmediği ilimleri yüklemek doğru değildir. Bu âyetlerin asıl amacı, insana kendi yaratılışının basitliğini ve Allah'ın kudretini hatırlatarak onu tefekküre ve tevazuya çağırmaktır.",
        tedebbur: [["Şâtıbî'nin uyarısı, Kur'an'daki âyetleri bilimsel teorilerle birebir eşleştirme eğilimine nasıl bir sınır çiziyor?", "Bir âyeti bugünkü bir teoriye bağlamanın, o teori değiştiğinde ne gibi bir sorun doğuracağını düşün."], ["Târık suresinin “insan neden yaratıldığına bir baksın” çağrısı, sende nasıl bir duygu uyandırıyor?", "Kendi yaratılışının basit bir başlangıcını düşünmenin, kibri nasıl kırabileceğini düşün."]] },
      3: { amac: "İnsanın yaratılışının bir cömertlik eseri olduğunu görmek.", odak: "Allah'ın cömertliği, insanı neden gaflete düşürüyor?",
        not: "İnfitâr 6'daki “Ey insan! Seni, kerem sahibi Rabbine karşı ne aldattı?” âyetine, âlimlerden ilginç cevaplar nakledilir. Hz. Ömer'in bu âyeti okuyunca “Cehaleti onu aldattı” dediği rivayet edilir. Fudayl b. İyâz'ın ise şöyle dediği nakledilir: “Eğer Rabbim bana ‘Seni ne aldattı?’ diye sorsa, ‘Senin üzerime saldığın perdelerin (setrin) beni aldattı’ derim.” Yani Allah'ın günahları örtmesi ve hemen cezalandırmaması, insanı gaflete düşürmüştür. Âyetin “kerîm” ismini seçmesi de bunu ima eder: İnsan, tam da Allah'ın cömertliğine güvenerek O'na karşı gafil olmuştur.",
        tedebbur: [["Fudayl'ın cevabı, Allah'ın günahları örtmesinin bir imtihan olduğunu nasıl gösteriyor?", "Bir hatanın hemen cezalandırılmamasının, onu tekrarlamaya mı yoksa ondan dönmeye mi vesile olduğunu düşün."], ["Allah'ın cömertliğini bir gaflet sebebi değil, bir şükür sebebi yapmak için ne yapabilirsin?", "Sana verilen nimetleri ve örtülen kusurlarını düşünerek bir şükür hissi uyandırmayı dene."]] },
      4: { amac: "İnsanın yaratılıştaki onurunu görmek.", odak: "“En güzel kıvamda yaratılmak” insana nasıl bir sorumluluk yükler?",
        not: "Hz. Peygamber şöyle buyurmuştur: “Biriniz kardeşiyle kavga ederse yüze vurmaktan sakınsın; çünkü Allah Âdem'i kendi sûreti üzere yaratmıştır” (Müslim). Bu hadisteki “kendi sûreti” ifadesindeki zamirin kime döndüğü âlimler arasında tartışılmıştır: Bir kısmına göre Âdem'in kendi sûreti, yani Allah'ın ona en başından verdiği tam ve olgun suret kastedilir. Bir kısmına göre ise Allah'a ait bir izafettir ve “Allah'ın şerefli kıldığı suret” anlamına gelir. Her iki yorumda da hadisin pratik sonucu açıktır: İnsan yüzü, kavga anında bile saygı gösterilmesi gereken bir onur taşır.",
        tedebbur: [["Yüze vurmanın yasaklanmasının insan onuruyla ilişkilendirilmesi, “ahsen-i takvîm” kavramını nasıl somutlaştırıyor?", "En öfkeli anda bile karşındakinin onurunu korumanın ne anlama geldiğini düşün."], ["En güzel kıvamda yaratılan insanın “aşağıların aşağısına” düşmesi neyle olur?", "Tîn suresindeki istisnanın, iman ve salih amelin bu düşüşe karşı bir koruma olduğunu düşün."]] },
      5: { amac: "Kur'an'daki tefekkür çağrısının Hz. Peygamber'in hayatındaki yansımasını görmek.", odak: "Kâinat âyetleri üzerinde düşünmemek neden kınanıyor?",
        not: "İbn Hibbân'ın Hz. Âişe'den naklettiğine göre, Hz. Peygamber bir gece namazda o kadar ağladı ki gözyaşları sakalını ve secde yerini ıslattı. Sabah ezanını okumaya gelen Bilâl onu bu hâlde görünce sebebini sordu. Hz. Peygamber şöyle buyurdu: “Bu gece bana bazı âyetler indi. Onları okuyup da üzerinde düşünmeyene yazıklar olsun!” Bu âyetler, akıl sahiplerini ayakta, otururken ve yatarken Allah'ı anmaya ve kâinatın yaratılışı üzerinde düşünmeye çağıran Âl-i İmrân 190-191 idi.",
        tedebbur: [["Hz. Peygamber'in bu âyetleri okuyup düşünmeyene “yazıklar olsun” demesi, tefekkürü bir tercih değil, bir görev hâline getiriyor mu?", "Kâinatı seyrederken onun bir anlam taşıdığını düşünmeden geçmenin, bir fırsatı kaçırmak olduğunu düşün."], ["Âyette tefekkürün zikirle (ayakta, otururken ve yatarken Allah'ı anmak) birlikte anılması, düşünce ile ibadet arasındaki ilişki hakkında ne söylüyor?", "Kâinatı düşünmenin bir bilgi edinme değil, bir ibadet olabileceğini düşün."]] },
      6: { amac: "Âlemin yaratılmışlığına dair kelâm delilinin Kur'an'daki kökünü görmek.", odak: "Değişen bir şey ilah olabilir mi?",
        not: "Kelâmcılar hudûs delilinin Kur'an'daki aslını Hz. İbrâhim'in kıssasında bulur (En'âm 76-79). Hz. İbrâhim önce bir yıldıza, sonra aya, sonra güneşe bakar; her biri batınca “Ben batanları sevmem” der ve sonunda yüzünü “gökleri ve yeri yaratana” çevirir. Kelâmcılara göre buradaki akıl yürütme şudur: Batan, yani değişen, bir hâlden bir hâle geçen şey bir başkasının etkisi altındadır ve yaratılmıştır; yaratılmış olan ise ilah olamaz. Nesefî Akāid'deki “âlem, bütün parçalarıyla hâdistir” cümlesi de bu akıl yürütmenin sistemleşmiş bir ifadesidir.",
        tedebbur: [["Hz. İbrâhim'in “Ben batanları sevmem” sözü, sevginin de akıl yürütme kadar imanın bir unsuru olduğunu nasıl gösteriyor?", "Kalıcı olmayan bir şeye kalbini bağlamanın, insana nasıl bir hayal kırıklığı getirdiğini düşün."], ["Senin hayatında “batan” ve kalıcı olmayan şeylere bağlandığın durumlar var mı?", "Geçici olana bağlanmanın bir tür kalp yanılgısı olduğunu düşün."]] },
      7: { amac: "Kâinattaki düzenden Allah'a ulaşan bir akıl yürütmeyi tanımak.", odak: "Zıtların bir arada bulunması neyi gösterir?",
        not: "Mâtürîdî, Kitâbü't-Tevhîd'de Allah'ın varlığına dair delillerinden birini kâinattaki zıtların bir araya gelmesine dayandırır: Âlemde sıcak ile soğuk, ıslak ile kuru, ışık ile karanlık gibi birbirine zıt tabiatlar bir arada bulunur ve uyum içinde işler. Zıt şeylerin tabiatı birbirinden kaçmak ve birbirini yok etmektir; onların kendiliğinden bir araya gelip bir düzen oluşturması mümkün değildir. Öyleyse onları bir araya getiren, bilgi ve hikmet sahibi bir yaratıcı vardır. Bu delil, kâinattaki düzenin ve dengenin kendi kendine açıklanamayacağını gösteren bir akıl yürütmedir.",
        tedebbur: [["Zıtların bir arada uyum içinde bulunması, kendi bedeninde ve çevrende nasıl gözlemlenebilir?", "Vücudundaki sıcaklık dengesini veya bir ekosistemdeki av ve avcı dengesini düşün."], ["Mâtürîdî'nin delili, kâinata bakarken düzeni fark etmenin imanla nasıl ilişkili olduğunu gösteriyor?", "Düzeni bir tesadüf olarak görmek ile bir hikmetin eseri olarak görmek arasındaki farkı düşün."]] },
      8: { amac: "Fıtratın korunması ve değiştirilmesi tartışmasını görmek.", odak: "Allah'ın yaratışı değiştirilebilir mi?",
        not: "Rûm 30'da “Allah'ın yaratışında değişiklik yoktur” (lâ tebdîle li-halkillâh) denir. Müfessirler bu ifadeyi iki şekilde anlamıştır: Bir haber olarak, Allah'ın insanı üzerinde yarattığı fıtratın özünün değişmeyeceği; veya bir emir olarak, “Allah'ın yaratışını değiştirmeyin” anlamında. Nisâ 119'da ise şeytanın insanlara “Allah'ın yaratışını değiştirmelerini emredeceği” bildirilir. Bu âyetler, bugün estetik ameliyatlar, genetik müdahaleler ve cinsiyet değişikliği gibi konulardaki tartışmalarda temel dayanaklardan biri olmuştur. Âlimler, tedavi amaçlı müdahaleler ile yalnızca görünüşü değiştirme veya fıtrata aykırı müdahaleler arasında ayrım yapar.",
        tedebbur: [["Tedavi amaçlı bir müdahale ile Allah'ın yaratışını değiştirme arasındaki sınırı nasıl çizersin?", "Bir eksikliği gidermek ile sağlıklı bir yaratılışı değiştirmek arasındaki farkı düşün."], ["“Allah'ın yaratışında değişiklik yoktur” ifadesi, insanın özünün teknolojiyle değiştirilemeyeceği hakkında ne söylüyor?", "İnsanın bedenini değiştirebilen teknolojinin, onun fıtratını ve ruhunu değiştirip değiştiremeyeceğini düşün."]] },
      9: { amac: "Âdem'in yaratılışını meleklerle olan diyaloğun ışığında okumak.", odak: "Melekler, henüz yaratılmamış insanın bozgunculuk yapacağını nereden bildi?",
        not: "Allah meleklere yeryüzünde bir halife yaratacağını bildirdiğinde, melekler “Orada bozgunculuk yapacak ve kan dökecek birini mi yaratacaksın?” diye sordular (Bakara 30). Müfessirler meleklerin bunu nereden bildiği sorusuna farklı cevaplar verir: Bir görüşe göre Allah onlara bunu önceden bildirmiştir. İbn Abbâs'tan nakledilen bir görüşe göre ise yeryüzünde insandan önce cinler yaşamış, bozgunculuk yapıp kan dökmüştü; melekler insanı da onlara kıyas etmişti. Bu yorum, Âdem'den önce yeryüzünde başka varlıkların bulunduğu fikrinin klasik tefsirde de yer aldığını gösterir. Allah'ın cevabı ise “Ben sizin bilmediğinizi bilirim” olmuştur.",
        tedebbur: [["Meleklerin sorusu bir itiraz mı, yoksa hikmeti anlama isteği mi?", "Allah'a soru sormak ile O'nun kararına itiraz etmek arasındaki farkı düşün."], ["“Ben sizin bilmediğinizi bilirim” cevabı, insanın yaratılışındaki hikmetin meleklerin bile bilgisini aştığı hakkında ne söylüyor?", "İnsanın hem bozgunculuk hem de en yüksek iyilik kapasitesine sahip olmasının anlamını düşün."]] },
      10: { amac: "Gazâlî'nin yaratılmışlar üzerine tefekkür kitabını tanımak.", odak: "Bir arının veya bir gözün yaratılışı üzerinde düşünmek neyi gösterir?",
        not: "Gazâlî'ye nispet edilen el-Hikme fî mahlûkātillâh (Allah'ın Yarattıklarındaki Hikmet) adlı eser, gökten başlayarak güneş, ay, yağmur, deniz, bitkiler, kuşlar, arılar, karıncalar ve en sonda insanın yaratılışındaki hikmetleri ayrı ayrı anlatır. Gazâlî'nin Tehâfüt'te sebeplerin kendi başına etkili olmadığını savunması, onun kâinattaki düzene ilgisiz olduğu anlamına gelmez; aksine bu eserde, her varlıktaki inceliği ve amaca uygunluğu Allah'ın hikmetinin bir delili olarak gösterir. Gazâlî'ye göre sebepler Allah'ın âdetidir; bu âdeti incelemek, O'nun hikmetini tanımaktır.",
        tedebbur: [["Gazâlî'nin sebeplerin bağımsız etkisini reddetmesi ile yaratılmışlardaki hikmeti incelemesi arasında bir çelişki var mı?", "Sebeplerin Allah'ın bir âdeti olarak incelenmesinin, onların O'nu gösteren işaretler olduğunu düşün."], ["Sen bir varlığın yaratılışındaki inceliği fark ettiğinde, bunu bir bilimsel merak olarak mı, yoksa bir tefekkür vesilesi olarak mı yaşıyorsun?", "Bilimsel merakın da bir tefekküre dönüşebileceğini düşün."]] },
      11: { amac: "Kur'an'ın Allah'ın varlığına dair delillerini bir filozofun gözünden görmek.", odak: "Kur'an Allah'ın varlığını hangi tür delillerle gösterir?",
        not: "İbn Rüşd, el-Keşf an menâhici'l-edille adlı eserinde Kur'an'ın Allah'ın varlığına dair delillerini iki ana türe ayırır. Birincisi “inâyet delili”dir: Kâinattaki her şeyin insanın varlığına ve ihtiyaçlarına uygun olarak düzenlenmesi; gece ile gündüzün, güneşin, yağmurun ve hayvanların insana hizmet etmesi. İkincisi “ihtirâ (yaratma) delili”dir: Canlıların ve hayatın yoktan var edilmesi; özellikle cansız maddeden hayatın ortaya çıkması. İbn Rüşd'e göre bu deliller, kelâmcıların karmaşık delillerinden farklı olarak, hem avamın hem de âlimlerin anlayabileceği bir sadelik ve güçtedir.",
        tedebbur: [["İnâyet delilini kendi hayatına uygula: Kâinatta senin varlığına uygun olarak düzenlenmiş hangi şeyleri fark ediyorsun?", "Suyun, havanın, güneşin ve yiyeceklerin varlığının senin ihtiyaçlarına ne kadar uygun olduğunu düşün."], ["İbn Rüşd'ün Kur'an'ın delillerini herkesin anlayabileceği deliller olarak görmesi, imanın gerekçelerini anlatırken nasıl bir yöntem öneriyor?", "Karmaşık felsefi deliller yerine, herkesin gözünün önündeki gerçeklerden başlamanın gücünü düşün."]] },
      12: { amac: "Kur'an'ın kâinat âyetlerini kelâmî bir derinlikle okuyan bir müfessiri tanımak.", odak: "Tek bir âyette kaç delil bulunabilir?",
        not: "Râzî, Mefâtîhu'l-gayb'de Bakara 164'ü tefsir ederken âyeti Allah'ın varlığına ve birliğine dair delillerin bir hazinesi olarak ele alır: “Göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelişinde, insanlara fayda veren şeylerle denizde akıp giden gemilerde, Allah'ın gökten indirip onunla ölmüş toprağı dirilttiği suda, her türlü canlıyı yeryüzüne yaymasında, rüzgârları ve gökle yer arasında emre amade bulutları evirip çevirmesinde, akleden bir topluluk için deliller vardır.” Râzî bu âyette sayılan her bir varlığı ayrı ayrı inceler ve her birinin nasıl bir hikmet ve kudret delili olduğunu uzun uzun açıklar.",
        tedebbur: [["Bakara 164'te sayılan varlıklardan birini seç ve onun nasıl bir “delil” olduğunu düşün.", "Gemilerin denizde yüzmesinin veya rüzgârların yön değiştirmesinin arkasındaki düzeni düşün."], ["Âyetin “akleden bir topluluk için” ifadesiyle bitmesi, bu delillerin herkes için değil, düşünenler için delil olduğunu mu gösteriyor?", "Aynı manzaraya bakan iki insanın, birinin delil diğerinin sıradan bir olay görmesinin sebebini düşün."]] },
      13: { amac: "Tabiat ile yaratma arasındaki ilişkiyi modern bir dille görmek.", odak: "Tabiat yaratıcı olabilir mi?",
        not: "Said Nursi, Tabiat Risalesi'nin sonunda tabiatın ne olduğunu bir dizi benzetmeyle açıklar: “Tabiat, bir matbaadır, tâbi (basan) değil; bir nakıştır, nakkaş değil; bir kabildir, fâil değil; bir mistardır (cetvel), masdar (kaynak) değil; bir nizamdır, nâzım (düzenleyen) değil; bir kanundur, kudret değil; bir şeriat-ı iradiyedir, hakiki bir hakikat-i hariciye değil.” Bu benzetmelerin her biri, tabiatın bir düzen ve işleyiş biçimi olduğunu, ama bu düzeni koyan ve işleten güç olmadığını anlatır. Bir kanun, kendini uygulayamaz; onu uygulayan bir kudret gerekir.",
        tedebbur: [["“Tabiat bir kanundur, kudret değil” benzetmesi, bilimsel kanunlar ile yaratma arasındaki ilişkiyi nasıl açıklıyor?", "Yerçekimi kanununun, nesneleri kendisinin mi çektiğini, yoksa bir düzenin ifadesi mi olduğunu düşün."], ["Günlük dilde kullandığımız “tabiat ana” veya “doğa bunu yaptı” gibi ifadeler, düşüncemizi nasıl etkiliyor?", "Kullandığımız kelimelerin, farkında olmadan bir dünya görüşü taşıyabileceğini düşün."]] },
      14: { amac: "Yaratılış hakkındaki bilgiyi başkalarına nasıl anlatacağını düşünmek.", odak: "Hassas bir konuyu başkasıyla konuşurken nasıl bir dil kullanmalıyım?",
        not: "A'lâ suresinin “Öğüt fayda verirse öğüt ver” âyeti, öğüdün muhatabın durumunu gözeterek verilmesi gerektiğini anlatır. Hz. Ali de şöyle demiştir: “İnsanlara anlayabilecekleri şekilde konuşun. Allah ve Resûlünün yalanlanmasını ister misiniz?” (Buhârî). Yaratılış ve evrim gibi hassas konularda bu ilke özellikle önemlidir: Bilgisi ve hazırlığı olmayan birine, onun anlayamayacağı tartışmaları aktarmak, onu imandan uzaklaştırabilir. Aynı şekilde, bilimsel bir eğitim almış birine, onun aklına hitap etmeyen bir dille konuşmak da onu dinden soğutabilir.",
        tedebbur: [["Hz. Ali'nin “Allah ve Resûlünün yalanlanmasını ister misiniz?” uyarısı, yanlış bir anlatımın sonuçları hakkında ne söylüyor?", "İyi niyetli ama muhatabına uygun olmayan bir anlatımın, nasıl ters bir etki yapabileceğini düşün."], ["Bu yolun sonunda, yaratılış hakkındaki bir soruyu bir çocuğa ve bir üniversite öğrencisine nasıl farklı şekillerde anlatırdın?", "Aynı hakikati, muhatabın seviyesine göre farklı bir dille anlatmanın yollarını düşün."]] }
    },
    sentez: "Gökyüzünden, bir canlıdan veya kendi bedeninden bir varlık seç ve onu bir hafta boyunca gözlemle. Sonra şu soruları cevaplayan bir yazı yaz: Bu varlık hangi düzeni ve hikmeti gösteriyor? Kur'an'da onunla ilgili hangi âyet var? Bilim onun nasıl işlediğini nasıl açıklıyor ve bu açıklama senin imanınla nasıl bir ilişki içinde? Yazını, bu tefekkürün sende uyandırdığı bir duyguyla bitir." }
});
